var LESSONS=[
{id:'greet',title:'Greetings and introductions',ar:'السَّلَامُ عَلَيْكُمْ',
 points:['Muslims greet each other with the salaam, and the reply returns it.','مَا اسْمُكَ؟ asks a man his name. To a woman, say مَا اسْمُكِ؟','اِسْمِي means "my name". The ending ـِي means "my".','Say الْحَمْدُ لِلَّهِ (all praise is for Allah) when asked how you are.'],
 ex:[['السَّلَامُ عَلَيْكُمْ','as-salaamu alaykum','Peace be upon you'],['وَعَلَيْكُمُ السَّلَامُ','wa alaykumus-salaam','And upon you be peace'],['مَا اسْمُكَ؟','masmuka?','What is your name?'],['اِسْمِي خَالِدٌ','ismee Khaalidun','My name is Khalid'],['كَيْفَ حَالُكَ؟','kayfa haaluka?','How are you?'],['بِخَيْرٍ وَالْحَمْدُ لِلَّهِ','bikhayrin wal-hamdu lillaah','Well, and all praise is for Allah'],['مِنْ أَيْنَ أَنْتَ؟','min ayna anta?','Where are you from?'],['أَنَا مِنْ مَكَّةَ','ana min Makkata','I am from Makkah'],['جَزَاكَ اللهُ خَيْرًا','jazaakallaahu khayran','May Allah reward you with good'],['مَعَ السَّلَامَةِ','ma\'as-salaamah','Goodbye (go in safety)']],
 q:[{q:'What is the reply to السَّلَامُ عَلَيْكُمْ ?',o:['وَعَلَيْكُمُ السَّلَامُ','مَعَ السَّلَامَةِ','مَا اسْمُكَ؟'],why:'The reply returns the greeting: "And upon you be peace".'},
    {q:'What does كَيْفَ حَالُكَ؟ mean?',o:['How are you?','What is your name?','Where are you from?'],why:'كَيْفَ means "how" and حَالُكَ means "your condition".'},
    {q:'What does جَزَاكَ اللهُ خَيْرًا mean?',o:['May Allah reward you with good','All praise is for Allah','Peace be upon you'],why:'It is how a Muslim thanks someone.'}]},
{id:'hadha',title:'This is… (near)',ar:'هٰذَا / هٰذِهِ',
 points:['هٰذَا (haadhaa) points to something near that is masculine.','هٰذِهِ (haadhihi) is for feminine nouns. Most feminine nouns end in ة.','Arabic needs no word for "is" or "a" here. هٰذَا كِتَابٌ is word for word "This book".','Ask with مَا هٰذَا؟ (What is this?). For a yes or no question, put أَ in front.'],
 ex:[['هٰذَا كِتَابٌ','haadhaa kitaabun','This is a book'],['هٰذَا مَسْجِدٌ','haadhaa masjidun','This is a mosque'],['هٰذِهِ سَيَّارَةٌ','haadhihi sayyaaratun','This is a car'],['هٰذِهِ سَاعَةٌ','haadhihi saa\'atun','This is a watch'],['مَا هٰذَا؟ هٰذَا قَلَمٌ','maa haadhaa? haadhaa qalamun','What is this? This is a pen'],['أَهٰذَا بَيْتٌ؟ نَعَمْ، هٰذَا بَيْتٌ','a-haadhaa baytun? na\'am…','Is this a house? Yes, this is a house']],
 q:[{q:'Complete the sentence: ___ سَيَّارَةٌ',o:['هٰذِهِ','هٰذَا'],why:'سَيَّارَةٌ ends in ة so it is feminine and takes هٰذِهِ.'},
    {q:'What does مَا هٰذَا؟ mean?',o:['What is this?','Who is this?','Where is this?'],why:'مَا asks "what" about things.'},
    {q:'Which sentence says "This is a pen"?',o:['هٰذَا قَلَمٌ','هٰذِهِ قَلَمٌ','قَلَمٌ هٰذِهِ'],why:'قَلَمٌ is masculine, so it takes هٰذَا, and هٰذَا comes first.'}]},
{id:'dhalika',title:'That is… (far)',ar:'ذٰلِكَ / تِلْكَ',
 points:['ذٰلِكَ (dhaalika) points to something far that is masculine.','تِلْكَ (tilka) points to something far that is feminine.','مَنْ asks "who" about people. مَا asks "what" about things.'],
 ex:[['ذٰلِكَ بَيْتٌ','dhaalika baytun','That is a house'],['ذٰلِكَ نَجْمٌ','dhaalika najmun','That is a star'],['تِلْكَ شَجَرَةٌ','tilka shajaratun','That is a tree'],['تِلْكَ مَدْرَسَةٌ','tilka madrasatun','That is a school'],['هٰذَا مَسْجِدٌ وَذٰلِكَ بَيْتٌ','haadhaa masjidun wa dhaalika baytun','This is a mosque and that is a house'],['مَنْ ذٰلِكَ؟ ذٰلِكَ مُدَرِّسٌ','man dhaalika? dhaalika mudarrisun','Who is that? That is a teacher']],
 q:[{q:'Which word points to a far feminine thing?',o:['تِلْكَ','ذٰلِكَ','هٰذَا'],why:'تِلْكَ is the feminine word for "that".'},
    {q:'مَنْ is used to ask about…',o:['people','things','places'],why:'مَنْ means "who".'},
    {q:'What does ذٰلِكَ نَجْمٌ mean?',o:['That is a star','This is a star','That is a tree'],why:'ذٰلِكَ is "that" and نَجْمٌ is "a star".'}]},
{id:'al',title:'"A" and "the"',ar:'كِتَابٌ ← الْكِتَابُ',
 points:['A noun with tanween (the double mark ـٌ, sounding "un") is indefinite: كِتَابٌ is "a book".','Add الـ to make it definite: الْكِتَابُ is "the book".','A word never carries both. When الـ comes, tanween leaves and one dammah stays.'],
 ex:[['بَيْتٌ ← الْبَيْتُ','baytun → al-baytu','a house → the house'],['قَلَمٌ ← الْقَلَمُ','qalamun → al-qalamu','a pen → the pen'],['بَابٌ ← الْبَابُ','baabun → al-baabu','a door → the door'],['مَسْجِدٌ ← الْمَسْجِدُ','masjidun → al-masjidu','a mosque → the mosque'],['الْبَيْتُ جَمِيلٌ','al-baytu jameelun','The house is beautiful']],
 q:[{q:'What does الْكِتَابُ mean?',o:['the book','a book','this book'],why:'الـ makes the noun definite.'},
    {q:'Which spelling is correct?',o:['الْقَلَمُ','الْقَلَمٌ','قَلَمُ'],why:'With الـ the word ends in one dammah, never tanween.'},
    {q:'Tanween on a noun shows that it is…',o:['indefinite','definite','feminine'],why:'Tanween works like "a" or "an".'}]},
{id:'sunmoon',title:'Sun and moon letters',ar:'الشَّمْسُ وَالْقَمَرُ',
 points:['Before 14 "sun letters" the ل of الـ is written but not said. The next letter is doubled: الشَّمْسُ is ash-shamsu.','Before the other 14 "moon letters" the ل is said clearly: الْقَمَرُ is al-qamaru.','Sun letters: ت ث د ذ ر ز س ش ص ض ط ظ ل ن.'],
 ex:[['الشَّمْسُ','ash-shamsu','the sun'],['الرَّجُلُ','ar-rajulu','the man'],['النَّجْمُ','an-najmu','the star'],['الطَّالِبُ','at-taalibu','the student'],['الْقَمَرُ','al-qamaru','the moon'],['الْبَابُ','al-baabu','the door'],['الْمَسْجِدُ','al-masjidu','the mosque']],
 q:[{q:'How is الطَّالِبُ pronounced?',o:['at-taalibu','al-taalibu'],why:'ط is a sun letter, so the ل is silent and ط is doubled.'},
    {q:'Which word begins with a moon letter?',o:['الْبَابُ','الشَّمْسُ','النَّجْمُ'],why:'ب is a moon letter, so the ل is pronounced.'},
    {q:'In الشَّمْسُ the letter ل is…',o:['written but silent','pronounced clearly','not written'],why:'With sun letters the ل is written and skipped in speech.'}]},
{id:'jumlah',title:'A simple sentence',ar:'الْبَيْتُ كَبِيرٌ',
 points:['A basic sentence starts with a definite noun, the subject (مُبْتَدَأ).','Then comes an indefinite word that tells us about it (خَبَر).','Both end in dammah. The second part matches the first in gender.'],
 ex:[['الْبَيْتُ كَبِيرٌ','','The house is big'],['الْمَسْجِدُ قَرِيبٌ','','The mosque is near'],['الْمَاءُ بَارِدٌ','','The water is cold'],['السَّيَّارَةُ جَدِيدَةٌ','','The car is new'],['الْغُرْفَةُ نَظِيفَةٌ','','The room is clean'],['الدَّرْسُ سَهْلٌ','','The lesson is easy']],
 q:[{q:'What does الْمَاءُ بَارِدٌ mean?',o:['The water is cold','The cold water','A cold water'],why:'Definite noun then indefinite description makes a full sentence.'},
    {q:'Complete: السَّيَّارَةُ ___',o:['جَدِيدَةٌ','جَدِيدٌ'],why:'السَّيَّارَةُ is feminine, so the description takes ة too.'},
    {q:'The first part of this kind of sentence is called…',o:['مُبْتَدَأ','خَبَر','حَرْف'],why:'مُبْتَدَأ is the subject. خَبَر is the information about it.'}]},
{id:'jarr',title:'In, on, from, to',ar:'فِي · عَلَى · مِنْ · إِلَى',
 points:['فِي = in, عَلَى = on, مِنْ = from, إِلَى = to.','The noun after one of these ends in kasrah: الْبَيْتُ becomes فِي الْبَيْتِ.','أَيْنَ means "where".','مِنْ is read مِنَ before الـ.'],
 ex:[['الْكِتَابُ عَلَى الْمَكْتَبِ','','The book is on the desk'],['الطَّالِبُ فِي الْفَصْلِ','','The student is in the classroom'],['أَيْنَ الْقَلَمُ؟ الْقَلَمُ فِي الْحَقِيبَةِ','','Where is the pen? The pen is in the bag'],['ذَهَبَ إِلَى الْمَسْجِدِ','','He went to the mosque'],['خَرَجَ مِنَ الْبَيْتِ','','He went out of the house']],
 q:[{q:'After a preposition the noun ends in…',o:['kasrah','dammah','fathah'],why:'Prepositions make the following noun majroor.'},
    {q:'What does عَلَى mean?',o:['on','in','from'],why:'عَلَى الْمَكْتَبِ is "on the desk".'},
    {q:'Complete: ذَهَبَ ___ الْمَسْجِدِ',o:['إِلَى','مِنْ','عَلَى'],why:'"He went to the mosque" needs إِلَى.'}]},
{id:'damir',title:'I, you, he, she, we',ar:'أَنَا · أَنْتَ · هُوَ · هِيَ',
 points:['أَنَا = I, نَحْنُ = we.','أَنْتَ = you (to a man), أَنْتِ = you (to a woman).','هُوَ = he, هِيَ = she.'],
 ex:[['أَنَا طَالِبٌ','','I am a student'],['أَنْتَ مُدَرِّسٌ','','You are a teacher'],['هُوَ فِي الْمَسْجِدِ','','He is in the mosque'],['هِيَ طَبِيبَةٌ','','She is a doctor'],['نَحْنُ مُسْلِمُونَ','','We are Muslims'],['مَنْ أَنْتَ؟ أَنَا خَالِدٌ','','Who are you? I am Khalid']],
 q:[{q:'What does هِيَ mean?',o:['she','he','we'],why:'هِيَ is "she". هُوَ is "he".'},
    {q:'Which word do you use when speaking to a woman?',o:['أَنْتِ','أَنْتَ','هُوَ'],why:'The kasrah at the end makes it feminine.'},
    {q:'What does نَحْنُ مُسْلِمُونَ mean?',o:['We are Muslims','I am a Muslim','They are Muslims'],why:'نَحْنُ means "we".'}]},
{id:'idafah',title:'Belonging: the idaafah',ar:'كِتَابُ الطَّالِبِ',
 points:['To say "X of Y", put the two nouns side by side.','The first noun loses both الـ and tanween.','The second noun, the owner, ends in kasrah.'],
 ex:[['كِتَابُ الطَّالِبِ','','the book of the student'],['بَابُ الْمَسْجِدِ','','the door of the mosque'],['بَيْتُ الْمُدَرِّسِ','','the house of the teacher'],['رَسُولُ اللهِ','','the Messenger of Allah'],['كِتَابُ اللهِ','','the Book of Allah'],['قَلَمُ خَالِدٍ','','Khalid\'s pen']],
 q:[{q:'What does بَابُ الْمَسْجِدِ mean?',o:['the door of the mosque','the mosque is a door','a door and a mosque'],why:'Two nouns together, the second in kasrah, show belonging.'},
    {q:'Which is correct for "the teacher\'s house"?',o:['بَيْتُ الْمُدَرِّسِ','الْبَيْتُ الْمُدَرِّسِ','بَيْتٌ الْمُدَرِّسِ'],why:'The first noun takes neither الـ nor tanween.'},
    {q:'The second noun in an idaafah ends in…',o:['kasrah','dammah','tanween dammah'],why:'The owner is always majroor.'}]},
{id:'mine',title:'My, your, his, her, our',ar:'كِتَابِي · كِتَابُكَ',
 points:['Small endings on the noun show the owner.','ـِي my, ـكَ your (m), ـكِ your (f), ـهُ his, ـهَا her, ـنَا our.'],
 ex:[['كِتَابِي','','my book'],['كِتَابُكَ','','your book (to a man)'],['كِتَابُهُ','','his book'],['كِتَابُهَا','','her book'],['هٰذَا بَيْتِي','','This is my house'],['رَبُّنَا اللهُ','','Our Lord is Allah'],['أَيْنَ قَلَمُهُ؟','','Where is his pen?']],
 q:[{q:'What does كِتَابُهَا mean?',o:['her book','his book','our book'],why:'ـهَا means "her".'},
    {q:'How do you say "my house"?',o:['بَيْتِي','بَيْتُكَ','بَيْتُنَا'],why:'ـِي means "my".'},
    {q:'What does رَبُّنَا mean?',o:['our Lord','my Lord','your Lord'],why:'ـنَا means "our".'}]},
{id:'sifah',title:'Describing words',ar:'بَيْتٌ جَدِيدٌ',
 points:['The describing word comes after the noun.','It copies the noun: same gender, same "a" or "the", same ending.','Compare: الْبَيْتُ الْجَدِيدُ is "the new house". الْبَيْتُ جَدِيدٌ is a full sentence, "The house is new".'],
 ex:[['بَيْتٌ جَدِيدٌ','','a new house'],['الْبَيْتُ الْجَدِيدُ','','the new house'],['سَيَّارَةٌ جَدِيدَةٌ','','a new car'],['مَسْجِدٌ كَبِيرٌ','','a big mosque'],['الطَّالِبُ الْمُجْتَهِدُ','','the hard-working student']],
 q:[{q:'What does الْبَيْتُ الْجَدِيدُ mean?',o:['the new house','The house is new','a new house'],why:'Both words carry الـ, so it is a phrase, not a sentence.'},
    {q:'How do you say "a big mosque"?',o:['مَسْجِدٌ كَبِيرٌ','كَبِيرٌ مَسْجِدٌ','مَسْجِدٌ الْكَبِيرُ'],why:'The description follows the noun and matches it.'},
    {q:'الْبَيْتُ جَدِيدٌ is…',o:['a full sentence: The house is new','a phrase: the new house'],why:'Definite then indefinite makes a sentence.'}]},
{id:'madi',title:'What happened: the past tense',ar:'ذَهَبَ · ذَهَبْتُ',
 points:['The basic verb is the "he" form: ذَهَبَ, he went.','Endings show who did it: ذَهَبَتْ she, ذَهَبْتَ you (m), ذَهَبْتِ you (f), ذَهَبْتُ I, ذَهَبْنَا we.','More verbs: خَرَجَ went out, جَلَسَ sat, كَتَبَ wrote, قَرَأَ read.'],
 ex:[['ذَهَبَ الطَّالِبُ إِلَى الْمَدْرَسَةِ','','The student went to the school'],['جَلَسَتِ الْبِنْتُ عَلَى الْكُرْسِيِّ','','The girl sat on the chair'],['كَتَبْتُ الدَّرْسَ','','I wrote the lesson'],['قَرَأْنَا الْقُرْآنَ','','We read the Quran'],['أَيْنَ ذَهَبْتَ؟','','Where did you go?']],
 q:[{q:'What does ذَهَبْتُ mean?',o:['I went','he went','you went'],why:'The ending ـتُ means "I".'},
    {q:'How do you say "she wrote"?',o:['كَتَبَتْ','كَتَبَ','كَتَبْتُ'],why:'The ending ـَتْ marks "she".'},
    {q:'What does قَرَأْنَا mean?',o:['we read','I read','they read'],why:'The ending ـنَا means "we".'}]},
{id:'adad',title:'Numbers 1 to 10',ar:'وَاحِدٌ · اِثْنَانِ · ثَلَاثَةٌ',
 points:['Learn the ten numbers first as words on their own.','When counting 3 to 10 things, the counted noun is plural and ends in kasrah: ثَلَاثَةُ كُتُبٍ, three books.','With a feminine noun the number drops its ة: خَمْسُ سَيَّارَاتٍ, five cars.'],
 ex:[['وَاحِدٌ ١','waahidun','one'],['اِثْنَانِ ٢','ithnaani','two'],['ثَلَاثَةٌ ٣','thalaathatun','three'],['أَرْبَعَةٌ ٤','arba\'atun','four'],['خَمْسَةٌ ٥','khamsatun','five'],['سِتَّةٌ ٦','sittatun','six'],['سَبْعَةٌ ٧','sab\'atun','seven'],['ثَمَانِيَةٌ ٨','thamaaniyatun','eight'],['تِسْعَةٌ ٩','tis\'atun','nine'],['عَشَرَةٌ ١٠','\'asharatun','ten']],
 q:[{q:'Which number is خَمْسَةٌ ?',o:['5','4','7'],why:'خَمْسَةٌ is five.'},
    {q:'Which word is the number 7?',o:['سَبْعَةٌ','سِتَّةٌ','تِسْعَةٌ'],why:'سَبْعَةٌ is seven. سِتَّةٌ is six and تِسْعَةٌ is nine.'},
    {q:'What does ثَلَاثَةُ كُتُبٍ mean?',o:['three books','the third book','three pens'],why:'كُتُبٌ is the plural of كِتَابٌ.'}]}
];

var MORE=[["Masculine and feminine","طَالِبٌ ← طَالِبَةٌ",["Many words for people and many describing words become feminine by adding ة.","The letter before ة always carries fathah."],[["طَالِبٌ ← طَالِبَةٌ","student (male → female)"],["مُدَرِّسٌ ← مُدَرِّسَةٌ","teacher"],["طَبِيبٌ ← طَبِيبَةٌ","doctor"],["مُسْلِمٌ ← مُسْلِمَةٌ","Muslim"],["كَبِيرٌ ← كَبِيرَةٌ","big"]],[["What is the feminine of مُدَرِّسٌ ?",["مُدَرِّسَةٌ","مُدَرِّسُونَ","مُدَرِّسَانِ"],"Add ة to make the feminine."],["Which ending usually marks a feminine noun?",["ة","الـ","ـُونَ"],"The taa marbootah is the common feminine marker."],["What does طَبِيبَةٌ mean?",["a female doctor","a male doctor","doctors"],"طَبِيبٌ with ة is the feminine."]]],["Feminine without ة","أُمٌّ · يَدٌ · شَمْسٌ",["Words for females are feminine by meaning: أُمٌّ، أُخْتٌ، بِنْتٌ.","Body parts that come in pairs are feminine: يَدٌ، عَيْنٌ، أُذُنٌ، رِجْلٌ.","A few others are feminine by usage: شَمْسٌ، أَرْضٌ، نَارٌ، دَارٌ."],[["هٰذِهِ أُمِّي","This is my mother"],["هٰذِهِ يَدٌ","This is a hand"],["الشَّمْسُ حَارَّةٌ","The sun is hot"],["الْأَرْضُ وَاسِعَةٌ","The earth is vast"],["عَيْنُهُ جَمِيلَةٌ","His eye is beautiful"]],[["Complete: ___ عَيْنٌ",["هٰذِهِ","هٰذَا"],"Paired body parts are feminine."],["Which word is feminine?",["أَرْضٌ","قَمَرٌ","بَيْتٌ"],"أَرْضٌ is feminine by usage."],["Complete: الشَّمْسُ ___",["حَارَّةٌ","حَارٌّ"],"الشَّمْسُ is feminine, so its description takes ة."]]],["Two of something: the dual","كِتَابَانِ",["Add ـَانِ to say two: كِتَابٌ becomes كِتَابَانِ.","As an object or after a preposition the ending is ـَيْنِ: كِتَابَيْنِ.","A final ة opens into ت: سَيَّارَتَانِ.","هٰذَانِ and هَاتَانِ mean 'these two'."],[["كِتَابَانِ","two books"],["طَالِبَانِ","two students"],["سَيَّارَتَانِ","two cars"],["هٰذَانِ قَلَمَانِ","These are two pens"],["قَرَأْتُ كِتَابَيْنِ","I read two books"]],[["How do you say 'two pens'?",["قَلَمَانِ","أَقْلَامٌ","قَلَمٌ"],"The dual ending is ـَانِ."],["After a preposition the dual ending is…",["ـَيْنِ","ـَانِ","ـُونَ"],"In nasb and jarr the dual takes ـَيْنِ."],["What does سَيَّارَتَانِ mean?",["two cars","a car","many cars"],"ـَانِ marks exactly two."]]],["Plural for men: ـُونَ","مُسْلِمُونَ",["For male people, add ـُونَ: مُسْلِمٌ becomes مُسْلِمُونَ.","In nasb and jarr the ending is ـِينَ: مُسْلِمِينَ."],[["مُدَرِّسُونَ","teachers"],["مُسْلِمُونَ","Muslims"],["الْمُؤْمِنُونَ","the believers"],["هُمْ مُهَنْدِسُونَ","They are engineers"],["سَلَّمْتُ عَلَى الْمُدَرِّسِينَ","I greeted the teachers"]],[["What is the plural of مُدَرِّسٌ ?",["مُدَرِّسُونَ","مُدَرِّسَانِ","مُدَرِّسَةٌ"],"Male people take ـُونَ."],["Complete: مَعَ ___",["الْمُسْلِمِينَ","الْمُسْلِمُونَ"],"After مَعَ the plural takes ـِينَ."],["What does الْمُؤْمِنُونَ mean?",["the believers","the believer","the two believers"],"ـُونَ marks the plural."]]],["Plural for women: ـَاتٌ","مُسْلِمَاتٌ",["Replace ة with ـَاتٌ: مُسْلِمَةٌ becomes مُسْلِمَاتٌ.","Many nouns for things take it too: سَيَّارَاتٌ.","In nasb it takes kasrah, not fathah: رَأَيْتُ الطَّالِبَاتِ."],[["طَالِبَاتٌ","female students"],["مُدَرِّسَاتٌ","female teachers"],["سَيَّارَاتٌ","cars"],["كَلِمَاتٌ","words"],["رَأَيْتُ الطَّالِبَاتِ","I saw the female students"]],[["What is the plural of طَالِبَةٌ ?",["طَالِبَاتٌ","طَالِبُونَ","طَالِبَتَانِ"],"ة changes to ـَاتٌ."],["What does سَيَّارَاتٌ mean?",["cars","a car","two cars"],"ـَاتٌ marks the plural."],["Complete: رَأَيْتُ ___",["الْمُدَرِّسَاتِ","الْمُدَرِّسَاتَ"],"This plural shows nasb with kasrah."]]],["Broken plurals","كِتَابٌ ← كُتُبٌ",["Most nouns change their inner shape to form the plural. Learn the plural with each new word.","Common shapes: كُتُبٌ، أَقْلَامٌ، بُيُوتٌ، رِجَالٌ."],[["كِتَابٌ ← كُتُبٌ","book → books"],["قَلَمٌ ← أَقْلَامٌ","pen → pens"],["بَيْتٌ ← بُيُوتٌ","house → houses"],["رَجُلٌ ← رِجَالٌ","man → men"],["بَابٌ ← أَبْوَابٌ","door → doors"],["مَسْجِدٌ ← مَسَاجِدُ","mosque → mosques"],["طَالِبٌ ← طُلَّابٌ","student → students"]],[["What is the plural of كِتَابٌ ?",["كُتُبٌ","كِتَابَانِ","كِتَابُونَ"],"كُتُبٌ is a broken plural."],["What does بُيُوتٌ mean?",["houses","a house","two houses"],"It is the plural of بَيْتٌ."],["What is the plural of قَلَمٌ ?",["أَقْلَامٌ","قَلَمُونَ","قَلَمَاتٌ"],"أَقْلَامٌ is a broken plural."]]],["These and those people","هٰؤُلَاءِ · أُولٰئِكَ",["هٰؤُلَاءِ means 'these' and أُولٰئِكَ means 'those', for people.","The same word serves men and women."],[["هٰؤُلَاءِ طُلَّابٌ","These are students"],["هٰؤُلَاءِ مُدَرِّسَاتٌ","These are female teachers"],["أُولٰئِكَ رِجَالٌ","Those are men"],["مَنْ هٰؤُلَاءِ؟","Who are these?"],["أُولٰئِكَ هُمُ الْمُفْلِحُونَ","Those are the successful ones"]],[["What does هٰؤُلَاءِ mean?",["these","those","this"],"هٰؤُلَاءِ points to people who are near."],["How do you say 'Those are men'?",["أُولٰئِكَ رِجَالٌ","ذٰلِكَ رِجَالٌ","هٰذَا رِجَالٌ"],"أُولٰئِكَ is the plural 'those'."],["هٰؤُلَاءِ is used for…",["people, male or female","one man","one woman"],"It has one form for both genders."]]],["Plurals of things","الْكُتُبُ جَدِيدَةٌ",["The plural of things, not people, is treated as feminine singular.","So we say هٰذِهِ كُتُبٌ and الْكُتُبُ جَدِيدَةٌ, and refer to them with هِيَ."],[["هٰذِهِ كُتُبٌ","These are books"],["الْكُتُبُ جَدِيدَةٌ","The books are new"],["الْبُيُوتُ كَبِيرَةٌ","The houses are big"],["تِلْكَ سَيَّارَاتٌ","Those are cars"],["أَيْنَ الْأَقْلَامُ؟ هِيَ عَلَى الْمَكْتَبِ","Where are the pens? They are on the desk"]],[["Complete: الْبُيُوتُ ___",["كَبِيرَةٌ","كَبِيرُونَ","كَبِيرٌ"],"Non-human plurals take a feminine singular description."],["How do you say 'These are books'?",["هٰذِهِ كُتُبٌ","هٰؤُلَاءِ كُتُبٌ","هٰذَا كُتُبٌ"],"هٰؤُلَاءِ is only for people."],["Which pronoun refers to الْأَقْلَامُ ?",["هِيَ","هُمْ","هُوَ"],"Plurals of things use هِيَ."]]],["The three endings","ـُ · ـَ · ـِ",["A noun's last vowel shows its job in the sentence. Dammah (مَرْفُوع) marks the subject or doer.","Fathah (مَنْصُوب) marks the object.","Kasrah (مَجْرُور) comes after a preposition, or on the owner in an idaafah."],[["جَاءَ الطَّالِبُ","The student came"],["رَأَيْتُ الطَّالِبَ","I saw the student"],["سَلَّمْتُ عَلَى الطَّالِبِ","I greeted the student"],["هٰذَا كِتَابُ الطَّالِبِ","This is the student's book"]],[["The doer of a verb ends in…",["dammah","fathah","kasrah"],"The doer is marfoo."],["Complete: رَأَيْتُ ___",["الْمُدَرِّسَ","الْمُدَرِّسُ","الْمُدَرِّسِ"],"The object takes fathah."],["A noun after a preposition ends in…",["kasrah","dammah","fathah"],"Prepositions make the noun majroor."]]],["Words without tanween","أَحْمَدُ · مَكَّةُ",["Some nouns never take tanween, and take fathah in place of kasrah. They are called مَمْنُوعٌ مِنَ الصَّرْفِ.","They include most women's names, foreign names, names shaped like أَفْعَل, and plurals shaped like مَسَاجِدُ.","With الـ, or as the first word of an idaafah, they take kasrah as normal."],[["هٰذَا أَحْمَدُ","This is Ahmad"],["ذَهَبْتُ إِلَى مَكَّةَ","I went to Makkah"],["كِتَابُ فَاطِمَةَ","Fatimah's book"],["صَلَّيْتُ فِي مَسَاجِدَ كَثِيرَةٍ","I prayed in many mosques"],["فِي الْمَسَاجِدِ","in the mosques"]],[["Complete: ذَهَبْتُ إِلَى ___",["مَكَّةَ","مَكَّةِ","مَكَّةٍ"],"مَكَّةُ takes fathah in place of kasrah."],["Which name takes no tanween?",["أَحْمَدُ","مُحَمَّدٌ","خَالِدٌ"],"Names shaped like أَفْعَل have no tanween."],["Complete: فِي ___",["الْمَسَاجِدِ","الْمَسَاجِدَ"],"With الـ the word takes kasrah as normal."]]],["Father and brother: the five nouns","أَبُوكَ · أَخُوكَ",["أَبٌ، أَخٌ، حَمٌ، فُو and ذُو show their case with a long vowel when they are the first word of an idaafah.","Waaw for raf, alif for nasb, yaa for jarr: أَبُوكَ، أَبَاكَ، أَبِيكَ."],[["جَاءَ أَبُوكَ","Your father came"],["رَأَيْتُ أَبَاكَ","I saw your father"],["ذَهَبْتُ إِلَى أَبِيكَ","I went to your father"],["أَخُوهُ طَبِيبٌ","His brother is a doctor"],["هٰذَا بَيْتُ أَخِي","This is my brother's house"]],[["Complete: رَأَيْتُ ___",["أَخَاكَ","أَخُوكَ","أَخِيكَ"],"The object takes alif."],["Complete: مَعَ ___",["أَبِيكَ","أَبُوكَ","أَبَاكَ"],"After مَعَ it takes yaa."],["What does أَخُوهُ طَبِيبٌ mean?",["His brother is a doctor","His father is a doctor","He is a doctor's brother"],"أَخُوهُ is 'his brother'."]]],["Saying 'I have'","عِنْدِي · لِي",["Arabic has no verb 'to have'. Use عِنْدَ for things you possess: عِنْدِي كِتَابٌ.","Use لِـ for family and for belonging: لِي أَخٌ."],[["عِنْدِي كِتَابٌ","I have a book"],["عِنْدَكَ قَلَمٌ","You have a pen"],["لِي أَخٌ وَأُخْتٌ","I have a brother and a sister"],["عِنْدَ الْمُدَرِّسِ سَيَّارَةٌ","The teacher has a car"],["أَعِنْدَكَ سَاعَةٌ؟","Do you have a watch?"],["هٰذَا الْكِتَابُ لِخَالِدٍ","This book belongs to Khalid"]],[["What does عِنْدِي كِتَابٌ mean?",["I have a book","This is my book","I read a book"],"عِنْدِي is 'with me', so 'I have'."],["How do you say 'I have a brother'?",["لِي أَخٌ","أَنَا أَخٌ","هٰذَا أَخٌ"],"لِـ is used for family."],["What does لِخَالِدٍ mean?",["belongs to Khalid","from Khalid","with Khalid"],"لِـ shows belonging."]]],["More prepositions","بِـ · لِـ · عَنْ · مَعَ",["بِـ = with, by. لِـ = for, belonging to. عَنْ = about, away from. كَـ = like.","مَعَ = together with. The noun after it takes kasrah too."],[["كَتَبْتُ بِالْقَلَمِ","I wrote with the pen"],["بِسْمِ اللهِ","In the name of Allah"],["الْحَمْدُ لِلَّهِ","All praise is for Allah"],["سَأَلَ عَنِ الدَّرْسِ","He asked about the lesson"],["ذَهَبْتُ مَعَ أَبِي","I went with my father"]],[["What does بِالْقَلَمِ mean?",["with the pen","on the pen","from the pen"],"بِـ shows the tool used."],["What does عَنْ mean?",["about","with","in"],"سَأَلَ عَنْ is 'he asked about'."],["Complete: ذَهَبْتُ ___ أَبِي",["مَعَ","عَنْ","عَلَى"],"مَعَ means 'together with'."]]],["Where exactly?","أَمَامَ · خَلْفَ · فَوْقَ · تَحْتَ",["These place words are followed by a noun in kasrah.","أَمَامَ in front of, خَلْفَ behind, فَوْقَ above, تَحْتَ under, بَيْنَ between, عِنْدَ at."],[["الْمُدَرِّسُ أَمَامَ الطُّلَّابِ","The teacher is in front of the students"],["الْحَدِيقَةُ خَلْفَ الْبَيْتِ","The garden is behind the house"],["الْقَلَمُ تَحْتَ الْكُرْسِيِّ","The pen is under the chair"],["السَّمَاءُ فَوْقَ الْأَرْضِ","The sky is above the earth"],["جَلَسَ بَيْنَ أَبِيهِ وَأَخِيهِ","He sat between his father and his brother"]],[["What does تَحْتَ mean?",["under","above","behind"],"تَحْتَ الْكُرْسِيِّ is 'under the chair'."],["What does خَلْفَ الْبَيْتِ mean?",["behind the house","in front of the house","inside the house"],"خَلْفَ is 'behind'."],["The noun after أَمَامَ ends in…",["kasrah","dammah","fathah"],"It is the second part of an idaafah."]]],["Asking questions","مَتَى · كَيْفَ · لِمَاذَا · كَمْ",["مَتَى when, كَيْفَ how, لِمَاذَا why, أَيُّ which, كَمْ how many.","هَلْ and أَ turn a statement into a yes or no question.","After كَمْ the noun is singular with tanween fathah: كَمْ كِتَابًا؟"],[["مَتَى ذَهَبْتَ؟","When did you go?"],["لِمَاذَا خَرَجْتَ؟","Why did you go out?"],["كَمْ كِتَابًا عِنْدَكَ؟","How many books do you have?"],["هَلْ أَنْتَ طَالِبٌ؟","Are you a student?"],["أَيُّ كِتَابٍ هٰذَا؟","Which book is this?"]],[["What does لِمَاذَا mean?",["why","when","how"],"لِمَاذَا asks for the reason."],["Complete: كَمْ ___ عِنْدَكَ؟",["قَلَمًا","أَقْلَامٌ","الْقَلَمُ"],"After كَمْ the noun is singular with tanween fathah."],["هَلْ makes a sentence into…",["a yes or no question","a command","a negative"],"هَلْ أَنْتَ طَالِبٌ؟ is 'Are you a student?'"]]],["Who and which: الَّذِي and الَّتِي","الَّذِي · الَّتِي",["الَّذِي (masculine) and الَّتِي (feminine) join a description to a definite noun.","The plural for men is الَّذِينَ."],[["الطَّالِبُ الَّذِي خَرَجَ مَرِيضٌ","The student who went out is ill"],["السَّيَّارَةُ الَّتِي أَمَامَ الْبَيْتِ جَدِيدَةٌ","The car which is in front of the house is new"],["الْكِتَابُ الَّذِي عَلَى الْمَكْتَبِ لِي","The book which is on the desk is mine"],["الَّذِينَ آمَنُوا","those who believed"]],[["Complete: الطَّالِبَةُ ___ جَلَسَتْ",["الَّتِي","الَّذِي","الَّذِينَ"],"A feminine noun takes الَّتِي."],["الَّذِينَ is…",["the plural for men","the feminine singular","the dual"],"الَّذِينَ آمَنُوا is 'those who believed'."],["What does الْكِتَابُ الَّذِي عَلَى الْمَكْتَبِ mean?",["the book which is on the desk","the book is on the desk","a book and a desk"],"الَّذِي links the description to the noun."]]],["Bigger and biggest","أَكْبَرُ مِنْ",["The shape أَفْعَلُ compares: كَبِيرٌ becomes أَكْبَرُ. It stays the same for masculine and feminine.","Use مِنْ for 'than'.","As the first word of an idaafah it means 'the most': أَكْبَرُ مَسْجِدٍ."],[["الْبَيْتُ أَكْبَرُ مِنَ الْغُرْفَةِ","The house is bigger than the room"],["خَالِدٌ أَطْوَلُ مِنْ أَخِيهِ","Khalid is taller than his brother"],["اللهُ أَكْبَرُ","Allah is the Greatest"],["هٰذَا أَجْمَلُ بَيْتٍ","This is the most beautiful house"]],[["What is the comparative of صَغِيرٌ ?",["أَصْغَرُ","صَغِيرَةٌ","صِغَارٌ"],"The comparative follows أَفْعَلُ."],["What does أَكْبَرُ مِنْ mean?",["bigger than","as big as","not big"],"مِنْ here means 'than'."],["What does اللهُ أَكْبَرُ mean?",["Allah is the Greatest","Allah is One","Praise be to Allah"],"أَكْبَرُ is 'greater, greatest'."]]],["Colours","أَحْمَرُ · حَمْرَاءُ",["Colours use أَفْعَلُ for the masculine and فَعْلَاءُ for the feminine.","Neither form takes tanween."],[["قَلَمٌ أَحْمَرُ","a red pen"],["سَيَّارَةٌ حَمْرَاءُ","a red car"],["بَابٌ أَبْيَضُ","a white door"],["وَرَقَةٌ بَيْضَاءُ","a white sheet of paper"],["السَّمَاءُ زَرْقَاءُ","The sky is blue"],["الشَّجَرَةُ خَضْرَاءُ","The tree is green"]],[["What is the feminine of أَبْيَضُ ?",["بَيْضَاءُ","أَبْيَضَةٌ","بِيضٌ"],"The feminine follows فَعْلَاءُ."],["Complete: سَيَّارَةٌ ___",["سَوْدَاءُ","أَسْوَدُ"],"سَيَّارَةٌ is feminine."],["What does أَخْضَرُ mean?",["green","blue","red"],"الشَّجَرَةُ خَضْرَاءُ is 'The tree is green'."]]],["They and you all","هُمْ · هُنَّ · أَنْتُمْ",["هُمْ they (men), هُنَّ they (women), أَنْتُمْ you (men), أَنْتُنَّ you (women).","For two people: هُمَا they two, أَنْتُمَا you two."],[["هُمْ طُلَّابٌ","They are students"],["هُنَّ مُدَرِّسَاتٌ","They are female teachers"],["أَنْتُمْ مُسْلِمُونَ","You are Muslims"],["هُمَا أَخَوَانِ","They two are brothers"],["مَنْ أَنْتُمْ؟","Who are you all?"]],[["What does هُنَّ mean?",["they (women)","they (men)","you (women)"],"هُنَّ is the feminine plural 'they'."],["How do you say 'you all' to men?",["أَنْتُمْ","هُمْ","أَنْتُنَّ"],"أَنْتُمْ addresses a group of men."],["What does هُمَا mean?",["they two","they (many)","you two"],"هُمَا is the dual."]]],["Their, your, plural owners","ـهُمْ · ـكُمْ",["ـهُمْ their (men), ـهُنَّ their (women), ـكُمْ your (men), ـكُنَّ your (women), ـهُمَا their (two).","After kasrah or yaa, ـهُ and ـهُمْ are read ـهِ and ـهِمْ: فِي بَيْتِهِمْ."],[["بَيْتُهُمْ","their house"],["رَبُّكُمْ","your Lord"],["كِتَابُهُنَّ","their book (women)"],["فِي بَيْتِهِمْ","in their house"],["السَّلَامُ عَلَيْكُمْ","Peace be upon you"]],[["What does بَيْتُهُمْ mean?",["their house","your house","our house"],"ـهُمْ means 'their'."],["What does رَبُّكُمْ mean?",["your Lord","their Lord","my Lord"],"ـكُمْ means 'your' for a group."],["Complete: فِي ___",["بَيْتِهِمْ","بَيْتِهُمْ"],"After kasrah the ending is read ـهِمْ."]]],["All and some","كُلُّ · بَعْضُ",["كُلُّ with an indefinite singular means 'every': كُلُّ طَالِبٍ.","كُلُّ with a definite plural means 'all': كُلُّ الطُّلَّابِ.","بَعْضُ means 'some of'."],[["كُلُّ طَالِبٍ","every student"],["كُلُّ الطُّلَّابِ","all the students"],["كُلُّ يَوْمٍ","every day"],["بَعْضُ النَّاسِ","some of the people"],["كُلُّهُمْ","all of them"]],[["What does كُلُّ يَوْمٍ mean?",["every day","some days","today"],"كُلُّ with an indefinite singular is 'every'."],["What does بَعْضُ الطُّلَّابِ mean?",["some of the students","all the students","every student"],"بَعْضُ is 'some of'."],["The noun after كُلُّ ends in…",["kasrah","dammah","fathah"],"It is the second part of an idaafah."]]],["Owner of: ذُو and ذَاتُ","ذُو عِلْمٍ",["ذُو (masculine) and ذَاتُ (feminine) mean 'owner of' or 'having'. The noun after them takes kasrah.","ذُو is one of the five nouns: ذُو، ذَا، ذِي."],[["رَجُلٌ ذُو عِلْمٍ","a man of knowledge"],["اِمْرَأَةٌ ذَاتُ خُلُقٍ","a woman of good character"],["اللهُ ذُو الْفَضْلِ الْعَظِيمِ","Allah is the Owner of great bounty"],["ذُو الْقَرْنَيْنِ","Dhul-Qarnayn"]],[["What does ذُو عِلْمٍ mean?",["having knowledge","without knowledge","seeking knowledge"],"ذُو is 'owner of'."],["What is the feminine of ذُو ?",["ذَاتُ","ذِي","ذَا"],"ذَاتُ is the feminine form."],["The noun after ذُو ends in…",["kasrah","dammah","fathah"],"It forms an idaafah."]]],["Past tense: they and you all","ذَهَبُوا · ذَهَبْتُمْ",["ذَهَبُوا they (men) went. The alif after the waaw is written but silent.","ذَهَبْنَ they (women) went, ذَهَبْتُمْ you (men) went, ذَهَبْتُنَّ you (women) went.","For two: ذَهَبَا they two went."],[["الطُّلَّابُ ذَهَبُوا إِلَى الْمَسْجِدِ","The students went to the mosque"],["الطَّالِبَاتُ جَلَسْنَ فِي الْفَصْلِ","The female students sat in the classroom"],["أَيْنَ ذَهَبْتُمْ؟","Where did you all go?"],["هُمَا خَرَجَا","They two went out"],["كَتَبْنَا الدَّرْسَ","We wrote the lesson"]],[["What does ذَهَبُوا mean?",["they (men) went","we went","you all went"],"ـُوا marks 'they' for men."],["How do you say 'they (women) wrote'?",["كَتَبْنَ","كَتَبُوا","كَتَبْنَا"],"ـْنَ marks 'they' for women."],["What does ذَهَبْتُمْ mean?",["you (men) went","they went","we went"],"ـْتُمْ marks 'you all'."]]],["Verb first: the verbal sentence","ذَهَبَ الطُّلَّابُ",["A sentence that starts with a verb is a verbal sentence. The doer (فَاعِل) follows and ends in dammah.","When the doer comes after the verb, the verb stays singular, even for a plural doer.","The verb matches the doer in gender."],[["ذَهَبَ الطَّالِبُ","The student went"],["ذَهَبَ الطُّلَّابُ","The students went"],["جَلَسَتِ الطَّالِبَاتُ","The female students sat"],["خَرَجَ الْمُدَرِّسُونَ","The teachers went out"]],[["Complete: ___ الطُّلَّابُ",["ذَهَبَ","ذَهَبُوا"],"Before its doer the verb stays singular."],["The doer of the verb is called…",["فَاعِل","مَفْعُول","خَبَر"],"فَاعِل means 'doer'."],["Complete: ___ الْبِنْتُ",["جَلَسَتِ","جَلَسَ"],"The verb matches the doer in gender."]]],["The object","قَرَأَ الطَّالِبُ الْكِتَابَ",["The thing the action falls on is the object (مَفْعُولٌ بِهِ). It ends in fathah.","An indefinite object takes tanween fathah, usually written with an alif: كِتَابًا."],[["قَرَأَ الطَّالِبُ الْكِتَابَ","The student read the book"],["فَتَحَ الْوَلَدُ الْبَابَ","The boy opened the door"],["شَرِبْتُ مَاءً","I drank water"],["أَكَلَ خَالِدٌ تُفَّاحَةً","Khalid ate an apple"],["كَتَبْتُ رِسَالَةً","I wrote a letter"]],[["Complete: فَتَحْتُ ___",["الْبَابَ","الْبَابُ","الْبَابِ"],"The object takes fathah."],["The object ends in…",["fathah","dammah","kasrah"],"The object is mansoob."],["Complete: قَرَأْتُ ___",["كِتَابًا","كِتَابٌ","كِتَابٍ"],"An indefinite object takes tanween fathah."]]],["Did not: مَا with the past","مَا ذَهَبَ",["Put مَا before a past verb to negate it."],[["مَا ذَهَبْتُ إِلَى السُّوقِ","I did not go to the market"],["مَا فَهِمَ الدَّرْسَ","He did not understand the lesson"],["مَا أَكَلْنَا شَيْئًا","We did not eat anything"],["أَذَهَبْتَ؟ لَا، مَا ذَهَبْتُ","Did you go? No, I did not go"]],[["What does مَا ذَهَبْتُ mean?",["I did not go","I went","I will go"],"مَا negates the past verb."],["How do you say 'He did not write'?",["مَا كَتَبَ","كَتَبَ","مَا كَتَبْتُ"],"مَا before the 'he' form."],["مَا before a past verb means…",["did not","will not","do not"],"It negates the past."]]],["Me, him, her on verbs","رَأَيْتُهُ · سَأَلَنِي",["The owner endings also attach to verbs as objects: ـهُ him, ـهَا her, ـكَ you, ـنَا us, ـهُمْ them.","'Me' on a verb is ـنِي, not ـِي."],[["رَأَيْتُهُ","I saw him"],["رَأَيْتُهَا","I saw her"],["سَأَلَنِي الْمُدَرِّسُ","The teacher asked me"],["خَلَقَنَا اللهُ","Allah created us"],["سَمِعْتُكَ","I heard you"]],[["What does رَأَيْتُهَا mean?",["I saw her","I saw him","She saw me"],"ـهَا is 'her'."],["How do you say 'He asked me'?",["سَأَلَنِي","سَأَلَهُ","سَأَلْتُ"],"ـنِي is 'me' on a verb."],["What does خَلَقَنَا mean?",["He created us","We created","He created me"],"ـنَا after the 'he' form is 'us'."]]],["The present tense","يَذْهَبُ · أَذْهَبُ",["The present verb takes a letter at the front: يَـ he, تَـ she or you, أَ I, نَـ we.","يَذْهَبُ he goes, تَذْهَبُ she goes or you (man) go, أَذْهَبُ I go, نَذْهَبُ we go.","It covers both 'goes' and 'is going'."],[["يَذْهَبُ خَالِدٌ إِلَى الْمَدْرَسَةِ","Khalid goes to school"],["تَكْتُبُ فَاطِمَةُ الدَّرْسَ","Fatimah writes the lesson"],["أَذْهَبُ إِلَى الْمَسْجِدِ","I go to the mosque"],["نَعْبُدُ اللهَ","We worship Allah"],["مَاذَا تَقْرَأُ؟","What are you reading?"]],[["What does أَذْهَبُ mean?",["I go","he goes","we go"],"أَ at the front marks 'I'."],["How do you say 'we write'?",["نَكْتُبُ","يَكْتُبُ","أَكْتُبُ"],"نَـ at the front marks 'we'."],["What does يَذْهَبُ mean?",["he goes","he went","I go"],"يَـ at the front marks 'he' in the present."]]],["Present tense: plural and feminine","يَذْهَبُونَ · تَذْهَبِينَ",["يَذْهَبُونَ they (men) go, تَذْهَبُونَ you (men) go.","تَذْهَبِينَ you (a woman) go.","يَذْهَبْنَ they (women) go, يَذْهَبَانِ they two go."],[["الطُّلَّابُ يَذْهَبُونَ إِلَى الْجَامِعَةِ","The students go to the university"],["مَاذَا تَكْتُبِينَ يَا مَرْيَمُ؟","What are you writing, Maryam?"],["أَيْنَ تَذْهَبُونَ؟","Where are you all going?"],["الْبَنَاتُ يَجْلِسْنَ","The girls sit"],["هُمَا يَدْرُسَانِ","They two study"]],[["What does يَذْهَبُونَ mean?",["they (men) go","we go","you (a woman) go"],"يَـ…ـُونَ is 'they' for men."],["To a woman: مَاذَا ___ ؟",["تَكْتُبِينَ","تَكْتُبُ","يَكْتُبُ"],"تَـ…ـِينَ addresses a woman."],["What does يَجْلِسْنَ mean?",["they (women) sit","they (men) sit","we sit"],"يَـ…ـْنَ is 'they' for women."]]],["Three present patterns","يَفْتَحُ · يَجْلِسُ · يَكْتُبُ",["The middle letter of the present verb carries fathah, kasrah or dammah. Learn it with each verb.","Dictionaries list the past and the present together: كَتَبَ يَكْتُبُ."],[["فَتَحَ يَفْتَحُ","to open"],["ذَهَبَ يَذْهَبُ","to go"],["جَلَسَ يَجْلِسُ","to sit"],["ضَرَبَ يَضْرِبُ","to strike"],["كَتَبَ يَكْتُبُ","to write"],["دَخَلَ يَدْخُلُ","to enter"],["شَرِبَ يَشْرَبُ","to drink"]],[["What is the present of كَتَبَ ?",["يَكْتُبُ","يَكْتَبُ","يَكْتِبُ"],"The middle letter takes dammah."],["What is the present of جَلَسَ ?",["يَجْلِسُ","يَجْلَسُ","يَجْلُسُ"],"The middle letter takes kasrah."],["What is the present of شَرِبَ ?",["يَشْرَبُ","يَشْرِبُ","يَشْرُبُ"],"The middle letter takes fathah."]]],["The future","سَيَذْهَبُ · سَوْفَ يَذْهَبُ",["Add سَـ to the present verb for the near future.","سَوْفَ before the verb points to a later future."],[["سَأَذْهَبُ إِلَى مَكَّةَ","I will go to Makkah"],["سَيَرْجِعُ أَبِي غَدًا","My father will return tomorrow"],["سَوْفَ نَدْرُسُ الْعَرَبِيَّةَ","We will study Arabic"],["سَتَفْهَمُ الدَّرْسَ إِنْ شَاءَ اللهُ","You will understand the lesson, if Allah wills"]],[["What does سَأَذْهَبُ mean?",["I will go","I went","I go"],"سَـ marks the future."],["Which letter marks the near future?",["سَـ","لَا","مَا"],"سَـ is attached to the present verb."],["What does سَوْفَ نَدْرُسُ mean?",["We will study","We studied","We are studying"],"سَوْفَ also marks the future."]]],["Does not: لَا with the present","لَا يَذْهَبُ",["لَا before a present verb means 'does not'. The verb keeps its dammah."],[["لَا أَفْهَمُ","I do not understand"],["لَا يَذْهَبُ إِلَى السُّوقِ","He does not go to the market"],["لَا نَعْبُدُ إِلَّا اللهَ","We worship none but Allah"],["لَا أَعْرِفُ","I do not know"]],[["What does لَا أَعْرِفُ mean?",["I do not know","I did not know","I will not know"],"لَا with the present is 'do not'."],["How do you say 'He does not write'?",["لَا يَكْتُبُ","مَا كَتَبَ","لَنْ يَكْتُبَ"],"لَا negates the present."],["After لَا of negation the verb ends in…",["dammah","fathah","sukoon"],"This لَا does not change the ending."]]],["Will not: لَنْ","لَنْ يَذْهَبَ",["لَنْ negates the future. The verb after it ends in fathah (مَنْصُوب).","Verbs ending in ـُونَ or ـِينَ drop the ن: لَنْ يَذْهَبُوا."],[["لَنْ أَذْهَبَ","I will not go"],["لَنْ يَرْجِعَ الْيَوْمَ","He will not return today"],["لَنْ نَتْرُكَ الصَّلَاةَ","We will not leave the prayer"],["لَنْ يَذْهَبُوا","They will not go"]],[["What does لَنْ أَذْهَبَ mean?",["I will not go","I did not go","I do not go"],"لَنْ negates the future."],["After لَنْ the verb ends in…",["fathah","dammah","sukoon"],"لَنْ makes the verb mansoob."],["Complete: لَنْ ___",["يَذْهَبُوا","يَذْهَبُونَ"],"The ن drops after لَنْ."]]],["Did not: لَمْ","لَمْ يَذْهَبْ",["لَمْ with a present verb gives a past negative: 'did not'.","The verb ends in sukoon (مَجْزُوم). Verbs in ـُونَ drop the ن."],[["لَمْ أَذْهَبْ","I did not go"],["لَمْ يَكْتُبِ الدَّرْسَ","He did not write the lesson"],["لَمْ يَلِدْ وَلَمْ يُولَدْ","He did not beget, nor was He begotten"],["لَمْ يَفْهَمُوا","They did not understand"]],[["What does لَمْ أَذْهَبْ mean?",["I did not go","I will not go","I do not go"],"لَمْ turns the meaning to the past."],["After لَمْ the verb ends in…",["sukoon","fathah","dammah"],"لَمْ makes the verb majzoom."],["Which means 'he did not write'?",["لَمْ يَكْتُبْ","لَنْ يَكْتُبَ","لَا يَكْتُبُ"],"لَمْ is 'did not'."]]],["To do: أَنْ","أُرِيدُ أَنْ أَذْهَبَ",["أَنْ links two verbs like the English 'to'. The verb after it ends in fathah.","Common before it: أُرِيدُ I want, أُحِبُّ I love, يَجِبُ it is necessary."],[["أُرِيدُ أَنْ أَذْهَبَ","I want to go"],["أُحِبُّ أَنْ أَقْرَأَ الْقُرْآنَ","I love to read the Quran"],["يُرِيدُ أَنْ يَشْرَبَ","He wants to drink"],["يَجِبُ أَنْ نَصْدُقَ","We must be truthful"]],[["Complete: أُرِيدُ أَنْ ___",["أَكْتُبَ","أَكْتُبُ","أَكْتُبْ"],"After أَنْ the verb takes fathah."],["What does أُرِيدُ أَنْ أَذْهَبَ mean?",["I want to go","I went","I will not go"],"أُرِيدُ is 'I want'."],["After أَنْ the verb ends in…",["fathah","dammah","sukoon"],"أَنْ makes the verb mansoob."]]],["In order to: لِـ، كَيْ، حَتَّى","لِأَتَعَلَّمَ",["لِـ and كَيْ before a present verb mean 'in order to'. حَتَّى means 'until' or 'so that'.","The verb after them ends in fathah."],[["ذَهَبْتُ إِلَى الْمَدْرَسَةِ لِأَتَعَلَّمَ","I went to school in order to learn"],["أَدْرُسُ كَيْ أَنْجَحَ","I study so that I succeed"],["اِنْتَظِرْ حَتَّى أَرْجِعَ","Wait until I return"],["جِئْتُ لِأَسْأَلَكَ","I came to ask you"]],[["What does لِأَتَعَلَّمَ mean?",["in order to learn","I learnt","do not learn"],"لِـ before the verb gives the purpose."],["What does حَتَّى mean?",["until","because","but"],"حَتَّى أَرْجِعَ is 'until I return'."],["After كَيْ the verb ends in…",["fathah","dammah","sukoon"],"كَيْ makes the verb mansoob."]]],["Giving a command","اُكْتُبْ · اِجْلِسْ",["Take the present 'you' form, drop the تَـ and end in sukoon: تَكْتُبُ becomes اُكْتُبْ.","If the word then starts with a sukoon, add a helping alif. It takes dammah when the middle vowel is dammah, otherwise kasrah."],[["اُكْتُبْ","Write!"],["اِجْلِسْ","Sit!"],["اِقْرَأْ","Read!"],["اِفْتَحِ الْبَابَ","Open the door!"],["اُدْخُلْ","Enter!"],["اِذْهَبْ إِلَى الْمَسْجِدِ","Go to the mosque!"]],[["What is the command from تَجْلِسُ ?",["اِجْلِسْ","اُجْلِسْ","جَلَسَ"],"The middle vowel is kasrah, so the alif takes kasrah."],["What does اِقْرَأْ mean?",["Read!","He read","I read"],"It is the command form."],["What is the command from تَكْتُبُ ?",["اُكْتُبْ","اِكْتُبْ","يَكْتُبُ"],"The middle vowel is dammah, so the alif takes dammah."]]],["Commands to women and groups","اُكْتُبِي · اُكْتُبُوا",["To a woman add ـِي: اُكْتُبِي. To a group of men add ـُوا: اُكْتُبُوا.","To two people add ـَا: اُكْتُبَا. To a group of women add ـْنَ: اُكْتُبْنَ."],[["اِجْلِسِي يَا فَاطِمَةُ","Sit, Fatimah!"],["اُدْخُلُوا الْفَصْلَ","Enter the classroom, all of you!"],["اُعْبُدُوا اللهَ","Worship Allah!"],["اِذْهَبَا","Go, you two!"]],[["Which command is said to a woman?",["اُكْتُبِي","اُكْتُبُوا","اُكْتُبْ"],"ـِي addresses a woman."],["What does اُعْبُدُوا اللهَ mean?",["Worship Allah, all of you","He worshipped Allah","I worship Allah"],"ـُوا addresses a group."],["Which command is said to a group of men?",["اِجْلِسُوا","اِجْلِسِي","اِجْلِسْ"],"ـُوا addresses a group of men."]]],["Do not!","لَا تَذْهَبْ",["لَا with the present 'you' form ending in sukoon forbids: لَا تَذْهَبْ.","This is different from the لَا of plain negation, where the verb keeps its dammah."],[["لَا تَذْهَبْ","Do not go!"],["لَا تَجْلِسْ هُنَا","Do not sit here!"],["لَا تَحْزَنْ","Do not grieve"],["لَا تَغْضَبْ","Do not get angry"],["لَا تَكْتُبِي عَلَى الْكِتَابِ","Do not write on the book (to a woman)"]],[["What does لَا تَذْهَبْ mean?",["Do not go!","You do not go","You did not go"],"Sukoon on the verb shows a prohibition."],["What does لَا تَذْهَبُ mean?",["You do not go","Do not go!","You did not go"],"Dammah on the verb shows plain negation."],["What does لَا تَحْزَنْ mean?",["Do not grieve","You are not sad","He does not grieve"],"It is a prohibition."]]],["The five verb forms","يَذْهَبُونَ ← لَنْ يَذْهَبُوا",["Five present forms end in ن: يَفْعَلَانِ، تَفْعَلَانِ، يَفْعَلُونَ، تَفْعَلُونَ، تَفْعَلِينَ.","They keep the ن normally and drop it after أَنْ، لَنْ and لَمْ, and in commands and prohibitions."],[["يَذْهَبُونَ","they go"],["لَنْ يَذْهَبُوا","they will not go"],["لَمْ يَذْهَبُوا","they did not go"],["تَكْتُبِينَ","you (a woman) write"],["لَا تَكْتُبِي","do not write (to a woman)"]],[["Complete: لَمْ ___",["يَكْتُبُوا","يَكْتُبُونَ"],"The ن drops after لَمْ."],["How many present forms end in this ن ?",["five","three","ten"],"They are called the five verbs."],["Complete: يُرِيدُونَ أَنْ ___",["يَذْهَبُوا","يَذْهَبُونَ"],"The ن drops after أَنْ."]]],["Indeed: إِنَّ and its sisters","إِنَّ اللهَ غَفُورٌ",["إِنَّ enters a nominal sentence for emphasis. The subject after it takes fathah and the information stays in dammah.","Its sisters work the same way: أَنَّ that, لٰكِنَّ but, كَأَنَّ as if, لَيْتَ if only, لَعَلَّ perhaps."],[["إِنَّ اللهَ غَفُورٌ رَحِيمٌ","Indeed Allah is Forgiving, Merciful"],["إِنَّ الْبَيْتَ كَبِيرٌ","Indeed the house is big"],["أَعْلَمُ أَنَّ الدَّرْسَ سَهْلٌ","I know that the lesson is easy"],["لَعَلَّ الْمُدَرِّسَ مَرِيضٌ","Perhaps the teacher is ill"],["إِنَّهُ طَالِبٌ","Indeed he is a student"]],[["Complete: إِنَّ ___ جَدِيدٌ",["الْكِتَابَ","الْكِتَابُ","الْكِتَابِ"],"The subject after إِنَّ takes fathah."],["What does لَعَلَّ mean?",["perhaps","but","as if"],"لَعَلَّ expresses hope or possibility."],["After إِنَّ the subject takes…",["fathah","dammah","kasrah"],"إِنَّ makes its noun mansoob."]]],["Was: كَانَ","كَانَ الْبَيْتُ كَبِيرًا",["كَانَ puts a nominal sentence in the past. The subject stays in dammah and the information takes fathah.","It changes like any verb: كَانَتْ، كُنْتُ، كَانُوا. Present: يَكُونُ."],[["كَانَ الْبَيْتُ كَبِيرًا","The house was big"],["كَانَتِ السَّيَّارَةُ جَدِيدَةً","The car was new"],["كُنْتُ مَرِيضًا","I was ill"],["كَانَ اللهُ غَفُورًا رَحِيمًا","Allah is ever Forgiving, Merciful"],["كَانُوا مُسْلِمِينَ","They were Muslims"]],[["Complete: كَانَ الدَّرْسُ ___",["سَهْلًا","سَهْلٌ","سَهْلٍ"],"The information after كَانَ takes fathah."],["What does كُنْتُ mean?",["I was","he was","we were"],"ـْتُ marks 'I'."],["With كَانَ, which part takes fathah?",["the information (خَبَر)","the subject","both parts"],"This is the opposite of إِنَّ."]]],["Is not: لَيْسَ","لَيْسَ الْبَيْتُ كَبِيرًا",["لَيْسَ negates a nominal sentence. Like كَانَ, its information takes fathah, or comes with بِـ.","Forms: لَيْسَ، لَيْسَتْ، لَسْتُ، لَسْتَ، لَسْنَا."],[["لَيْسَ الْبَيْتُ كَبِيرًا","The house is not big"],["لَيْسَتِ السَّيَّارَةُ جَدِيدَةً","The car is not new"],["لَسْتُ طَبِيبًا","I am not a doctor"],["لَيْسَ الدَّرْسُ بِصَعْبٍ","The lesson is not difficult"]],[["What does لَسْتُ mean?",["I am not","he is not","we are not"],"ـْتُ marks 'I'."],["Complete: لَيْسَ الْبَيْتُ ___",["بَعِيدًا","بَعِيدٌ"],"The information after لَيْسَ takes fathah."],["لَيْسَتْ is used with…",["a feminine subject","a masculine subject","the word أَنَا"],"ـَتْ marks the feminine."]]],["Became, still: sisters of كَانَ","أَصْبَحَ · صَارَ · مَا زَالَ",["These verbs work like كَانَ: subject in dammah, information in fathah.","أَصْبَحَ and صَارَ became, ظَلَّ remained, مَا زَالَ is still, مَا دَامَ as long as."],[["صَارَ الْوَلَدُ رَجُلًا","The boy became a man"],["أَصْبَحَ الْجَوُّ بَارِدًا","The weather became cold"],["مَا زَالَ الْمَطَرُ نَازِلًا","The rain is still falling"],["ظَلَّ الطَّالِبُ جَالِسًا","The student remained seated"]],[["What does صَارَ mean?",["became","was","is not"],"صَارَ shows a change of state."],["What does مَا زَالَ mean?",["is still","was never","became"],"مَا زَالَ shows that something continues."],["Complete: أَصْبَحَ الْجَوُّ ___",["حَارًّا","حَارٌّ"],"The information takes fathah."]]],["Numbers 11 to 19","أَحَدَ عَشَرَ",["11 and 12 match the counted noun in gender. From 13 to 19 the first part takes the opposite gender and the ten matches.","Both parts end in fathah, except in 12. The counted noun is singular with tanween fathah."],[["أَحَدَ عَشَرَ كَوْكَبًا","eleven stars"],["اِثْنَا عَشَرَ شَهْرًا","twelve months"],["ثَلَاثَةَ عَشَرَ طَالِبًا","thirteen students"],["خَمْسَ عَشْرَةَ سَيَّارَةً","fifteen cars"],["تِسْعَةَ عَشَرَ","nineteen"]],[["Which number is أَحَدَ عَشَرَ ?",["11","12","21"],"أَحَدَ عَشَرَ is eleven."],["Complete: ثَلَاثَةَ عَشَرَ ___",["طَالِبًا","طُلَّابٍ","طَالِبٌ"],"After 11 to 99 the noun is singular with tanween fathah."],["What does اِثْنَا عَشَرَ شَهْرًا mean?",["twelve months","two months","ten months"],"اِثْنَا عَشَرَ is twelve."]]],["Tens, hundreds, thousands","عِشْرُونَ · مِئَةٌ · أَلْفٌ",["Tens: عِشْرُونَ 20, ثَلَاثُونَ 30, أَرْبَعُونَ 40, خَمْسُونَ 50, up to تِسْعُونَ 90. In nasb and jarr they end in ـِينَ.","The unit comes first: خَمْسَةٌ وَعِشْرُونَ is 25.","After مِئَةٌ (100) and أَلْفٌ (1000) the noun is singular with kasrah."],[["عِشْرُونَ طَالِبًا","twenty students"],["خَمْسَةٌ وَعِشْرُونَ","twenty-five"],["خَمْسُونَ رِيَالًا","fifty riyals"],["مِئَةُ كِتَابٍ","a hundred books"],["أَلْفُ سَنَةٍ","a thousand years"]],[["Which number is ثَلَاثُونَ ?",["30","3","13"],"ثَلَاثُونَ is thirty."],["Complete: مِئَةُ ___",["كِتَابٍ","كِتَابًا","كُتُبٌ"],"After مِئَةٌ the noun is singular with kasrah."],["Which number is خَمْسَةٌ وَعِشْرُونَ ?",["25","52","15"],"The unit is said first."]]],["First, second, third","الْأَوَّلُ · الثَّانِي",["Ordinals follow the shape فَاعِل and behave like describing words: they come after the noun and match it.","'First' is irregular: الْأَوَّلُ (masculine), الْأُولَى (feminine)."],[["الدَّرْسُ الْأَوَّلُ","the first lesson"],["السَّنَةُ الْأُولَى","the first year"],["الْيَوْمُ الثَّانِي","the second day"],["الْبَابُ الثَّالِثُ","the third door"],["الصَّفْحَةُ الْخَامِسَةُ","the fifth page"]],[["What does الثَّالِثُ mean?",["the third","three","the thirtieth"],"It is the ordinal of ثَلَاثَةٌ."],["How do you say 'the first year'?",["السَّنَةُ الْأُولَى","السَّنَةُ الْأَوَّلُ","الْأَوَّلُ سَنَةٌ"],"السَّنَةُ is feminine, so it takes الْأُولَى."],["What does الْخَامِسُ mean?",["the fifth","the fourth","five"],"It is the ordinal of خَمْسَةٌ."]]],["Telling the time","كَمِ السَّاعَةُ؟",["Ask كَمِ السَّاعَةُ؟ and answer with the feminine ordinal: السَّاعَةُ الثَّالِثَةُ. One o'clock is السَّاعَةُ الْوَاحِدَةُ.","وَالنِّصْفُ half past, وَالرُّبْعُ quarter past, إِلَّا رُبْعًا quarter to."],[["كَمِ السَّاعَةُ الْآنَ؟","What time is it now?"],["السَّاعَةُ الْوَاحِدَةُ","It is one o'clock"],["السَّاعَةُ الْخَامِسَةُ وَالنِّصْفُ","It is half past five"],["السَّاعَةُ الثَّامِنَةُ إِلَّا رُبْعًا","It is quarter to eight"],["أَنَامُ السَّاعَةَ الْعَاشِرَةَ","I sleep at ten o'clock"]],[["What does السَّاعَةُ الثَّالِثَةُ mean?",["It is three o'clock","It is thirty minutes past","It is the third day"],"The hour uses the feminine ordinal."],["What does وَالنِّصْفُ mean?",["half past","quarter past","quarter to"],"نِصْفٌ is 'half'."],["What does كَمِ السَّاعَةُ؟ mean?",["What time is it?","Whose watch is this?","Where is the watch?"],"It is the usual way to ask the time."]]],["The Islamic months","رَمَضَانُ · ذُو الْحِجَّةِ",["The Islamic year has twelve lunar months.","مُحَرَّمٌ، صَفَرٌ، رَبِيعٌ الْأَوَّلُ، رَبِيعٌ الْآخِرُ، جُمَادَى الْأُولَى، جُمَادَى الْآخِرَةُ، رَجَبٌ، شَعْبَانُ، رَمَضَانُ، شَوَّالٌ، ذُو الْقَعْدَةِ، ذُو الْحِجَّةِ."],[["نَصُومُ فِي شَهْرِ رَمَضَانَ","We fast in the month of Ramadan"],["الْحَجُّ فِي ذِي الْحِجَّةِ","The Hajj is in Dhul-Hijjah"],["مُحَرَّمٌ أَوَّلُ شَهْرٍ فِي السَّنَةِ","Muharram is the first month of the year"],["عِيدُ الْفِطْرِ فِي شَوَّالٍ","Eid al-Fitr is in Shawwal"]],[["Which is the month of fasting?",["رَمَضَانُ","شَوَّالٌ","رَجَبٌ"],"Muslims fast in Ramadan."],["Which is the first month of the year?",["مُحَرَّمٌ","صَفَرٌ","شَعْبَانُ"],"The year begins with Muharram."],["In which month is the Hajj?",["ذُو الْحِجَّةِ","ذُو الْقَعْدَةِ","رَمَضَانُ"],"Its name means 'the month of the Hajj'."]]],["Roots and patterns","ك ت ب",["Most Arabic words grow from a three-letter root that carries the core meaning.","Patterns add vowels and letters around the root to build related words.","Scholars use ف ع ل as a model: كَاتِبٌ is on the pattern فَاعِلٌ."],[["كَتَبَ","he wrote"],["كِتَابٌ","a book"],["كَاتِبٌ","a writer"],["مَكْتُوبٌ","written"],["مَكْتَبٌ","a desk, an office"],["مَكْتَبَةٌ","a library"]],[["What is the root of مَكْتَبَةٌ ?",["ك ت ب","م ك ت","ت ب ة"],"The م and ة are added letters."],["Which pattern is كَاتِبٌ on?",["فَاعِلٌ","مَفْعُولٌ","فِعَالٌ"],"Alif after the first root letter and kasrah on the second."],["How many letters do most roots have?",["three","two","five"],"Most roots are three letters."]]],["Doubled verbs","حَجَّ · ظَنَّ · مَرَّ",["When the second and third root letters are the same they merge with a shaddah: حَجَّ.","They separate when the ending starts with a consonant: حَجَجْتُ."],[["حَجَّ يَحُجُّ","to perform Hajj"],["ظَنَّ يَظُنُّ","to think, suppose"],["مَرَّ يَمُرُّ","to pass by"],["رَدَّ يَرُدُّ","to return, answer"],["حَجَجْتُ الْبَيْتَ","I performed Hajj to the House"],["ظَنَنْتُ أَنَّهُ مَرِيضٌ","I thought that he was ill"]],[["How do you say 'I performed Hajj'?",["حَجَجْتُ","حَجَّتُ","حَجْتُ"],"The doubled letter separates before ـْتُ."],["What does يَظُنُّ mean?",["he thinks","he thought","I think"],"It is the present of ظَنَّ."],["What is the present of مَرَّ ?",["يَمُرُّ","يَمَرُّ","يَمِرُّ"],"The present takes dammah."]]],["Hollow verbs","قَالَ يَقُولُ",["The middle root letter is و or ي. In the past it appears as alif: قَالَ، بَاعَ.","The alif drops when the ending begins with a sukoon: قُلْتُ، بِعْتُ، نِمْتُ.","The present shows the weak letter, يَقُولُ، يَبِيعُ, or keeps alif: يَنَامُ."],[["قَالَ يَقُولُ","to say"],["كَانَ يَكُونُ","to be"],["صَامَ يَصُومُ","to fast"],["بَاعَ يَبِيعُ","to sell"],["نَامَ يَنَامُ","to sleep"],["قُلْتُ الْحَقَّ","I said the truth"],["قُلْ","Say!"]],[["How do you say 'I said'?",["قُلْتُ","قَالْتُ","قَوَلْتُ"],"The alif drops before ـْتُ."],["What is the present of بَاعَ ?",["يَبِيعُ","يَبُوعُ","يَبَاعُ"],"Its middle root letter is ي."],["What does قُلْ mean?",["Say!","he said","I say"],"It is the command of قَالَ."]]],["Verbs ending in a weak letter","دَعَا يَدْعُو",["The last root letter is و or ي: دَعَا، مَشَى، نَسِيَ.","In the past the weak letter returns before endings: دَعَوْتُ، مَشَيْتُ.","In the jussive and the command the weak letter drops: لَمْ يَدْعُ، اِمْشِ."],[["دَعَا يَدْعُو","to call, supplicate"],["مَشَى يَمْشِي","to walk"],["بَكَى يَبْكِي","to weep"],["نَسِيَ يَنْسَى","to forget"],["هَدَى يَهْدِي","to guide"],["دَعَوْتُ اللهَ","I supplicated to Allah"],["مَشَيْتُ إِلَى الْمَسْجِدِ","I walked to the mosque"]],[["How do you say 'I walked'?",["مَشَيْتُ","مَشَاتُ","مَشَتُ"],"The ي returns before ـْتُ."],["What does يَدْعُو mean?",["he supplicates","he supplicated","I supplicate"],"It is the present of دَعَا."],["What does نَسِيَ mean?",["he forgot","he walked","he wept"],"نَسِيَ يَنْسَى is 'to forget'."]]],["Verbs starting with و","وَصَلَ يَصِلُ",["When the first root letter is و, it usually drops in the present: وَصَلَ becomes يَصِلُ.","It also drops in the command: صِلْ، قِفْ، ضَعْ."],[["وَصَلَ يَصِلُ","to arrive"],["وَجَدَ يَجِدُ","to find"],["وَقَفَ يَقِفُ","to stand, stop"],["وَضَعَ يَضَعُ","to put"],["وَعَدَ يَعِدُ","to promise"],["قِفْ هُنَا","Stop here!"],["ضَعِ الْكِتَابَ عَلَى الْمَكْتَبِ","Put the book on the desk"]],[["What is the present of وَجَدَ ?",["يَجِدُ","يَوْجِدُ","يَوْجَدُ"],"The و drops in the present."],["What does قِفْ mean?",["Stop!","he stopped","I stop"],"It is the command of وَقَفَ."],["What does وَصَلَ mean?",["he arrived","he found","he put"],"وَصَلَ يَصِلُ is 'to arrive'."]]],["Verbs with hamzah","أَكَلَ · سَأَلَ · قَرَأَ",["Hamzah can be the first, middle or last root letter. Its seat changes with the vowels around it.","Two commands are short: كُلْ eat, خُذْ take.","'I eat' is آكُلُ, where two hamzahs merge into a long alif."],[["أَكَلَ يَأْكُلُ","to eat"],["أَخَذَ يَأْخُذُ","to take"],["سَأَلَ يَسْأَلُ","to ask"],["قَرَأَ يَقْرَأُ","to read"],["كُلْ بِيَمِينِكَ","Eat with your right hand"],["آكُلُ التَّمْرَ","I eat dates"]],[["What is the command of أَكَلَ ?",["كُلْ","أَكَلْ","يَأْكُلْ"],"The hamzah drops in this command."],["How do you say 'I eat'?",["آكُلُ","يَأْكُلُ","أَكَلْتُ"],"The two hamzahs merge into آ."],["What does خُذْ mean?",["Take!","he took","I take"],"It is the command of أَخَذَ."]]],["Form II: فَعَّلَ","عَلَّمَ يُعَلِّمُ",["Doubling the middle letter often means making someone do the action, or doing it intensely: عَلِمَ knew, عَلَّمَ taught.","Present: يُفَعِّلُ, with dammah on the first letter. Verbal noun: تَفْعِيلٌ."],[["عَلَّمَ يُعَلِّمُ","to teach"],["دَرَّسَ يُدَرِّسُ","to teach a class"],["كَبَّرَ يُكَبِّرُ","to say Allahu akbar"],["سَبَّحَ يُسَبِّحُ","to glorify Allah"],["صَلَّى يُصَلِّي","to pray"],["تَعْلِيمٌ","teaching"]],[["What does عَلَّمَ mean?",["he taught","he knew","he learnt"],"Form II of 'to know' is 'to teach'."],["What is the present of دَرَّسَ ?",["يُدَرِّسُ","يَدْرُسُ","يَدَرِّسُ"],"Form II presents start with dammah."],["What is the verbal noun of عَلَّمَ ?",["تَعْلِيمٌ","عِلْمٌ","مُعَلِّمٌ"],"Form II verbal nouns follow تَفْعِيلٌ."]]],["Form III: فَاعَلَ","سَافَرَ يُسَافِرُ",["An alif after the first root letter often shows an action done with or towards someone.","Present: يُفَاعِلُ. Verbal noun: مُفَاعَلَةٌ or فِعَالٌ."],[["سَافَرَ يُسَافِرُ","to travel"],["قَابَلَ يُقَابِلُ","to meet"],["سَاعَدَ يُسَاعِدُ","to help"],["جَاهَدَ يُجَاهِدُ","to strive"],["حَاوَلَ يُحَاوِلُ","to try"],["شَاهَدَ يُشَاهِدُ","to watch"]],[["What does سَافَرَ mean?",["he travelled","he helped","he met"],"سَافَرَ is 'to travel'."],["What is the present of سَاعَدَ ?",["يُسَاعِدُ","يَسْعَدُ","يَسَاعِدُ"],"Form III presents start with dammah."],["جِهَادٌ is the verbal noun of…",["جَاهَدَ","سَافَرَ","قَابَلَ"],"It follows the shape فِعَالٌ."]]],["Form IV: أَفْعَلَ","أَسْلَمَ يُسْلِمُ",["A hamzah at the front often makes the verb causative: نَزَلَ came down, أَنْزَلَ sent down.","Present: يُفْعِلُ. The command أَفْعِلْ begins with a hamzah that is always pronounced. Verbal noun: إِفْعَالٌ."],[["أَسْلَمَ يُسْلِمُ","to submit, to accept Islam"],["أَرْسَلَ يُرْسِلُ","to send"],["أَنْزَلَ يُنْزِلُ","to send down"],["أَخْرَجَ يُخْرِجُ","to take out"],["أَكْرَمَ يُكْرِمُ","to honour"],["إِسْلَامٌ","submission"]],[["What does أَنْزَلَ mean?",["he sent down","he came down","he went out"],"Form IV makes the verb causative."],["What is the present of أَرْسَلَ ?",["يُرْسِلُ","يَرْسِلُ","يُرَسِّلُ"],"Form IV presents follow يُفْعِلُ."],["What is the verbal noun of أَسْلَمَ ?",["إِسْلَامٌ","سَلَامٌ","مُسْلِمٌ"],"Form IV verbal nouns follow إِفْعَالٌ."]]],["Forms V and VI: تَفَعَّلَ and تَفَاعَلَ","تَعَلَّمَ · تَعَاوَنَ",["Adding تَـ to Form II gives its result: عَلَّمَ taught, تَعَلَّمَ learnt.","Adding تَـ to Form III gives a shared action: تَعَاوَنَ, to help one another.","Present: يَتَفَعَّلُ and يَتَفَاعَلُ, with fathah on the first letter."],[["تَعَلَّمَ يَتَعَلَّمُ","to learn"],["تَكَلَّمَ يَتَكَلَّمُ","to speak"],["تَوَضَّأَ يَتَوَضَّأُ","to make wudoo"],["تَذَكَّرَ يَتَذَكَّرُ","to remember"],["تَعَاوَنَ يَتَعَاوَنُ","to cooperate"],["أَتَعَلَّمُ الْعَرَبِيَّةَ","I am learning Arabic"]],[["What does تَعَلَّمَ mean?",["he learnt","he taught","he knew"],"Form V gives the result of Form II."],["What does يَتَكَلَّمُ mean?",["he speaks","he spoke","he teaches"],"It is the present of تَكَلَّمَ."],["What does تَعَاوَنَ mean?",["to help one another","to travel","to learn"],"Form VI shows a shared action."]]],["Forms VII and VIII: اِنْفَعَلَ and اِفْتَعَلَ","اِنْكَسَرَ · اِجْتَمَعَ",["اِنْفَعَلَ shows that something happened to the subject: كَسَرَ broke, اِنْكَسَرَ got broken.","اِفْتَعَلَ adds ت after the first root letter: جَمَعَ gathered, اِجْتَمَعَ assembled.","Both begin with a helping alif that drops in connected speech."],[["اِنْكَسَرَ يَنْكَسِرُ","to get broken"],["اِنْفَتَحَ يَنْفَتِحُ","to open by itself"],["اِجْتَمَعَ يَجْتَمِعُ","to assemble"],["اِسْتَمَعَ يَسْتَمِعُ","to listen"],["اِنْتَظَرَ يَنْتَظِرُ","to wait"],["اِجْتَهَدَ يَجْتَهِدُ","to work hard"]],[["What does اِنْكَسَرَ mean?",["it got broken","he broke it","he will break"],"Form VII shows what happened to the subject."],["What does اِسْتَمَعَ mean?",["he listened","he gathered","he waited"],"It is Form VIII of سَمِعَ."],["What is the present of اِنْتَظَرَ ?",["يَنْتَظِرُ","يَنْظُرُ","يُنْتَظِرُ"],"Form VIII presents follow يَفْتَعِلُ."]]],["Form X: اِسْتَفْعَلَ","اِسْتَغْفَرَ يَسْتَغْفِرُ",["The prefix اِسْتَـ often means to seek or ask for something: غَفَرَ forgave, اِسْتَغْفَرَ asked for forgiveness.","Present: يَسْتَفْعِلُ. Verbal noun: اِسْتِفْعَالٌ."],[["اِسْتَغْفَرَ يَسْتَغْفِرُ","to seek forgiveness"],["اِسْتَعْمَلَ يَسْتَعْمِلُ","to use"],["اِسْتَقْبَلَ يَسْتَقْبِلُ","to receive, welcome"],["اِسْتَيْقَظَ يَسْتَيْقِظُ","to wake up"],["أَسْتَغْفِرُ اللهَ","I seek Allah's forgiveness"]],[["What does اِسْتَغْفَرَ mean?",["he sought forgiveness","he forgave","he was forgiven"],"اِسْتَـ adds the meaning of seeking."],["What does أَسْتَغْفِرُ اللهَ mean?",["I seek Allah's forgiveness","I thank Allah","I praise Allah"],"It is the 'I' form of the present."],["What does اِسْتَيْقَظَ mean?",["he woke up","he used","he welcomed"],"اِسْتَيْقَظَ is 'to wake up'."]]],["The passive","كُتِبَ · يُكْتَبُ",["When the doer is not mentioned the verb changes its vowels. Past: dammah on the first letter and kasrah before the last: كَتَبَ becomes كُتِبَ.","Present: dammah on the first letter and fathah before the last: يَكْتُبُ becomes يُكْتَبُ.","The former object becomes the deputy doer (نَائِبُ الْفَاعِلِ) and takes dammah."],[["كُتِبَ الدَّرْسُ","The lesson was written"],["فُتِحَ الْبَابُ","The door was opened"],["خُلِقَ الْإِنْسَانُ ضَعِيفًا","Man was created weak"],["يُفْتَحُ الْبَابُ","The door is opened"]],[["What is the passive of فَتَحَ ?",["فُتِحَ","فَتِحَ","فُتَحَ"],"Dammah on the first letter and kasrah before the last."],["What does كُتِبَ الدَّرْسُ mean?",["The lesson was written","He wrote the lesson","Write the lesson"],"The doer is not mentioned."],["What does يُكْتَبُ mean?",["it is written","he writes","it was written"],"It is the present passive."]]],["The doer noun","كَاتِبٌ · مُدَرِّسٌ",["From a simple verb, the doer noun (اِسْمُ الْفَاعِلِ) follows فَاعِلٌ: كَتَبَ gives كَاتِبٌ.","From longer verbs, take the present, replace its first letter with مُـ and put kasrah before the last letter: يُدَرِّسُ gives مُدَرِّسٌ."],[["كَاتِبٌ","writer"],["عَالِمٌ","scholar"],["صَائِمٌ","one who is fasting"],["مُسْلِمٌ","one who submits"],["مُدَرِّسٌ","teacher"],["مُسَافِرٌ","traveller"],["مُؤْمِنٌ","believer"]],[["What is the doer noun of كَتَبَ ?",["كَاتِبٌ","مَكْتُوبٌ","كِتَابٌ"],"Simple verbs follow فَاعِلٌ."],["What does مُسَافِرٌ mean?",["traveller","travel","he travelled"],"It is the doer noun of سَافَرَ."],["What is the doer noun from يُعَلِّمُ ?",["مُعَلِّمٌ","مُعَلَّمٌ","عَالِمٌ"],"مُـ at the front and kasrah before the last letter."]]],["The done-to noun","مَكْتُوبٌ · مَفْتُوحٌ",["From a simple verb, the passive participle (اِسْمُ الْمَفْعُولِ) follows مَفْعُولٌ: كَتَبَ gives مَكْتُوبٌ.","From longer verbs it is like the doer noun but with fathah before the last letter: مُعَلَّمٌ, one who is taught."],[["مَكْتُوبٌ","written"],["مَفْتُوحٌ","open, opened"],["مَعْلُومٌ","known"],["مَشْهُورٌ","famous"],["مَسْؤُولٌ","responsible, asked"],["الْبَابُ مَفْتُوحٌ","The door is open"]],[["What is the passive participle of فَتَحَ ?",["مَفْتُوحٌ","فَاتِحٌ","مِفْتَاحٌ"],"Simple verbs follow مَفْعُولٌ."],["What does مَعْلُومٌ mean?",["known","knowing","teacher"],"It is the thing that is known."],["Which pattern is مَكْتُوبٌ on?",["مَفْعُولٌ","فَاعِلٌ","فَعِيلٌ"],"مَـ at the front and و before the last letter."]]],["The verbal noun","الْمَصْدَرُ",["The verbal noun names the action itself: reading, entering, patience.","For simple verbs its shape must be learnt with each verb. For Forms II to X it follows fixed patterns such as تَفْعِيلٌ، إِفْعَالٌ، اِسْتِفْعَالٌ."],[["دَخَلَ ← دُخُولٌ","to enter → entering"],["خَرَجَ ← خُرُوجٌ","to go out → going out"],["قَرَأَ ← قِرَاءَةٌ","to read → reading"],["صَبَرَ ← صَبْرٌ","to be patient → patience"],["شَرِبَ ← شُرْبٌ","to drink → drinking"],["عَلَّمَ ← تَعْلِيمٌ","to teach → teaching"]],[["What is the verbal noun of دَخَلَ ?",["دُخُولٌ","دَاخِلٌ","مَدْخَلٌ"],"دُخُولٌ is 'entering'."],["What does قِرَاءَةٌ mean?",["reading","reader","he read"],"It is the verbal noun of قَرَأَ."],["What does صَبْرٌ mean?",["patience","patient","be patient"],"It is the verbal noun of صَبَرَ."]]],["Nouns of place, time and tool","مَسْجِدٌ · مِفْتَاحٌ",["مَفْعَلٌ and مَفْعِلٌ name the place or time of an action: مَسْجِدٌ, the place of prostration.","مِفْعَالٌ، مِفْعَلٌ and مِفْعَلَةٌ name the tool: مِفْتَاحٌ, the tool for opening."],[["مَسْجِدٌ","place of prostration"],["مَكْتَبٌ","place of writing: desk, office"],["مَطْبَخٌ","place of cooking: kitchen"],["مَغْرِبٌ","time and place of sunset"],["مِفْتَاحٌ","key"],["مِكْنَسَةٌ","broom"]],[["مَطْبَخٌ is a noun of…",["place","tool","doer"],"It is where cooking happens."],["مِفْتَاحٌ is a noun of…",["tool","place","time"],"It is the tool for opening."],["What is the root of مَسْجِدٌ ?",["س ج د","م س ج","ج د م"],"The م is an added letter."]]],["How it happened: the haal","جَاءَ رَاكِبًا",["The haal (حَال) describes the state of the doer or the object while the action happens.","It is indefinite and takes fathah."],[["جَاءَ الْوَلَدُ رَاكِبًا","The boy came riding"],["دَخَلَ الْمُدَرِّسُ مُبْتَسِمًا","The teacher entered smiling"],["رَجَعَ الطَّالِبُ مَسْرُورًا","The student returned happy"],["صَلَّى قَائِمًا","He prayed standing"],["شَرِبْتُ الْمَاءَ بَارِدًا","I drank the water cold"]],[["Complete: جَاءَ الْوَلَدُ ___",["مَاشِيًا","الْمَاشِي"],"The haal is indefinite and takes fathah."],["The haal ends in…",["fathah","dammah","kasrah"],"The haal is mansoob."],["What does صَلَّى قَائِمًا mean?",["He prayed standing","He stood after praying","The one standing prayed"],"قَائِمًا describes his state while praying."]]],["Clearing up: the tamyeez","عِشْرُونَ كِتَابًا",["The tamyeez (تَمْيِيز) is an indefinite noun in fathah that removes vagueness.","It follows the numbers 11 to 99, measures, and comparisons such as 'more in knowledge'."],[["عِشْرُونَ كِتَابًا","twenty books"],["عِنْدِي لِتْرٌ حَلِيبًا","I have a litre of milk"],["أَنَا أَكْثَرُ مِنْكَ مَالًا","I have more wealth than you"],["هُوَ أَحْسَنُ خُلُقًا","He is better in character"],["كَمْ طَالِبًا فِي الْفَصْلِ؟","How many students are in the class?"]],[["Complete: عِشْرُونَ ___",["قَلَمًا","قَلَمٍ","أَقْلَامٌ"],"The tamyeez is singular with tanween fathah."],["The tamyeez ends in…",["fathah","dammah","kasrah"],"The tamyeez is mansoob."],["What does أَحْسَنُ خُلُقًا mean?",["better in character","a good character","his character is good"],"خُلُقًا tells in what way he is better."]]],["Emphasis with the verbal noun","صَبَرَ صَبْرًا",["The absolute object (الْمَفْعُولُ الْمُطْلَقُ) repeats the verb's own verbal noun in fathah.","It stresses the action. With a description or a number it tells its kind or how many times."],[["فَهِمْتُ الدَّرْسَ فَهْمًا","I really understood the lesson"],["صَبَرَ صَبْرًا جَمِيلًا","He was beautifully patient"],["وَكَلَّمَ اللهُ مُوسَى تَكْلِيمًا","And Allah spoke to Musa directly"],["سَجَدَ سَجْدَتَيْنِ","He prostrated twice"]],[["Complete: صَبَرَ ___ جَمِيلًا",["صَبْرًا","صَبْرٌ","صَابِرًا"],"It is the verbal noun in fathah."],["The absolute object is the verb's own…",["verbal noun","doer","tool"],"It repeats the action as a noun."],["What does سَجَدَ سَجْدَتَيْنِ mean?",["He prostrated twice","Two men prostrated","He prostrated in two mosques"],"The dual shows the number of times."]]],["Why it was done","قُمْتُ إِكْرَامًا لَهُ",["The object of reason (الْمَفْعُولُ لِأَجْلِهِ) is a verbal noun in fathah that gives the motive for the action.","It answers the question لِمَاذَا؟"],[["قُمْتُ إِكْرَامًا لِلْمُدَرِّسِ","I stood up out of respect for the teacher"],["نَصُومُ طَاعَةً لِلَّهِ","We fast in obedience to Allah"],["لَمْ أَخْرُجْ خَوْفًا مِنَ الْمَطَرِ","I did not go out for fear of the rain"],["أَدْرُسُ طَلَبًا لِلْعِلْمِ","I study seeking knowledge"]],[["What does خَوْفًا مِنَ الْمَطَرِ mean?",["for fear of the rain","in the rain","after the rain"],"خَوْفًا gives the reason."],["It answers the question…",["لِمَاذَا","مَتَى","أَيْنَ"],"It tells why the action was done."],["Complete: نَصُومُ ___ لِلَّهِ",["طَاعَةً","طَاعَةٌ"],"The object of reason takes fathah."]]],["Except: إِلَّا","إِلَّا",["In a positive sentence the noun after إِلَّا takes fathah: حَضَرَ الطُّلَّابُ إِلَّا خَالِدًا.","When the sentence is negative and the group is not mentioned, the noun takes whatever case its job needs: مَا حَضَرَ إِلَّا خَالِدٌ."],[["حَضَرَ الطُّلَّابُ إِلَّا خَالِدًا","The students came except Khalid"],["مَا حَضَرَ إِلَّا خَالِدٌ","None came except Khalid"],["لَا إِلٰهَ إِلَّا اللهُ","There is none worthy of worship except Allah"],["مَا رَأَيْتُ إِلَّا خَالِدًا","I saw no one except Khalid"]],[["Complete: حَضَرَ الطُّلَّابُ إِلَّا ___",["مُحَمَّدًا","مُحَمَّدٌ","مُحَمَّدٍ"],"In a positive sentence the excepted noun takes fathah."],["What does إِلَّا mean?",["except","until","because"],"إِلَّا takes something out of a group."],["Complete: مَا حَضَرَ إِلَّا ___",["خَالِدٌ","خَالِدًا"],"Here Khalid is the doer, so he takes dammah."]]],["Calling someone: يَا","يَا خَالِدُ",["يَا calls a person. A single name after it ends in one dammah without tanween: يَا خَالِدُ.","If the one called is the first word of an idaafah it takes fathah: يَا عَبْدَ اللهِ.","Before a word with الـ use يَا أَيُّهَا (masculine) or يَا أَيَّتُهَا (feminine)."],[["يَا خَالِدُ","O Khalid"],["يَا رَبِّ","O my Lord"],["يَا عَبْدَ اللهِ","O Abdullah"],["يَا أَيُّهَا النَّاسُ","O people"],["يَا أَيُّهَا الَّذِينَ آمَنُوا","O you who believe"]],[["Complete: يَا ___",["مُحَمَّدُ","مُحَمَّدٌ","مُحَمَّدًا"],"A single name takes one dammah without tanween."],["Complete: يَا ___ اللهِ",["عَبْدَ","عَبْدُ"],"The first word of an idaafah takes fathah after يَا."],["What comes before النَّاسُ when calling?",["يَا أَيُّهَا","يَا","أَيُّ"],"A word with الـ needs أَيُّهَا."]]],["If: إِنْ and its sisters","إِنْ تَدْرُسْ تَنْجَحْ",["إِنْ (if), مَنْ (whoever) and مَا (whatever) link a condition and its result.","Both present verbs end in sukoon (مَجْزُوم)."],[["إِنْ تَدْرُسْ تَنْجَحْ","If you study, you will succeed"],["مَنْ يَجْتَهِدْ يَنْجَحْ","Whoever works hard succeeds"],["إِنْ تَنْصُرُوا اللهَ يَنْصُرْكُمْ","If you help the cause of Allah, He will help you"]],[["Complete: إِنْ تَدْرُسْ ___",["تَنْجَحْ","تَنْجَحُ","تَنْجَحَ"],"Both verbs take sukoon."],["In مَنْ يَجْتَهِدْ يَنْجَحْ, the word مَنْ means…",["whoever","from","with"],"Here مَنْ is a conditional word."],["Verbs in a condition with إِنْ end in…",["sukoon","fathah","dammah"],"They are majzoom."]]],["When, and if only: إِذَا and لَوْ","إِذَا · لَوْ",["إِذَا means 'when' or 'whenever' for something expected. It is usually followed by a past verb with a future meaning.","لَوْ is for something that did not happen. Its answer often starts with لَـ."],[["إِذَا جَاءَ رَمَضَانُ صُمْنَا","When Ramadan comes, we fast"],["إِذَا سَمِعْتَ الْأَذَانَ فَأَجِبْ","When you hear the adhaan, respond"],["لَوِ اجْتَهَدْتَ لَنَجَحْتَ","Had you worked hard, you would have succeeded"],["لَوْ كَانَ عِنْدِي مَالٌ لَحَجَجْتُ","If I had money, I would have performed Hajj"]],[["What does إِذَا mean?",["when","if only","because"],"إِذَا is for something expected."],["لَوْ is used for…",["something that did not happen","something certain","a command"],"It imagines a different past."],["What does لَوِ اجْتَهَدْتَ لَنَجَحْتَ mean?",["Had you worked hard, you would have succeeded","You worked hard and succeeded","Work hard to succeed"],"لَوْ shows it did not happen."]]],["None at all: لَا of total negation","لَا إِلٰهَ إِلَّا اللهُ",["This لَا denies a whole kind. Its noun is indefinite and ends in a single fathah with no tanween.","The greatest example is the testimony of faith."],[["لَا إِلٰهَ إِلَّا اللهُ","There is none worthy of worship except Allah"],["لَا رَيْبَ فِيهِ","There is no doubt in it"],["لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ","There is no power and no strength except with Allah"],["لَا طَالِبَ فِي الْفَصْلِ","There is no student in the classroom"]],[["Complete: لَا ___ فِي الْفَصْلِ",["طَالِبَ","طَالِبٌ","طَالِبًا"],"The noun takes one fathah without tanween."],["What does لَا رَيْبَ فِيهِ mean?",["There is no doubt in it","Do not doubt it","He has no doubt"],"لَا denies every kind of doubt."],["The noun after this لَا has…",["one fathah, no tanween","tanween dammah","kasrah"],"It is built on fathah."]]],["How wonderful!","مَا أَجْمَلَ السَّمَاءَ",["To express wonder use مَا أَفْعَلَ followed by a noun in fathah.","The pattern is fixed: مَا, then أَفْعَلَ, then the thing admired."],[["مَا أَجْمَلَ السَّمَاءَ","How beautiful the sky is!"],["مَا أَكْبَرَ هٰذَا الْمَسْجِدَ","How big this mosque is!"],["مَا أَسْهَلَ الدَّرْسَ","How easy the lesson is!"],["مَا أَحْسَنَ خُلُقَهُ","How good his character is!"]],[["Complete: مَا أَجْمَلَ ___",["الْبَيْتَ","الْبَيْتُ","الْبَيْتِ"],"The thing admired takes fathah."],["What does مَا أَسْهَلَ الدَّرْسَ mean?",["How easy the lesson is!","The lesson is not easy","Which lesson is easiest?"],"It expresses wonder."],["Which pattern expresses wonder?",["مَا أَفْعَلَ","مَا فَعَلَ","أَفْعَلُ مِنْ"],"مَا أَفْعَلَ is the pattern of wonder."]]],["Himself, and all of them","نَفْسُهُ · كُلُّهُمْ",["نَفْسُ and عَيْنُ with a pronoun stress that it was the very person: الْمُدِيرُ نَفْسُهُ.","كُلُّ and جَمِيعُ with a pronoun stress that all are included: الطُّلَّابُ كُلُّهُمْ.","The emphasising word copies the case of the word before it."],[["جَاءَ الْمُدِيرُ نَفْسُهُ","The headmaster himself came"],["رَأَيْتُ الْمُدِيرَ نَفْسَهُ","I saw the headmaster himself"],["حَضَرَ الطُّلَّابُ كُلُّهُمْ","All the students attended"],["قَرَأْتُ الْكِتَابَ كُلَّهُ","I read the whole book"]],[["Complete: رَأَيْتُ الْمُدَرِّسَ ___",["نَفْسَهُ","نَفْسُهُ","نَفْسِهِ"],"It copies the fathah of the word before it."],["What does الطُّلَّابُ كُلُّهُمْ mean?",["all the students","some of the students","the students' books"],"كُلُّهُمْ stresses that none is left out."],["What does نَفْسُهُ mean here?",["himself","his book","like him"],"It stresses the very person."]]],["Talking about family","أُسْرَتِي",["Useful sentences for introducing your family.","كَمْ asks how many, and لِي says what relatives you have."],[["هٰذِهِ أُسْرَتِي","This is my family"],["أَبِي مُهَنْدِسٌ وَأُمِّي مُدَرِّسَةٌ","My father is an engineer and my mother is a teacher"],["لِي أَخٌ وَاحِدٌ وَأُخْتَانِ","I have one brother and two sisters"],["كَمْ أَخًا لَكَ؟","How many brothers do you have?"],["جَدِّي يَسْكُنُ مَعَنَا","My grandfather lives with us"],["أُحِبُّ أُسْرَتِي","I love my family"]],[["What does أُسْرَتِي mean?",["my family","my house","my sister"],"أُسْرَةٌ is 'family'."],["What does كَمْ أَخًا لَكَ؟ mean?",["How many brothers do you have?","Where is your brother?","Who is your brother?"],"كَمْ asks 'how many'."],["What does أُخْتَانِ mean?",["two sisters","a sister","many sisters"],"ـَانِ marks the dual."]]],["Where I live","أَيْنَ تَسْكُنُ؟",["يَسْكُنُ means 'he lives' in a place. شَقَّةٌ is a flat and دَوْرٌ is a floor.","Describe your home with the describing words you know."],[["أَيْنَ تَسْكُنُ؟","Where do you live?"],["أَسْكُنُ فِي شَقَّةٍ قَرِيبَةٍ مِنَ الْمَسْجِدِ","I live in a flat near the mosque"],["فِي الْبَيْتِ ثَلَاثُ غُرَفٍ","There are three rooms in the house"],["الْمَطْبَخُ صَغِيرٌ وَنَظِيفٌ","The kitchen is small and clean"],["أُرِيدُ شَقَّةً فِي الدَّوْرِ الثَّانِي","I want a flat on the second floor"],["بَيْتُنَا أَمَامَ الْحَدِيقَةِ","Our house is in front of the garden"]],[["What does أَيْنَ تَسْكُنُ؟ mean?",["Where do you live?","Where are you going?","What is your name?"],"يَسْكُنُ is 'to live in a place'."],["What does شَقَّةٌ mean?",["a flat","a street","a floor"],"شَقَّةٌ is a flat or apartment."],["What does ثَلَاثُ غُرَفٍ mean?",["three rooms","the third room","thirty rooms"],"غُرَفٌ is the plural of غُرْفَةٌ."]]],["My day","حَيَاتِي الْيَوْمِيَّةُ",["Daily actions in the 'I' form of the present tense.","Time words: فِي الصَّبَاحِ in the morning, بَعْدَ after, قَبْلَ before, ثُمَّ then."],[["أَسْتَيْقِظُ عِنْدَ الْفَجْرِ","I wake up at dawn"],["أُصَلِّي الْفَجْرَ فِي الْمَسْجِدِ","I pray Fajr in the mosque"],["أَتَنَاوَلُ الْفَطُورَ","I have breakfast"],["أَذْهَبُ إِلَى الْعَمَلِ بِالسَّيَّارَةِ","I go to work by car"],["أَرْجِعُ إِلَى الْبَيْتِ بَعْدَ الْعَصْرِ","I return home after Asr"],["أَنَامُ مُبَكِّرًا","I sleep early"]],[["What does أَسْتَيْقِظُ mean?",["I wake up","I sleep","I return"],"It is the 'I' form of اِسْتَيْقَظَ."],["What does بَعْدَ الْعَصْرِ mean?",["after Asr","before Asr","during Asr"],"بَعْدَ is 'after'."],["What does الْفَطُورُ mean?",["breakfast","lunch","dinner"],"الْفَطُورُ is the morning meal."]]],["At the table","مَاذَا تَأْكُلُ؟",["الْفَطُورُ breakfast, الْغَدَاءُ lunch, الْعَشَاءُ dinner.","أُرِيدُ I want, أُفَضِّلُ I prefer, تَفَضَّلْ here you are."],[["مَاذَا تَأْكُلُ فِي الْغَدَاءِ؟","What do you eat for lunch?"],["آكُلُ الْأَرُزَّ وَالدَّجَاجَ","I eat rice and chicken"],["مَاذَا تَشْرَبُ؟","What will you drink?"],["أَشْرَبُ الشَّايَ بِلَا سُكَّرٍ","I drink tea without sugar"],["أَنَا جَائِعٌ","I am hungry"],["بِسْمِ اللهِ","In the name of Allah (said before eating)"],["الْحَمْدُ لِلَّهِ","All praise is for Allah (said after eating)"]],[["What does الْغَدَاءُ mean?",["lunch","breakfast","dinner"],"الْغَدَاءُ is the midday meal."],["What does أَنَا جَائِعٌ mean?",["I am hungry","I am thirsty","I am tired"],"جَائِعٌ is 'hungry'."],["What do we say before eating?",["بِسْمِ اللهِ","مَعَ السَّلَامَةِ","كَيْفَ حَالُكَ؟"],"We begin with the name of Allah."]]],["Prayer times","أَيْنَ تُصَلِّي؟",["The five daily prayers: الْفَجْرُ، الظُّهْرُ، الْعَصْرُ، الْمَغْرِبُ، الْعِشَاءُ.","Useful verbs: يُصَلِّي prays, يَتَوَضَّأُ makes wudoo, يَسْمَعُ hears."],[["أَيْنَ تُصَلِّي الْفَجْرَ؟","Where do you pray Fajr?"],["أُصَلِّي فِي الْمَسْجِدِ","I pray in the mosque"],["أَتَوَضَّأُ قَبْلَ الصَّلَاةِ","I make wudoo before the prayer"],["هَلْ سَمِعْتَ الْأَذَانَ؟","Did you hear the adhaan?"],["حَانَ وَقْتُ الصَّلَاةِ","The time for prayer has come"],["الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ","Prayer is better than sleep"]],[["What does أَتَوَضَّأُ mean?",["I make wudoo","I pray","I hear"],"It is the 'I' form of تَوَضَّأَ."],["What does قَبْلَ الصَّلَاةِ mean?",["before the prayer","after the prayer","during the prayer"],"قَبْلَ is 'before'."],["What does الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ mean?",["Prayer is better than sleep","Pray before you sleep","Sleep after the prayer"],"خَيْرٌ مِنْ is 'better than'."]]],["At school","فِي الْمَدْرَسَةِ",["Subjects: الْقُرْآنُ، التَّفْسِيرُ، الْحَدِيثُ، الْفِقْهُ، اللُّغَةُ الْعَرَبِيَّةُ، الرِّيَاضِيَّاتُ.","يَدْرُسُ studies, يَبْدَأُ begins, يَنْتَهِي ends."],[["مَاذَا تَدْرُسُ؟","What do you study?"],["أَدْرُسُ اللُّغَةَ الْعَرَبِيَّةَ","I study the Arabic language"],["مَتَى يَبْدَأُ الدَّرْسُ؟","When does the lesson begin?"],["يَبْدَأُ السَّاعَةَ الثَّامِنَةَ","It begins at eight o'clock"],["فِي أَيِّ صَفٍّ أَنْتَ؟","Which class are you in?"],["الِاخْتِبَارُ غَدًا","The test is tomorrow"]],[["What does أَدْرُسُ اللُّغَةَ الْعَرَبِيَّةَ mean?",["I study the Arabic language","I teach Arabic","I speak Arabic"],"أَدْرُسُ is 'I study'."],["What does الِاخْتِبَارُ mean?",["the test","the lesson","the class"],"الِاخْتِبَارُ is a test or exam."],["What does مَتَى يَبْدَأُ الدَّرْسُ؟ mean?",["When does the lesson begin?","Where is the lesson?","Who teaches the lesson?"],"مَتَى is 'when'."]]],["At the market","بِكَمْ هٰذَا؟",["بِكَمْ؟ asks the price. يَشْتَرِي buys, يَبِيعُ sells.","رَخِيصٌ cheap, غَالٍ expensive."],[["بِكَمْ هٰذَا الْقَمِيصُ؟","How much is this shirt?"],["بِخَمْسِينَ رِيَالًا","For fifty riyals"],["هٰذَا غَالٍ","This is expensive"],["أُرِيدُ كِيلُو تُفَّاحٍ","I want a kilo of apples"],["هَلْ عِنْدَكَ خُبْزٌ؟","Do you have bread?"],["تَفَضَّلْ، هٰذَا الْبَاقِي","Here you are, this is the change"]],[["What does بِكَمْ هٰذَا؟ mean?",["How much is this?","What is this?","Whose is this?"],"بِكَمْ asks the price."],["What does غَالٍ mean?",["expensive","cheap","new"],"The opposite is رَخِيصٌ."],["What does يَشْتَرِي mean?",["he buys","he sells","he pays"],"يَبِيعُ is 'he sells'."]]],["Travel","السَّفَرُ",["جَوَازُ السَّفَرِ passport, تَذْكِرَةٌ ticket, مَطَارٌ airport, رِحْلَةٌ trip or flight.","إِنْ شَاءَ اللهُ, 'if Allah wills', is said about any future plan."],[["إِلَى أَيْنَ تُسَافِرُ؟","Where are you travelling to?"],["أُسَافِرُ إِلَى الْمَدِينَةِ الْمُنَوَّرَةِ","I am travelling to Madinah"],["أَيْنَ جَوَازُ السَّفَرِ؟","Where is the passport?"],["مَتَى تُقْلِعُ الطَّائِرَةُ؟","When does the plane take off?"],["أُرِيدُ تَذْكِرَةً إِلَى جُدَّةَ","I want a ticket to Jeddah"],["سَأُسَافِرُ غَدًا إِنْ شَاءَ اللهُ","I will travel tomorrow, if Allah wills"]],[["What does جَوَازُ السَّفَرِ mean?",["passport","ticket","airport"],"Word for word it is 'permit of travel'."],["What does تَذْكِرَةٌ mean?",["ticket","flight","bag"],"تَذْكِرَةٌ is a ticket."],["What does إِنْ شَاءَ اللهُ mean?",["if Allah wills","praise be to Allah","in the name of Allah"],"It is said about future plans."]]],["Hajj and Umrah","الْحَجُّ وَالْعُمْرَةُ",["Key words: الْكَعْبَةُ the Kabah, الطَّوَافُ going round it, السَّعْيُ walking between Safa and Marwah, الْإِحْرَامُ the pilgrim's state.","A pilgrim is حَاجٌّ, plural حُجَّاجٌ. One performing Umrah is مُعْتَمِرٌ."],[["الْحَجُّ رُكْنٌ مِنْ أَرْكَانِ الْإِسْلَامِ","Hajj is one of the pillars of Islam"],["طَافَ الْحَاجُّ حَوْلَ الْكَعْبَةِ","The pilgrim went round the Kabah"],["سَعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ","He walked between Safa and Marwah"],["لَبَّيْكَ اللّٰهُمَّ لَبَّيْكَ","Here I am, O Allah, here I am"],["شَرِبْتُ مِنْ مَاءِ زَمْزَمَ","I drank from the water of Zamzam"]],[["What is الطَّوَافُ ?",["going round the Kabah","standing at Arafah","shaving the head"],"طَافَ is 'he went round'."],["What does حَاجٌّ mean?",["a pilgrim","a mosque","a month"],"Its plural is حُجَّاجٌ."],["The السَّعْيُ is between…",["Safa and Marwah","Makkah and Madinah","Mina and Arafah"],"سَعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ."]]],["Weather and health","الْجَوُّ وَالصِّحَّةُ",["Weather: الْجَوُّ حَارٌّ hot, بَارِدٌ cold, مُعْتَدِلٌ mild, مُمْطِرٌ rainy.","Health: مَرِيضٌ ill, صُدَاعٌ headache, دَوَاءٌ medicine, مُسْتَشْفًى hospital."],[["كَيْفَ الْجَوُّ الْيَوْمَ؟","How is the weather today?"],["الْجَوُّ حَارٌّ فِي الصَّيْفِ","The weather is hot in summer"],["يَنْزِلُ الْمَطَرُ فِي الشِّتَاءِ","Rain falls in winter"],["أَشْعُرُ بِصُدَاعٍ","I have a headache"],["ذَهَبْتُ إِلَى الطَّبِيبِ","I went to the doctor"],["شَفَاكَ اللهُ","May Allah cure you"]],[["What does الصَّيْفُ mean?",["summer","winter","rain"],"الشِّتَاءُ is winter."],["What does صُدَاعٌ mean?",["headache","medicine","hospital"],"أَشْعُرُ بِصُدَاعٍ is 'I have a headache'."],["What does شَفَاكَ اللهُ mean?",["May Allah cure you","May Allah reward you","Allah is the Greatest"],"It is said to someone who is ill."]]]];
