function today(off){var d=new Date();d.setDate(d.getDate()-(off||0));return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate();}
function streak(){var n=0,i=D.days.indexOf(today())>=0?0:1;while(D.days.indexOf(today(i))>=0){n++;i++;}return n;}
function addXP(n,msg){
  if(n<=0)return;D.xp+=n;D.hist=D.hist||{};D.hist[today()]=(D.hist[today()]||0)+n;var keep={};for(var hi=0;hi<90;hi++)keep[today(hi)]=1;for(var hk in D.hist)if(!keep[hk])delete D.hist[hk];if(D.days.indexOf(today())<0){D.days.push(today());if(D.days.length>60)D.days.shift();}
  if(D.td.d!==today())D.td={d:today(),xp:0};var was=D.td.xp;D.td.xp+=n;var lv0=level();
  save();header();trk('daily_goal_progress',{xp_added:n,xp_today:D.td.xp,goal:GOAL,goal_met:D.td.xp>=GOAL});if(was<GOAL&&D.td.xp>=GOAL){sfx('win');confetti();trk('daily_goal_reached',{xp_today:D.td.xp,goal:GOAL,streak_days:streak()});}toast('+'+n+' XP'+(msg?'  '+msg:''));
}
var LEVELS=[[0,'Beginner','مُبْتَدِئٌ'],[150,'Student','طَالِبٌ'],[400,'Striver','مُجْتَهِدٌ'],[800,'Advanced','مُتَقَدِّمٌ']];
function level(){var l=0;for(var i=0;i<LEVELS.length;i++)if(D.xp>=LEVELS[i][0])l=i;return l;}
function doneCount(){var n=0;LESSONS.forEach(function(l){if(D.done[l.id])n++;});return n;}
var BADGES=[
 ['🌱','First step','Finish your first lesson',function(){return doneCount()>=1;}],
 ['📘','Five lessons','Finish five lessons',function(){return doneCount()>=5;}],
 ['📗','25 lessons','Finish 25 lessons',function(){return doneCount()>=25;}],
 ['📙','50 lessons','Finish 50 lessons',function(){return doneCount()>=50;}],
 ['🎓','Course complete','Finish every lesson',function(){return doneCount()>=LESSONS.length;}],
 ['⭐','100 XP','Earn 100 XP',function(){return D.xp>=100;}],
 ['🌟','400 XP','Earn 400 XP',function(){return D.xp>=400;}],
 ['🏆','800 XP','Earn 800 XP',function(){return D.xp>=800;}],
 ['💯','Perfect score','Get every answer right in a mixed quiz',function(){return D.perfect>0;}],
 ['🗂️','Word collector','Score 80% or more on every word set',function(){return SETS.every(function(s){return (D.sets[s.id]||0)>=80;});}],
 ['🎈','Game explorer','Finish level 1 of every kids game',function(){return GAMES.every(function(g){return kgStars(g[0],1)>0;});}],
 ['🎮','30 game levels','Finish 30 game levels',function(){return kgDone()>=30;}],
 ['👑','All 100 levels','Finish every game level',function(){return kgDone()>=100;}],
 ['📝','25 quizzes','Pass 25 quizzes in the quiz library',function(){return qzDone()>=25;}],
 ['📚','All 100 quizzes','Pass every quiz in the library',function(){return qzDone()>=100;}],
 ['🔥','Three days','Learn three days in a row',function(){return streak()>=3;}],
 ['📅','Seven days','Learn seven days in a row',function(){return streak()>=7;}]
];

/* ---------- helpers ---------- */
var $=function(id){return document.getElementById(id);};
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
var AR=/[؀-ۿ]/;
function mix(s){ /* wrap Arabic runs inside mixed text */
  return esc(s).replace(/[؀-ۿ_][؀-ۿ\s·\/←_]*[؀-ۿ_]|[؀-ۿ]/g,function(m){return '<span class="ar" lang="ar" style="font-size:1.35em">'+m+'</span>';});
}
function shuffle(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=(Math.random()*(i+1))|0,t=a[i];a[i]=a[j];a[j]=t;}return a;}
function sample(a,n,not){return shuffle(a.filter(function(x){return x!==not;})).slice(0,n);}
var canSay=false;try{canSay='speechSynthesis' in window&&typeof SpeechSynthesisUtterance!=='undefined';}catch(e){}
/* Pronunciation voice: prefer a male Arabic voice; if the device has none, use a deeper version of its voice. */
var VKEY='lisan-voice',arVoices=[],voicePick=null,voiceChosen=false;
var MALE_V=/(maged|majed|tarik|naayf|hamed|shakir|hamdan|bassel|taim|fahed|rami|omar|jamal|abdullah|moaz|laith|hedi|saleh|ismael|\bali\b|ar-xa-x-arc|ar-xa-x-ard|\bmale\b)/i;
var FEMALE_V=/(laila|layla|mariam|amira|zariyah|hoda|salma|fatima|sana|rana|iman|noura|mouna|amany|reem|amal|hala|female|ar-xa-x-arz|ar-xa-x-are)/i;
function isMaleV(v){var n=v.name+' '+(v.voiceURI||'');return MALE_V.test(n)&&!FEMALE_V.test(v.name);}
function vScore(v){var n=v.name+' '+(v.voiceURI||''),s=0;if(isMaleV(v))s+=100;if(/natural|neural|online|enhanced|premium/i.test(n))s+=20;if(/ar[-_]SA/i.test(v.lang))s+=5;if(v.localService)s+=1;return s;}
function loadVoices(){try{arVoices=speechSynthesis.getVoices().filter(function(v){return /^ar/i.test(v.lang);});}catch(e){arVoices=[];}
  var saved='';try{saved=localStorage.getItem(VKEY)||'';}catch(e){}
  var c=arVoices.filter(function(v){return v.name===saved;})[0];voiceChosen=!!c;
  voicePick=c||arVoices.filter(isMaleV).sort(function(a,b){return vScore(b)-vScore(a);})[0]||null;}
if(canSay){loadVoices();try{speechSynthesis.addEventListener('voiceschanged',function(){loadVoices();if(typeof S!=='undefined'&&S.view==='progress'&&!S.quiz)render();});}catch(e){}}
function say(t){if(!canSay)return;try{speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(t.replace(/[←→·\/١-٩٠]/g,' '));u.lang=voicePick?voicePick.lang:'ar-SA';u.rate=.75;if(voicePick)u.voice=voicePick;if(!voiceChosen&&!(voicePick&&isMaleV(voicePick)))u.pitch=.7;speechSynthesis.speak(u);}catch(e){}}
function voicePanel(){if(!canSay)return '';var male=arVoices.filter(isMaleV),saved='';try{saved=localStorage.getItem(VKEY)||'';}catch(e){}
  var note=voicePick&&isMaleV(voicePick)?'Using a male voice: '+esc(voicePick.name)+'.':'This device has no male Arabic voice, so the app uses a deeper version of its Arabic voice. iPhone, Mac and Windows usually have a male one.';
  return '<div class="panel"><h2>🔊 Pronunciation voice</h2><p>Tap any Arabic word or sentence in the app to hear it. '+note+'</p>'+
  '<div class="btnrow" style="align-items:flex-end"><label class="vsel">Voice <select id="voiceSel"><option value="">Automatic (male when available)</option>'+arVoices.map(function(v){return '<option value="'+esc(v.name)+'"'+(v.name===saved?' selected':'')+'>'+(isMaleV(v)?'♂ ':'')+esc(v.name)+' ('+esc(v.lang)+')</option>';}).join('')+'</select></label>'+
  '<button class="btn" data-act="say" data-t="السَّلَامُ عَلَيْكُمْ، كَيْفَ حَالُكَ؟">▶ Test the voice</button></div>'+(male.length?'':'')+'</div>';}
addEventListener('change',function(e){if(e.target&&e.target.id==='voiceSel'){try{if(e.target.value)localStorage.setItem(VKEY,e.target.value);else localStorage.removeItem(VKEY);}catch(x){}loadVoices();say('السَّلَامُ عَلَيْكُمْ');render();}});
function sayBtn(t){return canSay?'<button class="say" data-act="say" data-t="'+esc(t)+'" aria-label="Listen">🔊</button>':'';}
var toastT=null;
function toast(m){var t=$('toast');t.textContent=m;t.classList.add('on');clearTimeout(toastT);toastT=setTimeout(function(){t.classList.remove('on');},1800);}
function header(){$('xp').textContent='⭐ '+D.xp+' XP';$('streak').textContent='🔥 '+streak();
  var td=D.td.d===today()?D.td.xp:0,g=$('goal');g.textContent=(td>=GOAL?'✅ ':'🎯 ')+Math.min(td,GOAL)+'/'+GOAL;g.classList.toggle('met',td>=GOAL);
  var l=level(),a=LEVELS[l][0],b=LEVELS[l+1]?LEVELS[l+1][0]:a;$('lvlName').textContent=LEVELS[l][1];
  $('lvlFill').style.width=(b>a?Math.min(100,(D.xp-a)/(b-a)*100):100)+'%';$('lvl').title=LEVELS[l+1]?(b-D.xp)+' XP to '+LEVELS[l+1][1]:'Top level reached';
  $('snd').textContent=D.snd?'🔊':'🔇';}
var GOAL=30,AC=null;
function sfx(k){if(!D.snd)return;try{AC=AC||new (window.AudioContext||window.webkitAudioContext)();var t=AC.currentTime,notes=k==='ok'?[660,880]:k==='win'?[523,659,784,1046]:[220,165];
  notes.forEach(function(f,i){var o=AC.createOscillator(),g=AC.createGain();o.type=k==='bad'?'triangle':'sine';o.frequency.value=f;g.gain.setValueAtTime(.0001,t+i*.09);g.gain.exponentialRampToValueAtTime(.18,t+i*.09+.02);g.gain.exponentialRampToValueAtTime(.0001,t+i*.09+.25);o.connect(g);g.connect(AC.destination);o.start(t+i*.09);o.stop(t+i*.09+.3);});}catch(e){}}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;var c=document.createElement('div');c.className='confetti';var cols=['#f2b01e','#1556a8','#0e9aa7','#1c8a55','#e0574a'];
  for(var i=0;i<60;i++){var s=document.createElement('i');s.style.left=Math.random()*100+'%';s.style.background=cols[i%5];s.style.animationDelay=Math.random()*.4+'s';s.style.animationDuration=1.6+Math.random()*1.2+'s';s.style.transform='rotate('+Math.random()*360+'deg)';c.appendChild(s);}
  document.body.appendChild(c);setTimeout(function(){c.remove();},3200);}
$('snd').addEventListener('click',function(){D.snd=!D.snd;save();header();if(D.snd)sfx('ok');});
addEventListener('keydown',function(e){var Q=S.quiz;if(!Q||Q.end||e.target.closest('input,textarea,select'))return;
  var n=+e.key;if(n>=1&&n<=Q.qs[Q.i].o.length&&Q.pick<0){var b=document.querySelector('[data-act=pick][data-k="'+(n-1)+'"]');if(b)b.click();}
  else if((e.key==='Enter'||e.key===' ')&&Q.pick>=0){e.preventDefault();var nb=document.querySelector('[data-act=next]');if(nb)nb.click();}});


