function lvItem(x){return '<div class="lvrow"><div class="lvar"><span class="ar" lang="ar">'+esc(x[0])+'</span>'+sayBtn(x[0])+'</div><div class="lvtl">'+esc(x[1])+'</div><div class="lven">'+esc(x[2])+'</div></div>';}
function lvQuiz(L){var all=L.w.concat(L.s);var qs=shuffle(all).slice(0,10).map(function(x){var o=[x[2]].concat(sample(all,3,x).map(function(y){return y[2];}));return makeQ({q:'What does this mean?',big:x[0],o:o,why:x[0]+' ('+x[1]+') means "'+x[2]+'".'});});
  startQuiz(L.title+' level quiz',qs,'level',L.id);}
function viewLevels(){
  D.lv=D.lv||{};
  if(S.lvl){var L=LV.filter(function(l){return l.id===S.lvl;})[0];
    return '<button class="btn back" data-act="back">← All levels</button><div class="lead"><h1>'+L.icon+' '+esc(L.title)+' <span class="ar" lang="ar" style="color:var(--primary)">'+esc(L.ar)+'</span></h1><p>'+esc(L.desc)+'</p></div>'+
    '<h2 class="lvh">Words</h2><div class="lvlist words">'+L.w.map(lvItem).join('')+'</div>'+
    '<h2 class="lvh">Sentences</h2><div class="lvlist">'+L.s.map(lvItem).join('')+'</div>'+
    '<p style="margin-top:20px"><button class="btn primary" data-act="lvQuiz" data-id="'+L.id+'" style="font-size:18px;padding:12px 22px">Take the '+esc(L.title)+' quiz</button></p>';}
  return '<div class="lead"><h1>Levels</h1><p>Pick your level: from short and easy to long and hard.</p></div><div class="grid lvgrid">'+LV.map(function(L,i){var b=D.lv[L.id]||0;
    return '<button class="card lvcard lv'+i+(b>=70?' done':'')+'" data-act="lvl" data-id="'+L.id+'"><span class="lvicon">'+L.icon+'</span><h3>'+esc(L.title)+'</h3><span class="ar" lang="ar">'+esc(L.ar)+'</span><span class="n">'+L.w.length+' WORDS · '+L.s.length+' SENTENCES</span><span style="color:var(--muted)">'+esc(L.desc)+'</span>'+(b?'<span class="tag'+(b>=70?' ok':'')+'">Best '+b+'%</span>':'<span class="tag">New</span>')+'</button>';}).join('')+'</div>';
}

