var GRAM=[{"id": "nominal", "icon": "🧱", "title": "Nominal sentences", "ar": "الْمُبْتَدَأُ وَالْخَبَرُ", "rule": ["A sentence that starts with a noun is a nominal sentence. The first noun is the subject (مُبْتَدَأٌ), and the word that tells you about it is the news (خَبَرٌ).", "The subject is usually definite (with الـ) and the news usually indefinite: الْبَيْتُ كَبِيرٌ = The house is big.", "Both are marfoo': they end in ـُ or ـٌ.", "There is no word for \"is\" or \"am\" in the present. If both words have الـ, it is a phrase, not a sentence: الْبَيْتُ الْكَبِيرُ = the big house.", "The news matches the subject in gender: الْبِنْتُ صَغِيرَةٌ."], "ex": [["الْمَسْجِدُ قَرِيبٌ", "The mosque is near."], ["الْمَاءُ بَارِدٌ", "The water is cold."], ["أَنَا طَالِبٌ", "I am a student."], ["اللهُ رَحِيمٌ", "Allah is merciful."], ["السَّيَّارَةُ جَدِيدَةٌ", "The car is new."]], "d": [["c", "Which one is a full sentence: \"The house is big\"?", ["الْبَيْتُ كَبِيرٌ", "الْبَيْتُ الْكَبِيرُ", "بَيْتٌ الْكَبِيرُ"], "The subject is definite (الْبَيْتُ) and the news is indefinite (كَبِيرٌ). الْبَيْتُ الْكَبِيرُ means \"the big house\"."], ["c", "Which means \"the new pen\" (a phrase, not a sentence)?", ["الْقَلَمُ الْجَدِيدُ", "الْقَلَمُ جَدِيدٌ", "قَلَمٌ الْجَدِيدُ"], "When both words have الـ, the second describes the first."], ["c", "Complete: الْكِتَابُ ___ (useful)", ["مُفِيدٌ", "مُفِيدًا", "مُفِيدٍ"], "The news of a nominal sentence is marfoo': مُفِيدٌ."], ["f", "الْمَاءَ بَارِدٌ", ["الْمَاءُ بَارِدٌ", "الْمَاءِ بَارِدٌ", "مَاءً بَارِدٌ"], "The subject is marfoo': الْمَاءُ with dammah."], ["f", "الْبِنْتُ صَغِيرٌ", ["الْبِنْتُ صَغِيرَةٌ", "الْبِنْتُ صَغِيرًا", "الْبِنْتَ صَغِيرٌ"], "الْبِنْتُ is feminine, so the news is صَغِيرَةٌ."], ["c", "How do you say \"I am a teacher\" (a man)?", ["أَنَا مُدَرِّسٌ", "أَنَا مُدَرِّسٍ", "أَنَا مُدَرِّسًا"], "No word for \"am\" is needed: أَنَا مُدَرِّسٌ."], ["o", "الْمَسْجِدُ قَرِيبٌ مِنَ الْبَيْتِ", "The mosque is near the house."], ["o", "الطَّالِبُ مُجْتَهِدٌ", "The student is hard-working."], ["c", "In الْجَوُّ حَارٌّ, which word is the news?", ["حَارٌّ", "الْجَوُّ", "There is no news"], "الْجَوُّ is the subject; حَارٌّ tells us about it."], ["f", "السَّيَّارَةُ جَدِيدٌ", ["السَّيَّارَةُ جَدِيدَةٌ", "السَّيَّارَةَ جَدِيدَةٌ", "سَيَّارَةُ جَدِيدَةٌ"], "السَّيَّارَةُ is feminine, so the news takes ة."]]}, {"id": "demo", "icon": "👉", "title": "This and that", "ar": "أَسْمَاءُ الْإِشَارَةِ", "rule": ["هٰذَا = this (masculine), هٰذِهِ = this (feminine).", "ذٰلِكَ = that (masculine), تِلْكَ = that (feminine).", "هٰؤُلَاءِ = these (people), أُولٰئِكَ = those (people).", "هٰذَا كِتَابٌ is a sentence: \"This is a book\". هٰذَا الْكِتَابُ is a phrase: \"this book\"."], "ex": [["هٰذَا قَلَمٌ", "This is a pen."], ["تِلْكَ نَافِذَةٌ", "That is a window."], ["هٰذَا الْبَيْتُ كَبِيرٌ", "This house is big."], ["هٰؤُلَاءِ طُلَّابٌ", "These are students."]], "d": [["c", "___ سَاعَةٌ (This is a watch)", ["هٰذِهِ", "هٰذَا", "ذٰلِكَ"], "سَاعَةٌ is feminine and near, so هٰذِهِ."], ["c", "___ جَبَلٌ (That is a mountain)", ["ذٰلِكَ", "تِلْكَ", "هٰذِهِ"], "جَبَلٌ is masculine and far, so ذٰلِكَ."], ["c", "___ شَجَرَةٌ (That is a tree)", ["تِلْكَ", "ذٰلِكَ", "هٰذَا"], "شَجَرَةٌ is feminine and far, so تِلْكَ."], ["c", "Which means \"This book is new\"?", ["هٰذَا الْكِتَابُ جَدِيدٌ", "هٰذَا كِتَابٌ جَدِيدٌ", "هٰذَا الْكِتَابُ الْجَدِيدُ"], "هٰذَا الْكِتَابُ = this book, and جَدِيدٌ is the news. هٰذَا كِتَابٌ جَدِيدٌ means \"This is a new book\"."], ["f", "هٰذَا مَدْرَسَةٌ", ["هٰذِهِ مَدْرَسَةٌ", "ذٰلِكَ مَدْرَسَةٌ", "هٰذَا مَدْرَسَةً"], "مَدْرَسَةٌ ends in ة, so it is feminine: هٰذِهِ."], ["f", "تِلْكَ مَسْجِدٌ", ["ذٰلِكَ مَسْجِدٌ", "هٰذِهِ مَسْجِدٌ", "تِلْكَ مَسْجِدًا"], "مَسْجِدٌ is masculine; far masculine is ذٰلِكَ."], ["c", "How do you say \"These are teachers\"?", ["هٰؤُلَاءِ مُدَرِّسُونَ", "هٰذَا مُدَرِّسُونَ", "هٰذِهِ مُدَرِّسُونَ"], "هٰؤُلَاءِ points to a group of people."], ["c", "How do you say \"Those are Muslims\"?", ["أُولٰئِكَ مُسْلِمُونَ", "ذٰلِكَ مُسْلِمُونَ", "تِلْكَ مُسْلِمُونَ"], "أُولٰئِكَ points to a group of people far away."], ["o", "هٰذِهِ السَّيَّارَةُ جَمِيلَةٌ", "This car is beautiful."], ["o", "ذٰلِكَ الرَّجُلُ طَبِيبٌ", "That man is a doctor."]]}, {"id": "al", "icon": "☀️", "title": "The word \"the\" and sun letters", "ar": "أَلْ وَالْحُرُوفُ الشَّمْسِيَّةُ", "rule": ["الـ makes a noun definite (\"the\"). A noun with الـ never has tanween: كِتَابٌ ← الْكِتَابُ.", "With the 14 sun letters (ت ث د ذ ر ز س ش ص ض ط ظ ل ن) the ل is silent and the next letter is doubled: الشَّمْسُ = ash-shams.", "With the 14 moon letters the ل is pronounced: الْقَمَرُ = al-qamar."], "ex": [["الشَّمْسُ", "ash-shamsu: the sun"], ["الْقَمَرُ", "al-qamaru: the moon"], ["النُّورُ", "an-nooru: the light"], ["الْبَابُ", "al-baabu: the door"]], "d": [["c", "Add الـ to كِتَابٌ:", ["الْكِتَابُ", "الْكِتَابٌ", "الْكِتَابٍ"], "A word with الـ never takes tanween: الْكِتَابُ."], ["c", "Which word starts with a sun letter?", ["السَّمَكُ", "الْبَحْرُ", "الْقَلَمُ"], "س is a sun letter, so the ل is silent: as-samaku."], ["c", "Which word starts with a moon letter?", ["الْكُرْسِيُّ", "الدَّرْسُ", "الشَّارِعُ"], "ك is a moon letter: al-kursiyyu."], ["c", "How is النَّجْمُ read?", ["an-najmu", "al-najmu", "an-najmun"], "ن is a sun letter, so the ل is not said."], ["c", "How is الرَّجُلُ read?", ["ar-rajulu", "al-rajulu", "ar-rajulun"], "ر is a sun letter, and there is no tanween with الـ."], ["f", "الْبَيْتٌ", ["الْبَيْتُ", "بَيْتُ", "الْبَيْتٍ"], "الـ and tanween never come together: الْبَيْتُ."], ["c", "How is الْوَلَدُ read?", ["al-waladu", "aw-waladu", "al-waladun"], "و is a moon letter, so the ل is pronounced."], ["c", "Which spelling of \"the sun\" is right?", ["الشَّمْسُ", "الْشَمْسُ", "شَمْسُ"], "ش is a sun letter: the ل has no sukoon and ش gets a shaddah."], ["c", "Which one means \"the teacher\"?", ["الْمُدَرِّسُ", "مُدَرِّسٌ", "مُدَرِّسًا"], "الـ = \"the\"."], ["c", "How many sun letters are there?", ["14", "28", "7"], "Half of the 28 letters are sun letters."]]}, {"id": "jarr", "icon": "📍", "title": "Prepositions", "ar": "حُرُوفُ الْجَرِّ", "rule": ["After a preposition (فِي، مِنْ، إِلَى، عَلَى، عَنْ، بِـ، لِـ، كَـ) the noun is majroor: it ends in ـِ or ـٍ.", "فِي الْبَيْتِ = in the house. فِي بَيْتٍ = in a house.", "Before الـ, مِنْ becomes مِنَ: مِنَ الْمَسْجِدِ.", "لِـ + اللهِ is written لِلَّهِ."], "ex": [["الْكِتَابُ عَلَى الْمَكْتَبِ", "The book is on the desk."], ["ذَهَبْتُ إِلَى الْمَدْرَسَةِ", "I went to school."], ["خَرَجَ مِنَ الْمَسْجِدِ", "He came out of the mosque."], ["كَتَبْتُ بِالْقَلَمِ", "I wrote with the pen."]], "d": [["c", "Complete: الْقَلَمُ فِي ___ (the bag)", ["الْحَقِيبَةِ", "الْحَقِيبَةُ", "الْحَقِيبَةَ"], "After فِي the noun takes kasrah."], ["c", "Complete: جَلَسْتُ عَلَى ___ (a chair)", ["كُرْسِيٍّ", "كُرْسِيٌّ", "كُرْسِيًّا"], "Without الـ, the majroor ending is kasratain."], ["f", "ذَهَبَ إِلَى الْمَسْجِدُ", ["ذَهَبَ إِلَى الْمَسْجِدِ", "ذَهَبَ إِلَى الْمَسْجِدَ", "ذَهَبَ إِلَى مَسْجِدُ"], "إِلَى makes the noun majroor."], ["f", "خَرَجْتُ مِنْ الْبَيْتِ", ["خَرَجْتُ مِنَ الْبَيْتِ", "خَرَجْتُ مِنِ الْبَيْتُ", "خَرَجْتُ مِنْ الْبَيْتُ"], "Before الـ, مِنْ becomes مِنَ."], ["c", "What does عَنْ mean?", ["about, away from", "on", "with"], "تَكَلَّمَ عَنِ الدَّرْسِ = He talked about the lesson."], ["c", "Which means \"with the pen\"?", ["بِالْقَلَمِ", "بِالْقَلَمُ", "بِالْقَلَمَ"], "بِـ joins the word and makes it majroor."], ["c", "Which means \"for Allah\"?", ["لِلَّهِ", "لِاللهِ", "لِلَّهُ"], "لِـ + اللهِ is written لِلَّهِ, as in الْحَمْدُ لِلَّهِ."], ["o", "الْكِتَابُ عَلَى الْمَكْتَبِ", "The book is on the desk."], ["o", "ذَهَبْتُ إِلَى السُّوقِ", "I went to the market."], ["c", "After a preposition, the noun is…", ["majroor (kasrah)", "marfoo' (dammah)", "mansoob (fathah)"], "Prepositions are حُرُوفُ الْجَرِّ: they make the noun majroor."]]}, {"id": "idafa", "icon": "🔗", "title": "Possession: the idaafah", "ar": "الْإِضَافَةُ", "rule": ["Two nouns side by side show belonging: كِتَابُ الطَّالِبِ = the student's book.", "The first word has no الـ and no tanween.", "The second word is always majroor.", "A ة on the first word is said as t: سَيَّارَةُ الْمُدِيرِ = sayyaaratul-mudeer."], "ex": [["بَيْتُ اللهِ", "the House of Allah"], ["بَابُ الْفَصْلِ", "the classroom door"], ["اِسْمُ الْمُدَرِّسِ", "the teacher's name"], ["مِفْتَاحُ السَّيَّارَةِ", "the car key"]], "d": [["c", "How do you say \"the teacher's book\"?", ["كِتَابُ الْمُدَرِّسِ", "الْكِتَابُ الْمُدَرِّسِ", "كِتَابٌ الْمُدَرِّسُ"], "First word: no الـ, no tanween. Second word: majroor."], ["f", "الْبَابُ الْبَيْتِ مَفْتُوحٌ", ["بَابُ الْبَيْتِ مَفْتُوحٌ", "بَابٌ الْبَيْتِ مَفْتُوحٌ", "الْبَابُ الْبَيْتُ مَفْتُوحٌ"], "The first word of an idaafah never takes الـ."], ["f", "قَلَمٌ زَيْدٍ", ["قَلَمُ زَيْدٍ", "قَلَمٌ زَيْدٌ", "الْقَلَمُ زَيْدٍ"], "The first word loses its tanween."], ["c", "Complete: مِفْتَاحُ ___ (the car)", ["السَّيَّارَةِ", "السَّيَّارَةُ", "السَّيَّارَةَ"], "The second word of an idaafah is majroor."], ["c", "What does بِنْتُ الْإِمَامِ mean?", ["the imam's daughter", "The daughter is an imam.", "a daughter and an imam"], "The first noun belongs to the second."], ["c", "Which one is an idaafah?", ["بَيْتُ الْمُدِيرِ", "الْبَيْتُ كَبِيرٌ", "بَيْتٌ كَبِيرٌ"], "بَيْتُ الْمُدِيرِ = the manager's house."], ["c", "How is the ة read in غُرْفَةُ الطَّالِبِ?", ["as t: ghurfatut-taalib", "silent: ghurfa at-taalib", "as h: ghurfah at-taalib"], "The ة of the first word is joined and said as t."], ["o", "اِسْمُ الْمُدَرِّسِ مُحَمَّدٌ", "The teacher's name is Muhammad."], ["o", "بَيْتُ الْمُدِيرِ بَعِيدٌ", "The manager's house is far."], ["c", "How do you say \"the door of a house\"?", ["بَابُ بَيْتٍ", "بَابٌ بَيْتٍ", "الْبَابُ بَيْتٌ"], "If the second word is indefinite, it takes kasratain."]]}, {"id": "sifa", "icon": "🎨", "title": "Describing words", "ar": "النَّعْتُ", "rule": ["A describing word comes after its noun.", "It matches the noun in four things: gender, number, \"the\" or not, and ending.", "بَيْتٌ كَبِيرٌ = a big house. الْبَيْتُ الْكَبِيرُ = the big house. فِي بَيْتٍ كَبِيرٍ = in a big house.", "Plurals of things take a feminine singular describing word: كُتُبٌ جَدِيدَةٌ."], "ex": [["سَيَّارَةٌ جَدِيدَةٌ", "a new car"], ["الْمَسْجِدُ الْقَدِيمُ", "the old mosque"], ["طُلَّابٌ مُجْتَهِدُونَ", "hard-working students"], ["رَأَيْتُ حَدِيقَةً جَمِيلَةً", "I saw a beautiful garden."]], "d": [["c", "\"a new car\":", ["سَيَّارَةٌ جَدِيدَةٌ", "سَيَّارَةٌ جَدِيدٌ", "سَيَّارَةٌ الْجَدِيدَةُ"], "The car is feminine and indefinite, so the describing word is too."], ["c", "\"the old mosque\":", ["الْمَسْجِدُ الْقَدِيمُ", "الْمَسْجِدُ قَدِيمٌ", "مَسْجِدٌ الْقَدِيمُ"], "Both words need الـ. الْمَسْجِدُ قَدِيمٌ is a sentence: \"The mosque is old\"."], ["f", "فِي بَيْتٍ كَبِيرٌ", ["فِي بَيْتٍ كَبِيرٍ", "فِي بَيْتٌ كَبِيرٌ", "فِي الْبَيْتِ كَبِيرٍ"], "The describing word copies the noun's ending: كَبِيرٍ."], ["f", "بِنْتٌ صَغِيرٌ", ["بِنْتٌ صَغِيرَةٌ", "بِنْتٌ الصَّغِيرَةُ", "بِنْتًا صَغِيرٌ"], "بِنْتٌ is feminine, so صَغِيرَةٌ."], ["c", "\"new books\" (things, plural):", ["كُتُبٌ جَدِيدَةٌ", "كُتُبٌ جَدِيدُونَ", "كُتُبٌ جَدِيدٌ"], "Plurals of things take a feminine singular describing word."], ["c", "\"hard-working students\" (men):", ["طُلَّابٌ مُجْتَهِدُونَ", "طُلَّابٌ مُجْتَهِدَةٌ", "طُلَّابٌ مُجْتَهِدٌ"], "Plurals of people take a plural describing word."], ["c", "\"I saw a beautiful garden\":", ["رَأَيْتُ حَدِيقَةً جَمِيلَةً", "رَأَيْتُ حَدِيقَةً جَمِيلَةٌ", "رَأَيْتُ حَدِيقَةٌ جَمِيلَةٌ"], "The object is mansoob, and its describing word matches it."], ["o", "هٰذَا قَلَمٌ جَدِيدٌ", "This is a new pen."], ["o", "الْمَدْرَسَةُ الْكَبِيرَةُ قَرِيبَةٌ", "The big school is near."], ["c", "A describing word matches its noun in…", ["gender, number, \"the\" and ending", "gender only", "ending only"], "All four must match."]]}, {"id": "pron", "icon": "🙋", "title": "Pronouns: I, you, he, she", "ar": "الضَّمَائِرُ الْمُنْفَصِلَةُ", "rule": ["أَنَا = I, نَحْنُ = we.", "أَنْتَ = you (man), أَنْتِ = you (woman), أَنْتُمَا = you two, أَنْتُمْ = you all.", "هُوَ = he, هِيَ = she, هُمَا = they two.", "هُمْ = they (men or mixed), هُنَّ = they (women)."], "ex": [["أَنَا مُسْلِمٌ", "I am a Muslim."], ["هِيَ مُدَرِّسَةٌ", "She is a teacher."], ["نَحْنُ طُلَّابٌ", "We are students."], ["هُمْ فِي الْمَسْجِدِ", "They are in the mosque."]], "d": [["c", "Which word means \"she\"?", ["هِيَ", "هُوَ", "هُمْ"], "هِيَ = she, هُوَ = he."], ["c", "Which word means \"we\"?", ["نَحْنُ", "أَنْتُمْ", "هُمْ"], "نَحْنُ = we."], ["c", "Speaking to a woman: \"You are a student.\"", ["أَنْتِ طَالِبَةٌ", "أَنْتَ طَالِبَةٌ", "أَنْتَ طَالِبٌ"], "أَنْتِ with kasrah is for a woman."], ["f", "هُوَ طَبِيبَةٌ", ["هِيَ طَبِيبَةٌ", "هُمْ طَبِيبَةٌ", "هُنَّ طَبِيبَةٌ"], "طَبِيبَةٌ is a woman doctor, so the pronoun is هِيَ."], ["c", "\"They are teachers\" (men):", ["هُمْ مُدَرِّسُونَ", "هُنَّ مُدَرِّسُونَ", "هُوَ مُدَرِّسُونَ"], "هُمْ is for a group of men or a mixed group."], ["c", "\"They are teachers\" (women):", ["هُنَّ مُدَرِّسَاتٌ", "هُمْ مُدَرِّسَاتٌ", "هِيَ مُدَرِّسَاتٌ"], "هُنَّ is for a group of women."], ["c", "\"You (all) are Muslims\":", ["أَنْتُمْ مُسْلِمُونَ", "أَنْتَ مُسْلِمُونَ", "أَنْتِ مُسْلِمُونَ"], "أَنْتُمْ is \"you\" for a group."], ["o", "نَحْنُ طُلَّابٌ فِي الْجَامِعَةِ", "We are students at the university."], ["o", "هِيَ مُدَرِّسَةٌ جَدِيدَةٌ", "She is a new teacher."], ["c", "Which pronoun means \"you two\"?", ["أَنْتُمَا", "أَنْتُمْ", "أَنْتِ"], "أَنْتُمَا is the dual \"you\"."]]}, {"id": "attached", "icon": "🧩", "title": "My, your, his: attached pronouns", "ar": "الضَّمَائِرُ الْمُتَّصِلَةُ", "rule": ["ـِي my, ـُكَ your (man), ـُكِ your (woman), ـُهُ his, ـُهَا her, ـُنَا our, ـُكُمْ your (all), ـُهُمْ their.", "A noun with an attached pronoun is already definite: no الـ and no tanween.", "ة becomes ت before a pronoun: سَيَّارَةٌ ← سَيَّارَتِي.", "On a verb, \"me\" is ـنِي: عَلَّمَنِي = he taught me."], "ex": [["كِتَابِي", "my book"], ["بَيْتُهُ", "his house"], ["سَيَّارَتُهَا", "her car"], ["مُدَرِّسُنَا", "our teacher"]], "d": [["c", "\"my book\":", ["كِتَابِي", "الْكِتَابِي", "كِتَابٌي"], "Add ـِي and drop the tanween."], ["c", "\"her pen\":", ["قَلَمُهَا", "قَلَمُهُ", "قَلَمُكِ"], "ـهَا = her."], ["c", "\"our house\":", ["بَيْتُنَا", "بَيْتُهُمْ", "بَيْتِي"], "ـنَا = our."], ["c", "\"my car\":", ["سَيَّارَتِي", "سَيَّارَةِي", "السَّيَّارَتِي"], "ة turns into ت before a pronoun."], ["f", "الْقَلَمُهُ جَدِيدٌ", ["قَلَمُهُ جَدِيدٌ", "قَلَمٌهُ جَدِيدٌ", "قَلَمُهُ جَدِيدًا"], "A noun with a pronoun never takes الـ."], ["c", "To a woman: \"What is your name?\"", ["مَا اسْمُكِ؟", "مَا اسْمُكَ؟", "مَا اسْمُهَا؟"], "ـكِ with kasrah is \"your\" for a woman."], ["c", "\"their teacher\" (men):", ["مُدَرِّسُهُمْ", "مُدَرِّسُهُنَّ", "مُدَرِّسُكُمْ"], "ـهُمْ = their (men)."], ["c", "How do you say \"he taught me\"?", ["عَلَّمَنِي", "عَلَّمِي", "عَلَّمَتْنِي"], "On a verb, \"me\" is ـنِي. عَلَّمَتْنِي means \"she taught me\"."], ["o", "بَيْتُهُ قَرِيبٌ مِنَ الْمَسْجِدِ", "His house is near the mosque."], ["o", "أَيْنَ حَقِيبَتُكَ؟", "Where is your bag?"]]}, {"id": "past", "icon": "⏪", "title": "The past tense", "ar": "الْفِعْلُ الْمَاضِي", "rule": ["The basic form means \"he did\": كَتَبَ = he wrote.", "Endings: كَتَبْتُ I, كَتَبْتَ you (man), كَتَبْتِ you (woman), كَتَبَتْ she.", "كَتَبْنَا we, كَتَبْتُمْ you all, كَتَبُوا they (men), كَتَبْنَ they (women).", "The alif at the end of ـُوا is written but not said."], "ex": [["ذَهَبْتُ إِلَى السُّوقِ", "I went to the market."], ["كَتَبَتِ الدَّرْسَ", "She wrote the lesson."], ["جَلَسْنَا فِي الْفَصْلِ", "We sat in the classroom."], ["خَرَجُوا مِنَ الْمَسْجِدِ", "They came out of the mosque."]], "d": [["c", "\"I wrote\":", ["كَتَبْتُ", "كَتَبَتْ", "كَتَبْتَ"], "ـتُ (with dammah) is \"I\"."], ["c", "\"She went\":", ["ذَهَبَتْ", "ذَهَبْتُ", "ذَهَبْتِ"], "ـَتْ (with sukoon) is \"she\"."], ["c", "\"We sat\":", ["جَلَسْنَا", "جَلَسُوا", "جَلَسْتُمْ"], "ـنَا is \"we\"."], ["c", "\"They (men) went out\":", ["خَرَجُوا", "خَرَجْنَ", "خَرَجْنَا"], "ـُوا is \"they\" (men)."], ["c", "To a woman: \"Did you understand?\"", ["هَلْ فَهِمْتِ؟", "هَلْ فَهِمْتَ؟", "هَلْ فَهِمَتْ؟"], "ـتِ is \"you\" (woman)."], ["f", "أَنَا ذَهَبَتْ إِلَى السُّوقِ", ["أَنَا ذَهَبْتُ إِلَى السُّوقِ", "أَنَا ذَهَبْنَا إِلَى السُّوقِ", "أَنَا ذَهَبُوا إِلَى السُّوقِ"], "With أَنَا use ـتُ: ذَهَبْتُ."], ["f", "الطُّلَّابُ دَخَلَ الْفَصْلَ", ["الطُّلَّابُ دَخَلُوا الْفَصْلَ", "الطُّلَّابُ دَخَلْنَا الْفَصْلَ", "الطُّلَّابُ دَخَلْتُ الْفَصْلَ"], "When a plural subject (men) comes first, the verb takes ـُوا."], ["c", "\"You (all) opened the door\":", ["فَتَحْتُمُ الْبَابَ", "فَتَحُوا الْبَابَ", "فَتَحْنَا الْبَابَ"], "ـتُمْ is \"you all\". Before الـ its sukoon becomes dammah."], ["o", "ذَهَبْتُ إِلَى الْمَسْجِدِ أَمْسِ", "I went to the mosque yesterday."], ["o", "شَرِبَتِ الْبِنْتُ الْحَلِيبَ", "The girl drank the milk."]]}, {"id": "present", "icon": "▶️", "title": "The present tense", "ar": "الْفِعْلُ الْمُضَارِعُ", "rule": ["The present tense starts with one of four letters: أَ I, نَ we, تَ you or she, يَ he or they.", "يَكْتُبُ he writes, تَكْتُبُ she writes or you write, أَكْتُبُ I write, نَكْتُبُ we write.", "يَكْتُبُونَ they (men), تَكْتُبُونَ you all, تَكْتُبِينَ you (woman).", "Put سَـ or سَوْفَ in front for the future: سَأَكْتُبُ = I will write."], "ex": [["أَنَا أَقْرَأُ الْقُرْآنَ", "I read the Quran."], ["هِيَ تَطْبُخُ الطَّعَامَ", "She cooks the food."], ["نَحْنُ نَدْرُسُ الْعَرَبِيَّةَ", "We study Arabic."], ["هُمْ يَلْعَبُونَ", "They are playing."]], "d": [["c", "\"I read\":", ["أَقْرَأُ", "يَقْرَأُ", "نَقْرَأُ"], "أَ at the start means \"I\"."], ["c", "\"We learn\":", ["نَتَعَلَّمُ", "يَتَعَلَّمُ", "تَتَعَلَّمُ"], "نَ at the start means \"we\"."], ["c", "\"She writes\":", ["تَكْتُبُ", "يَكْتُبُ", "أَكْتُبُ"], "تَ is used for \"she\" (and \"you\")."], ["c", "\"They (men) play\":", ["يَلْعَبُونَ", "يَلْعَبُ", "تَلْعَبُونَ"], "يَـ … ـُونَ = they (men)."], ["c", "To a woman: \"Where do you live?\"", ["أَيْنَ تَسْكُنِينَ؟", "أَيْنَ تَسْكُنُ؟", "أَيْنَ يَسْكُنُ؟"], "تَـ … ـِينَ = you (woman)."], ["f", "نَحْنُ يَذْهَبُ إِلَى الْمَدْرَسَةِ", ["نَحْنُ نَذْهَبُ إِلَى الْمَدْرَسَةِ", "نَحْنُ تَذْهَبُ إِلَى الْمَدْرَسَةِ", "نَحْنُ أَذْهَبُ إِلَى الْمَدْرَسَةِ"], "With نَحْنُ the verb starts with نَـ."], ["f", "هِيَ يَطْبُخُ الطَّعَامَ", ["هِيَ تَطْبُخُ الطَّعَامَ", "هِيَ أَطْبُخُ الطَّعَامَ", "هِيَ نَطْبُخُ الطَّعَامَ"], "With هِيَ the verb starts with تَـ."], ["c", "What does سَـ add in سَأَذْهَبُ?", ["the future: I will go", "the past: I went", "\"not\": I do not go"], "سَـ or سَوْفَ before the present makes it future."], ["o", "أَنَا أَدْرُسُ اللُّغَةَ الْعَرَبِيَّةَ", "I study the Arabic language."], ["o", "هُمْ يُصَلُّونَ فِي الْمَسْجِدِ", "They pray in the mosque."]]}, {"id": "amr", "icon": "📣", "title": "Commands and \"don't\"", "ar": "الْأَمْرُ وَالنَّهْيُ", "rule": ["To give a command, take the present (تَكْتُبُ), drop تَـ and end with sukoon. If it then starts with sukoon, add a hamza: اُكْتُبْ.", "Use اُ when the middle vowel is dammah (تَكْتُبُ ← اُكْتُبْ), otherwise اِ (تَجْلِسُ ← اِجْلِسْ، تَفْتَحُ ← اِفْتَحْ).", "To a woman add ـِي: اُكْتُبِي. To a group add ـُوا: اُكْتُبُوا.", "\"Don't\" = لَا + present with sukoon: لَا تَكْتُبْ، لَا تَجْلِسِي، لَا تَتَكَلَّمُوا."], "ex": [["اُكْتُبْ اسْمَكَ", "Write your name."], ["اِجْلِسِي هُنَا", "Sit here (to a woman)."], ["اِسْمَعُوا جَيِّدًا", "Listen well (to a group)."], ["لَا تَتَأَخَّرْ", "Don't be late."]], "d": [["c", "\"Write!\" (to a man):", ["اُكْتُبْ", "كَتَبَ", "يَكْتُبُ"], "From تَكْتُبُ: drop تَـ, start with اُ, end with sukoon."], ["c", "\"Sit!\" (to a woman):", ["اِجْلِسِي", "اِجْلِسْ", "اِجْلِسُوا"], "ـِي at the end is for a woman."], ["c", "\"Open the door!\" (to a group):", ["اِفْتَحُوا الْبَابَ", "اِفْتَحِ الْبَابَ", "اِفْتَحِي الْبَابَ"], "ـُوا at the end is for a group."], ["c", "\"Don't be late!\" (to a man):", ["لَا تَتَأَخَّرْ", "لَا تَتَأَخَّرُ", "لَمْ تَتَأَخَّرْ"], "لَا + present with sukoon. لَا تَتَأَخَّرُ is a statement: \"you are not late\"."], ["f", "لَا تَكْتُبُ عَلَى الْكِتَابِ", ["لَا تَكْتُبْ عَلَى الْكِتَابِ", "لَا كَتَبَ عَلَى الْكِتَابِ", "لَا اُكْتُبْ عَلَى الْكِتَابِ"], "In \"don't\", the verb ends in sukoon."], ["f", "اُكْتُبْ يَا فَاطِمَةُ", ["اُكْتُبِي يَا فَاطِمَةُ", "اُكْتُبُوا يَا فَاطِمَةُ", "تَكْتُبْ يَا فَاطِمَةُ"], "Speaking to a woman: اُكْتُبِي."], ["c", "\"Listen!\" (to a group):", ["اِسْمَعُوا", "اِسْمَعْ", "اِسْمَعِي"], "A group command ends in ـُوا."], ["c", "\"Go!\" (to a man), from تَذْهَبُ:", ["اِذْهَبْ", "اُذْهُبْ", "ذَهَبَ"], "The middle vowel is fathah (تَذْهَبُ), so start with اِ."], ["o", "اِقْرَأْ هٰذَا الْكِتَابَ", "Read this book."], ["o", "لَا تَتَكَلَّمُوا فِي الصَّلَاةِ", "Do not talk (all of you) during the prayer."]]}, {"id": "neg", "icon": "🚫", "title": "Saying \"not\"", "ar": "النَّفْيُ", "rule": ["مَا + past = did not: مَا ذَهَبْتُ.", "لَمْ + present with sukoon = did not: لَمْ أَذْهَبْ.", "لَا + present = do not (now or in general): لَا أَعْرِفُ.", "لَنْ + present with fathah = will not: لَنْ أَذْهَبَ.", "لَيْسَ = is not. Its news becomes mansoob: لَيْسَ الْبَيْتُ كَبِيرًا. For she: لَيْسَتْ."], "ex": [["لَمْ أَفْهَمِ الدَّرْسَ", "I did not understand the lesson."], ["لَا أَعْرِفُ", "I don't know."], ["لَنْ نَنْسَى", "We will not forget."], ["لَيْسَ الْجَوُّ بَارِدًا", "The weather is not cold."]], "d": [["c", "\"I did not go\" (with لَمْ):", ["لَمْ أَذْهَبْ", "لَمْ ذَهَبْتُ", "لَمْ أَذْهَبُ"], "لَمْ + present verb with sukoon."], ["c", "\"I will not go\":", ["لَنْ أَذْهَبَ", "لَا ذَهَبْتُ", "لَمْ أَذْهَبْ"], "لَنْ + present verb with fathah = will not."], ["c", "\"I don't know\":", ["لَا أَعْرِفُ", "لَمْ أَعْرِفُ", "لَنْ أَعْرِفْ"], "لَا + present = do not."], ["c", "\"The house is not big\":", ["لَيْسَ الْبَيْتُ كَبِيرًا", "لَيْسَ الْبَيْتُ كَبِيرٌ", "لَا الْبَيْتُ كَبِيرٌ"], "After لَيْسَ the news becomes mansoob."], ["f", "لَمْ يَذْهَبُ إِلَى الْمَدْرَسَةِ", ["لَمْ يَذْهَبْ إِلَى الْمَدْرَسَةِ", "لَمْ ذَهَبَ إِلَى الْمَدْرَسَةِ", "لَمْ يَذْهَبَ إِلَى الْمَدْرَسَةِ"], "لَمْ puts sukoon on the last letter."], ["f", "لَيْسَ الطَّالِبُ مُجْتَهِدٌ", ["لَيْسَ الطَّالِبُ مُجْتَهِدًا", "لَيْسَ الطَّالِبَ مُجْتَهِدٌ", "لَيْسَ الطَّالِبِ مُجْتَهِدًا"], "The news of لَيْسَ is mansoob."], ["c", "\"She is not a teacher\":", ["لَيْسَتْ مُدَرِّسَةً", "لَيْسَ مُدَرِّسَةً", "لَيْسَتْ مُدَرِّسَةٌ"], "لَيْسَ becomes لَيْسَتْ for a feminine subject, and the news is mansoob."], ["c", "\"I did not eat\" (with مَا):", ["مَا أَكَلْتُ", "مَا آكُلُ", "مَا أَكَلَتْ"], "مَا + past verb. مَا آكُلُ means \"I don't eat\"."], ["o", "لَمْ أَفْهَمِ الدَّرْسَ", "I did not understand the lesson."], ["o", "لَنْ نَنْسَى هٰذَا الْيَوْمَ", "We will not forget this day."]]}, {"id": "inna", "icon": "✨", "title": "Inna and its sisters", "ar": "إِنَّ وَأَخَوَاتُهَا", "rule": ["These words come before a nominal sentence: إِنَّ indeed, أَنَّ that, لٰكِنَّ but, كَأَنَّ as if, لَعَلَّ perhaps, لَيْتَ if only.", "They make the subject mansoob (fathah). The news stays marfoo'.", "إِنَّ اللهَ غَفُورٌ = Indeed, Allah is Forgiving.", "With a pronoun they take the attached form: إِنَّكَ، إِنَّهُ، إِنَّنَا."], "ex": [["إِنَّ اللهَ مَعَ الصَّابِرِينَ", "Indeed, Allah is with the patient."], ["أَعْرِفُ أَنَّ الدَّرْسَ سَهْلٌ", "I know that the lesson is easy."], ["لَعَلَّ الْمُدَرِّسَ قَادِمٌ", "Perhaps the teacher is coming."], ["لَيْتَ الشَّبَابَ يَعُودُ", "If only youth would return."]], "d": [["c", "Complete: إِنَّ ___ رَحِيمٌ (Allah)", ["اللهَ", "اللهُ", "اللهِ"], "After إِنَّ the subject is mansoob."], ["f", "إِنَّ الصَّلَاةُ مُهِمَّةٌ", ["إِنَّ الصَّلَاةَ مُهِمَّةٌ", "إِنَّ الصَّلَاةَ مُهِمَّةً", "إِنَّ الصَّلَاةِ مُهِمَّةٌ"], "إِنَّ makes the subject mansoob and leaves the news marfoo'."], ["f", "لَعَلَّ الْمُدَرِّسَ قَادِمًا", ["لَعَلَّ الْمُدَرِّسَ قَادِمٌ", "لَعَلَّ الْمُدَرِّسُ قَادِمٌ", "لَعَلَّ الْمُدَرِّسِ قَادِمًا"], "The news after لَعَلَّ stays marfoo'."], ["c", "What does لَيْتَ mean?", ["if only (a wish)", "because", "perhaps"], "لَيْتَ expresses a wish."], ["c", "What does كَأَنَّ mean?", ["as if", "indeed", "but"], "كَأَنَّ = as if, as though."], ["c", "Complete: الْجَوُّ حَارٌّ لٰكِنَّ ___ بَارِدٌ (the water)", ["الْمَاءَ", "الْمَاءُ", "الْمَاءِ"], "لٰكِنَّ is a sister of إِنَّ, so its subject is mansoob."], ["c", "\"Indeed, you (man) are a good student\":", ["إِنَّكَ طَالِبٌ جَيِّدٌ", "إِنَّ أَنْتَ طَالِبٌ جَيِّدٌ", "إِنَّكَ طَالِبًا جَيِّدًا"], "With a pronoun, إِنَّ takes the attached form: إِنَّكَ."], ["c", "\"I know that the lesson is easy\":", ["أَعْرِفُ أَنَّ الدَّرْسَ سَهْلٌ", "أَعْرِفُ أَنَّ الدَّرْسُ سَهْلٌ", "أَعْرِفُ أَنَّ الدَّرْسِ سَهْلًا"], "أَنَّ works like إِنَّ."], ["o", "إِنَّ اللهَ مَعَ الصَّابِرِينَ", "Indeed, Allah is with the patient."], ["o", "لَعَلَّ الْمَطَرَ قَرِيبٌ", "Perhaps the rain is near."]]}, {"id": "kaana", "icon": "🕰️", "title": "Kaana and its sisters", "ar": "كَانَ وَأَخَوَاتُهَا", "rule": ["كَانَ was, أَصْبَحَ became (in the morning), صَارَ became, لَيْسَ is not, مَا زَالَ still.", "The subject stays marfoo'. The news becomes mansoob: كَانَ الْجَوُّ بَارِدًا.", "كَانَ takes past endings: كُنْتُ I was, كَانَتْ she was, كُنَّا we were, كَانُوا they were."], "ex": [["كَانَ الدَّرْسُ سَهْلًا", "The lesson was easy."], ["كُنْتُ طَالِبًا", "I was a student."], ["أَصْبَحَ الْجَوُّ حَارًّا", "The weather became hot."], ["مَا زَالَ الْمَطَرُ نَازِلًا", "The rain is still falling."]], "d": [["c", "Complete: كَانَ الْجَوُّ ___ (cold)", ["بَارِدًا", "بَارِدٌ", "بَارِدٍ"], "The news of كَانَ is mansoob."], ["f", "كَانَ الْبَيْتَ كَبِيرًا", ["كَانَ الْبَيْتُ كَبِيرًا", "كَانَ الْبَيْتُ كَبِيرٌ", "كَانَ الْبَيْتِ كَبِيرًا"], "The subject of كَانَ stays marfoo'."], ["f", "صَارَ الْوَلَدُ طَوِيلٌ", ["صَارَ الْوَلَدُ طَوِيلًا", "صَارَ الْوَلَدَ طَوِيلًا", "صَارَ الْوَلَدِ طَوِيلٌ"], "صَارَ is a sister of كَانَ, so the news is mansoob."], ["c", "\"The weather became hot\":", ["أَصْبَحَ الْجَوُّ حَارًّا", "أَصْبَحَ الْجَوَّ حَارٌّ", "أَصْبَحَ الْجَوُّ حَارٌّ"], "Subject marfoo', news mansoob."], ["c", "\"I was a student\":", ["كُنْتُ طَالِبًا", "كَانَ طَالِبًا", "كُنْتُ طَالِبٌ"], "كُنْتُ = I was, and the news is mansoob."], ["c", "\"She was ill\":", ["كَانَتْ مَرِيضَةً", "كَانَ مَرِيضَةً", "كَانَتْ مَرِيضَةٌ"], "كَانَتْ for \"she\", and the news is mansoob."], ["c", "What does مَا زَالَ mean?", ["still", "never", "was not"], "مَا زَالَ = still, has not stopped."], ["c", "\"They were in the mosque\":", ["كَانُوا فِي الْمَسْجِدِ", "كَانَ فِي الْمَسْجِدِ", "كُنَّا فِي الْمَسْجِدِ"], "كَانُوا = they were."], ["o", "كَانَ الدَّرْسُ سَهْلًا", "The lesson was easy."], ["o", "أَصْبَحَ الطَّالِبُ مُجْتَهِدًا", "The student became hard-working."]]}, {"id": "plural", "icon": "👥", "title": "Sound plurals", "ar": "الْجَمْعُ السَّالِمُ", "rule": ["Masculine sound plural: ـُونَ when marfoo', ـِينَ when mansoob or majroor: مُسْلِمُونَ، مُسْلِمِينَ.", "Feminine sound plural: ـَاتٌ when marfoo', ـَاتٍ when mansoob or majroor. It never takes fathah: رَأَيْتُ الطَّالِبَاتِ.", "Many words ending in ة take ـَاتٌ: سَيَّارَةٌ ← سَيَّارَاتٌ."], "ex": [["الْمُسْلِمُونَ إِخْوَةٌ", "The Muslims are brothers."], ["رَأَيْتُ الْمُدَرِّسِينَ", "I saw the teachers."], ["الْمُعَلِّمَاتُ فِي الْمَدْرَسَةِ", "The (women) teachers are in the school."], ["سَلَّمْتُ عَلَى الطَّالِبَاتِ", "I greeted the (women) students."]], "d": [["c", "Plural of مُدَرِّسٌ (men):", ["مُدَرِّسُونَ", "مَدَارِسُ", "مُدَرِّسَانِ"], "The masculine sound plural ends in ـُونَ. مَدَارِسُ means schools."], ["c", "Plural of مُسْلِمَةٌ:", ["مُسْلِمَاتٌ", "مُسْلِمُونَ", "مُسْلِمَتَانِ"], "Feminine plural: ـَاتٌ. مُسْلِمَتَانِ means two."], ["c", "\"I saw the teachers (men)\":", ["رَأَيْتُ الْمُدَرِّسِينَ", "رَأَيْتُ الْمُدَرِّسُونَ", "رَأَيْتُ الْمُدَرِّسَاتُ"], "As an object, ـُونَ changes to ـِينَ."], ["c", "\"with the engineers (men)\":", ["مَعَ الْمُهَنْدِسِينَ", "مَعَ الْمُهَنْدِسُونَ", "مَعَ الْمُهَنْدِسَاتُ"], "After مَعَ the noun is majroor: ـِينَ."], ["f", "جَاءَ الْمُسْلِمِينَ", ["جَاءَ الْمُسْلِمُونَ", "جَاءَ الْمُسْلِمُينَ", "جَاءَ الْمُسْلِمِونَ"], "The doer is marfoo': ـُونَ."], ["f", "رَأَيْتُ الطَّالِبَاتَ", ["رَأَيْتُ الطَّالِبَاتِ", "رَأَيْتُ الطَّالِبَاتُ", "رَأَيْتُ الطَّالِبِينَاتِ"], "The feminine sound plural takes kasrah when mansoob."], ["c", "\"The believers (men) are successful\":", ["الْمُؤْمِنُونَ مُفْلِحُونَ", "الْمُؤْمِنِينَ مُفْلِحُونَ", "الْمُؤْمِنُونَ مُفْلِحِينَ"], "Subject and news are both marfoo': ـُونَ."], ["c", "Plural of سَيَّارَةٌ:", ["سَيَّارَاتٌ", "سَيَّارُونَ", "سَيَّارِينَ"], "Words ending in ة often take ـَاتٌ."], ["c", "Which ending does a masculine sound plural take after فِي?", ["ـِينَ", "ـُونَ", "ـَانِ"], "فِي makes it majroor: ـِينَ."], ["o", "الْمُسْلِمُونَ يُصَلُّونَ فِي الْمَسْجِدِ", "The Muslims pray in the mosque."]]}, {"id": "broken", "icon": "🏗️", "title": "Broken plurals", "ar": "جَمْعُ التَّكْسِيرِ", "rule": ["Many nouns change their inner shape in the plural: كِتَابٌ ← كُتُبٌ.", "Common shapes: أَفْعَالٌ (أَقْلَامٌ), فُعُولٌ (بُيُوتٌ), فِعَالٌ (رِجَالٌ), فُعُلٌ (كُتُبٌ), مَفَاعِلُ (مَسَاجِدُ), فُعَلَاءُ (عُلَمَاءُ).", "Learn each plural together with its word: see the \"Plurals you must know\" word set.", "Plurals of things are treated as feminine singular: الْكُتُبُ جَدِيدَةٌ."], "ex": [["قَلَمٌ ← أَقْلَامٌ", "pen → pens"], ["بَيْتٌ ← بُيُوتٌ", "house → houses"], ["مَسْجِدٌ ← مَسَاجِدُ", "mosque → mosques"], ["الْبُيُوتُ جَمِيلَةٌ", "The houses are beautiful."]], "d": [["c", "Plural of قَلَمٌ:", ["أَقْلَامٌ", "قُلُومٌ", "قَلَمَاتٌ"], "Shape أَفْعَالٌ."], ["c", "Plural of بَيْتٌ (house):", ["بُيُوتٌ", "بَيْتُونَ", "بَيْتَاتٌ"], "Shape فُعُولٌ."], ["c", "Plural of رَجُلٌ:", ["رِجَالٌ", "رَجُلُونَ", "رَجُلَاتٌ"], "Shape فِعَالٌ."], ["c", "Plural of مَسْجِدٌ:", ["مَسَاجِدُ", "مَسْجِدَاتٌ", "مُسُوجٌ"], "Shape مَفَاعِلُ."], ["c", "Plural of عَالِمٌ (a male scholar):", ["عُلَمَاءُ", "عَالِمُونٌ", "عَوَالِمُ"], "Shape فُعَلَاءُ."], ["c", "Plural of كِتَابٌ:", ["كُتُبٌ", "كِتَابُونَ", "أَكْتَابٌ"], "Shape فُعُلٌ."], ["c", "Singular of دُرُوسٌ:", ["دَرْسٌ", "دَارِسٌ", "مَدْرَسَةٌ"], "دَرْسٌ ← دُرُوسٌ (shape فُعُولٌ)."], ["f", "الْكُتُبُ جَدِيدُونَ", ["الْكُتُبُ جَدِيدَةٌ", "الْكُتُبُ جَدِيدٌ", "الْكُتُبَ جَدِيدَةٌ"], "Plurals of things take a feminine singular describing word."], ["c", "Singular of أَوْلَادٌ:", ["وَلَدٌ", "لَدٌّ", "وَالِدٌ"], "وَلَدٌ ← أَوْلَادٌ (shape أَفْعَالٌ)."], ["o", "هٰذِهِ الْبُيُوتُ جَمِيلَةٌ", "These houses are beautiful."]]}, {"id": "dual", "icon": "✌️", "title": "Two of something: the dual", "ar": "الْمُثَنَّى", "rule": ["Add ـَانِ when marfoo' and ـَيْنِ when mansoob or majroor: كِتَابَانِ، كِتَابَيْنِ.", "ة becomes ت: سَيَّارَةٌ ← سَيَّارَتَانِ.", "In an idaafah the ن falls away: كِتَابَا الطَّالِبِ = the student's two books.", "Dual pronouns: هُمَا they two, أَنْتُمَا you two."], "ex": [["عِنْدِي أَخَوَانِ", "I have two brothers."], ["قَرَأْتُ كِتَابَيْنِ", "I read two books."], ["فِي الْبَيْتِ غُرْفَتَانِ", "There are two rooms in the house."], ["هُمَا طَالِبَانِ", "They (two) are students."]], "d": [["c", "\"two books\" (as subject):", ["كِتَابَانِ", "كِتَابَيْنِ", "كِتَابُونَ"], "Marfoo' dual: ـَانِ."], ["c", "\"I bought two pens\":", ["اِشْتَرَيْتُ قَلَمَيْنِ", "اِشْتَرَيْتُ قَلَمَانِ", "اِشْتَرَيْتُ أَقْلَامَانِ"], "As an object the dual is ـَيْنِ."], ["c", "\"two cars\":", ["سَيَّارَتَانِ", "سَيَّارَةَانِ", "سَيَّارَاتَانِ"], "ة becomes ت before the dual ending."], ["c", "\"in two days\":", ["فِي يَوْمَيْنِ", "فِي يَوْمَانِ", "فِي أَيَّامَيْنِ"], "After a preposition: ـَيْنِ."], ["f", "جَاءَ الطَّالِبَيْنِ", ["جَاءَ الطَّالِبَانِ", "جَاءَ الطَّالِبَانُ", "جَاءَ الطَّالِبَيْنُ"], "The doer is marfoo': ـَانِ."], ["c", "\"they two\" is…", ["هُمَا", "هُمْ", "هُنَّ"], "هُمَا is the dual pronoun."], ["c", "\"the student's two books\":", ["كِتَابَا الطَّالِبِ", "كِتَابَانِ الطَّالِبِ", "الْكِتَابَانِ الطَّالِبِ"], "In an idaafah the ن of the dual falls away."], ["c", "\"two girls\" (as subject):", ["بِنْتَانِ", "بِنْتَيْنِ", "بَنَاتَانِ"], "Marfoo' dual: ـَانِ."], ["o", "عِنْدِي أَخَوَانِ وَأُخْتٌ", "I have two brothers and a sister."], ["o", "هُمَا طَالِبَانِ مُجْتَهِدَانِ", "They two are hard-working students."]]}, {"id": "num", "icon": "🔢", "title": "Numbers 3 to 10", "ar": "الْأَعْدَادُ", "rule": ["1 and 2 come after the noun and match it: كِتَابٌ وَاحِدٌ، بِنْتَانِ اثْنَتَانِ.", "3 to 10 take the opposite gender of the singular noun.", "The noun after 3 to 10 is plural and majroor: ثَلَاثَةُ كُتُبٍ (كِتَابٌ is masculine, so the number takes ة).", "ثَلَاثُ سَيَّارَاتٍ (سَيَّارَةٌ is feminine, so the number has no ة)."], "ex": [["ثَلَاثَةُ كُتُبٍ", "three books"], ["خَمْسُ سَيَّارَاتٍ", "five cars"], ["سَبْعَةُ أَيَّامٍ", "seven days"], ["عَشْرُ بَنَاتٍ", "ten girls"]], "d": [["c", "\"three books\":", ["ثَلَاثَةُ كُتُبٍ", "ثَلَاثُ كُتُبٍ", "ثَلَاثَةُ كِتَابٍ"], "كِتَابٌ is masculine, so the number takes ة; the noun is plural majroor."], ["c", "\"five cars\":", ["خَمْسُ سَيَّارَاتٍ", "خَمْسَةُ سَيَّارَاتٍ", "خَمْسُ سَيَّارَةٍ"], "سَيَّارَةٌ is feminine, so the number has no ة."], ["c", "\"four girls\":", ["أَرْبَعُ بَنَاتٍ", "أَرْبَعَةُ بَنَاتٍ", "أَرْبَعُ بِنْتٍ"], "بِنْتٌ is feminine, so أَرْبَعُ."], ["c", "\"ten men\":", ["عَشَرَةُ رِجَالٍ", "عَشْرُ رِجَالٍ", "عَشَرَةُ رَجُلٍ"], "رَجُلٌ is masculine, so عَشَرَةُ."], ["c", "\"seven days\":", ["سَبْعَةُ أَيَّامٍ", "سَبْعُ أَيَّامٍ", "سَبْعَةُ يَوْمٍ"], "يَوْمٌ is masculine, so سَبْعَةُ."], ["f", "ثَلَاثَةُ سَاعَاتٍ", ["ثَلَاثُ سَاعَاتٍ", "ثَلَاثَةُ سَاعَةٍ", "ثَلَاثُ سَاعَةٌ"], "سَاعَةٌ is feminine, so the number drops ة."], ["f", "عِنْدِي خَمْسُ أَقْلَامٍ", ["عِنْدِي خَمْسَةُ أَقْلَامٍ", "عِنْدِي خَمْسُ قَلَمٍ", "عِنْدِي خَمْسَةُ قَلَمٌ"], "قَلَمٌ is masculine, so خَمْسَةُ."], ["c", "\"one book\":", ["كِتَابٌ وَاحِدٌ", "وَاحِدُ كِتَابٍ", "وَاحِدَةُ كِتَابٍ"], "1 comes after the noun and matches it."], ["c", "\"six questions\":", ["سِتَّةُ أَسْئِلَةٍ", "سِتُّ أَسْئِلَةٍ", "سِتَّةُ سُؤَالٍ"], "سُؤَالٌ is masculine, so سِتَّةُ."], ["o", "فِي الْفَصْلِ عَشَرَةُ طُلَّابٍ", "There are ten students in the class."]]}, {"id": "qwords", "icon": "❓", "title": "Asking questions", "ar": "أَدَوَاتُ الِاسْتِفْهَامِ", "rule": ["هَلْ or أَ make a yes or no question: هَلْ أَنْتَ طَالِبٌ؟", "مَا = what (before nouns), مَاذَا = what (before verbs), مَنْ = who.", "أَيْنَ where, مَتَى when, كَيْفَ how, لِمَاذَا why, أَيُّ which.", "كَمْ = how many. The noun after it is singular with fathah tanween: كَمْ كِتَابًا؟"], "ex": [["هَلْ أَنْتَ طَالِبٌ؟", "Are you a student?"], ["مَاذَا تَقْرَأُ؟", "What are you reading?"], ["مَتَى الدَّرْسُ؟", "When is the lesson?"], ["كَمْ أَخًا لَكَ؟", "How many brothers do you have?"]], "d": [["c", "Which word asks \"where\"?", ["أَيْنَ", "مَتَى", "كَيْفَ"], "أَيْنَ = where."], ["c", "\"What do you want?\" (to a man):", ["مَاذَا تُرِيدُ؟", "مَنْ تُرِيدُ؟", "أَيْنَ تُرِيدُ؟"], "مَاذَا is used before verbs."], ["c", "\"How many books do you have?\":", ["كَمْ كِتَابًا عِنْدَكَ؟", "كَمْ كُتُبٌ عِنْدَكَ؟", "كَمْ كِتَابٌ عِنْدَكَ؟"], "After كَمْ comes a singular noun with fathah tanween."], ["c", "\"Who is this?\":", ["مَنْ هٰذَا؟", "مَا هٰذَا؟", "أَيْنَ هٰذَا؟"], "مَنْ asks about people."], ["c", "\"Why are you late?\":", ["لِمَاذَا تَأَخَّرْتَ؟", "مَتَى تَأَخَّرْتَ؟", "كَيْفَ تَأَخَّرْتَ؟"], "لِمَاذَا = why."], ["c", "\"When is the lesson?\":", ["مَتَى الدَّرْسُ؟", "كَمِ الدَّرْسُ؟", "مَنِ الدَّرْسُ؟"], "مَتَى = when."], ["f", "مَنْ هٰذَا؟ هٰذَا كِتَابٌ", ["مَا هٰذَا؟ هٰذَا كِتَابٌ", "أَيْنَ هٰذَا؟ هٰذَا كِتَابٌ", "كَيْفَ هٰذَا؟ هٰذَا كِتَابٌ"], "For things use مَا; مَنْ is for people."], ["c", "Which word turns a sentence into a yes or no question?", ["هَلْ", "مَاذَا", "لِمَاذَا"], "هَلْ أَنْتَ طَالِبٌ؟ = Are you a student?"], ["o", "أَيْنَ تَسْكُنُ يَا أَخِي؟", "Where do you live, my brother?"], ["o", "كَيْفَ حَالُكَ الْيَوْمَ؟", "How are you today?"]]}, {"id": "verbal", "icon": "🏃", "title": "Verbal sentences: doer and object", "ar": "الْجُمْلَةُ الْفِعْلِيَّةُ", "rule": ["A verbal sentence starts with a verb: verb + doer (فَاعِلٌ) + object (مَفْعُولٌ بِهِ).", "The doer is marfoo' and the object is mansoob: كَتَبَ الطَّالِبُ الدَّرْسَ.", "When the verb comes first, it stays singular even with a plural doer: ذَهَبَ الطُّلَّابُ.", "A feminine doer gives the verb ـَتْ: ذَهَبَتِ الْبِنْتُ."], "ex": [["فَتَحَ الْوَلَدُ النَّافِذَةَ", "The boy opened the window."], ["أَكَلَتِ الْبِنْتُ التُّفَّاحَةَ", "The girl ate the apple."], ["ذَهَبَ الطُّلَّابُ إِلَى الْمَسْجِدِ", "The students went to the mosque."], ["خَلَقَ اللهُ السَّمَاوَاتِ", "Allah created the heavens."]], "d": [["c", "Complete: قَرَأَ الطَّالِبُ ___ (the book)", ["الْكِتَابَ", "الْكِتَابُ", "الْكِتَابِ"], "The object is mansoob."], ["c", "Complete: كَتَبَ ___ الرِّسَالَةَ (the teacher)", ["الْمُدَرِّسُ", "الْمُدَرِّسَ", "الْمُدَرِّسِ"], "The doer is marfoo'."], ["f", "ذَهَبُوا الطُّلَّابُ إِلَى الْمَسْجِدِ", ["ذَهَبَ الطُّلَّابُ إِلَى الْمَسْجِدِ", "ذَهَبَ الطُّلَّابَ إِلَى الْمَسْجِدِ", "ذَهَبْنَا الطُّلَّابُ إِلَى الْمَسْجِدِ"], "When the verb comes first, it stays singular."], ["f", "جَلَسَ الْبِنْتُ عَلَى الْكُرْسِيِّ", ["جَلَسَتِ الْبِنْتُ عَلَى الْكُرْسِيِّ", "جَلَسَ الْبِنْتَ عَلَى الْكُرْسِيِّ", "جَلَسْتُ الْبِنْتُ عَلَى الْكُرْسِيِّ"], "A feminine doer needs ـَتْ on the verb."], ["c", "In فَتَحَ زَيْدٌ الْبَابَ, the doer is…", ["زَيْدٌ", "الْبَابَ", "فَتَحَ"], "The doer is marfoo': زَيْدٌ."], ["c", "In شَرِبَ الْوَلَدُ الْحَلِيبَ, the object is…", ["الْحَلِيبَ", "الْوَلَدُ", "شَرِبَ"], "The object is mansoob: الْحَلِيبَ."], ["c", "\"The (women) teachers came\":", ["جَاءَتِ الْمُدَرِّسَاتُ", "جِئْنَ الْمُدَرِّسَاتُ", "جَاءَ الْمُدَرِّسَاتَ"], "Verb first, so it is singular and feminine: جَاءَتْ."], ["o", "فَتَحَ الْوَلَدُ النَّافِذَةَ", "The boy opened the window."], ["o", "أَكَلَتِ الْبِنْتُ التُّفَّاحَةَ", "The girl ate the apple."], ["c", "\"Allah created the heavens\":", ["خَلَقَ اللهُ السَّمَاوَاتِ", "خَلَقَ اللهَ السَّمَاوَاتُ", "خَلَقَ اللهُ السَّمَاوَاتُ"], "The doer اللهُ is marfoo'. السَّمَاوَاتِ is a feminine plural object, so it takes kasrah."]]}, {"id": "compare", "icon": "📈", "title": "Bigger and biggest", "ar": "اسْمُ التَّفْضِيلِ", "rule": ["The shape أَفْعَلُ means \"more\": كَبِيرٌ ← أَكْبَرُ.", "\"than\" is مِنْ: الْبَحْرُ أَكْبَرُ مِنَ النَّهْرِ.", "أَفْعَلُ + an indefinite noun means \"the most\": أَكْبَرُ مَدِينَةٍ = the biggest city.", "In comparisons أَفْعَلُ does not change for women: فَاطِمَةُ أَطْوَلُ مِنْ مَرْيَمَ."], "ex": [["الْبَحْرُ أَكْبَرُ مِنَ النَّهْرِ", "The sea is bigger than the river."], ["اللهُ أَكْبَرُ", "Allah is the Greatest."], ["هٰذَا أَسْهَلُ دَرْسٍ", "This is the easiest lesson."], ["فَاطِمَةُ أَطْوَلُ مِنْ مَرْيَمَ", "Fatimah is taller than Maryam."]], "d": [["c", "\"bigger\":", ["أَكْبَرُ", "كُبْرَى", "كَبِيرٌ"], "Shape أَفْعَلُ from كَبِيرٌ."], ["c", "\"smaller than the house\":", ["أَصْغَرُ مِنَ الْبَيْتِ", "صَغِيرٌ مِنَ الْبَيْتِ", "أَصْغَرُ الْبَيْتِ"], "\"than\" is مِنْ."], ["c", "\"the biggest city\":", ["أَكْبَرُ مَدِينَةٍ", "أَكْبَرُ مِنْ مَدِينَةٍ", "الْمَدِينَةُ أَكْبَرُ"], "أَفْعَلُ + an indefinite noun = the most…"], ["c", "\"Fatimah is taller than Maryam\":", ["فَاطِمَةُ أَطْوَلُ مِنْ مَرْيَمَ", "فَاطِمَةُ طَوِيلَةٌ مِنْ مَرْيَمَ", "فَاطِمَةُ أَطْوَلَةٌ مِنْ مَرْيَمَ"], "In comparisons أَفْعَلُ stays the same for women."], ["c", "\"more beautiful\":", ["أَجْمَلُ", "جَمِيلٌ", "جَمَالٌ"], "جَمِيلٌ ← أَجْمَلُ."], ["c", "\"easier\":", ["أَسْهَلُ", "سَهْلٌ", "سُهُولَةٌ"], "سَهْلٌ ← أَسْهَلُ."], ["c", "\"nearer\":", ["أَقْرَبُ", "قَرِيبٌ", "قُرْبٌ"], "قَرِيبٌ ← أَقْرَبُ."], ["f", "الْقِطَارُ سَرِيعٌ مِنَ السَّيَّارَةِ", ["الْقِطَارُ أَسْرَعُ مِنَ السَّيَّارَةِ", "الْقِطَارُ أَسْرَعُ السَّيَّارَةِ", "الْقِطَارُ سُرْعَةٌ مِنَ السَّيَّارَةِ"], "To compare, use أَفْعَلُ + مِنْ."], ["c", "What does اللهُ أَكْبَرُ mean?", ["Allah is the Greatest", "Allah is big", "Allah is near"], "أَكْبَرُ = greater, greatest."], ["o", "الْبَحْرُ أَكْبَرُ مِنَ النَّهْرِ", "The sea is bigger than the river."]]}, {"id": "relative", "icon": "🪢", "title": "Who, which, that", "ar": "الْأَسْمَاءُ الْمَوْصُولَةُ", "rule": ["الَّذِي = who, which (masculine), الَّتِي = who, which (feminine), الَّذِينَ = who (a group of people).", "They are used after a definite noun: الرَّجُلُ الَّذِي جَاءَ = the man who came.", "After an indefinite noun no such word is used: رَجُلٌ جَاءَ = a man who came.", "Plurals of things take الَّتِي: الْكُتُبُ الَّتِي قَرَأْتُهَا."], "ex": [["الرَّجُلُ الَّذِي جَاءَ", "the man who came"], ["الْبِنْتُ الَّتِي كَتَبَتْ", "the girl who wrote"], ["الطُّلَّابُ الَّذِينَ نَجَحُوا", "the students who passed"], ["الْحَمْدُ لِلَّهِ الَّذِي خَلَقَنَا", "Praise be to Allah who created us."]], "d": [["c", "\"the man who came\":", ["الرَّجُلُ الَّذِي جَاءَ", "الرَّجُلُ الَّتِي جَاءَ", "رَجُلٌ الَّذِي جَاءَ"], "الَّذِي after a definite masculine noun."], ["c", "\"the girl who wrote\":", ["الْبِنْتُ الَّتِي كَتَبَتْ", "الْبِنْتُ الَّذِي كَتَبَتْ", "الْبِنْتُ الَّذِينَ كَتَبَتْ"], "الَّتِي for feminine."], ["c", "\"the students who passed\":", ["الطُّلَّابُ الَّذِينَ نَجَحُوا", "الطُّلَّابُ الَّذِي نَجَحُوا", "الطُّلَّابُ الَّتِي نَجَحُوا"], "الَّذِينَ for a group of people."], ["c", "\"a book that I read\":", ["كِتَابٌ قَرَأْتُهُ", "كِتَابٌ الَّذِي قَرَأْتُهُ", "الْكِتَابُ قَرَأْتُ"], "After an indefinite noun no الَّذِي is used."], ["f", "السَّيَّارَةُ الَّذِي اشْتَرَيْتُهَا جَمِيلَةٌ", ["السَّيَّارَةُ الَّتِي اشْتَرَيْتُهَا جَمِيلَةٌ", "السَّيَّارَةُ الَّذِينَ اشْتَرَيْتُهَا جَمِيلَةٌ", "سَيَّارَةٌ الَّتِي اشْتَرَيْتُهَا جَمِيلَةٌ"], "السَّيَّارَةُ is feminine: الَّتِي."], ["c", "What does مَنْ mean in مَنْ صَبَرَ ظَفِرَ?", ["whoever", "who? (a question)", "from"], "Whoever is patient succeeds."], ["c", "\"the books which are on the table\":", ["الْكُتُبُ الَّتِي عَلَى الطَّاوِلَةِ", "الْكُتُبُ الَّذِينَ عَلَى الطَّاوِلَةِ", "الْكُتُبُ الَّذِي عَلَى الطَّاوِلَةِ"], "Plurals of things are treated as feminine singular: الَّتِي."], ["o", "هٰذَا هُوَ الْكِتَابُ الَّذِي قَرَأْتُهُ", "This is the book that I read."], ["o", "الْحَمْدُ لِلَّهِ الَّذِي خَلَقَنَا", "Praise be to Allah who created us."], ["c", "الَّذِي, الَّتِي and الَّذِينَ come after…", ["definite nouns", "indefinite nouns", "verbs only"], "They follow a noun with الـ, or a name."]]}, {"id": "forms", "icon": "🌳", "title": "Verb families", "ar": "أَوْزَانُ الْفِعْلِ", "rule": ["From one root, different shapes give related meanings.", "فَعَلَ: عَلِمَ he knew. فَعَّلَ: عَلَّمَ he taught (made someone know).", "فَاعَلَ: جَاهَدَ he strove (with or against someone). أَفْعَلَ: أَخْرَجَ he took out.", "تَفَعَّلَ: تَعَلَّمَ he learned. اِفْتَعَلَ: اِجْتَمَعَ they gathered. اِسْتَفْعَلَ: اِسْتَغْفَرَ he sought forgiveness.", "In the present, families فَعَّلَ، فَاعَلَ and أَفْعَلَ start with يُـ: يُعَلِّمُ، يُجَاهِدُ، يُخْرِجُ."], "ex": [["عَلَّمَنِي أَبِي الْقُرْآنَ", "My father taught me the Quran."], ["تَعَلَّمْتُ الْعَرَبِيَّةَ", "I learned Arabic."], ["أَسْتَغْفِرُ اللهَ", "I seek Allah's forgiveness."], ["اِجْتَمَعَ النَّاسُ فِي الْمَسْجِدِ", "The people gathered in the mosque."]], "d": [["c", "عَلِمَ = he knew. عَلَّمَ = …", ["he taught", "he learned", "he was taught"], "The shape فَعَّلَ often means making someone do something."], ["c", "Which verb means \"he learned\"?", ["تَعَلَّمَ", "عَلَّمَ", "أَعْلَمَ"], "Shape تَفَعَّلَ: تَعَلَّمَ."], ["c", "غَفَرَ = he forgave. اِسْتَغْفَرَ = …", ["he sought forgiveness", "he forgave a lot", "he was forgiven"], "The shape اِسْتَفْعَلَ often means asking for something."], ["c", "خَرَجَ = he went out. أَخْرَجَ = …", ["he took out", "he went out again", "he wanted to go out"], "The shape أَفْعَلَ often means making something happen."], ["c", "Which shape is اِجْتَمَعَ (they gathered)?", ["اِفْتَعَلَ", "اِسْتَفْعَلَ", "تَفَاعَلَ"], "اِجْتَمَعَ: اِ + ج + ت + مَعَ."], ["c", "Which shape is قَاتَلَ (he fought against)?", ["فَاعَلَ", "فَعَّلَ", "أَفْعَلَ"], "A long aa after the first letter: فَاعَلَ."], ["c", "\"he used\" (root عَمِلَ, to work):", ["اِسْتَعْمَلَ", "عَمَّلَ", "تَعَامَلَ"], "اِسْتَعْمَلَ = he used."], ["c", "Present of عَلَّمَ:", ["يُعَلِّمُ", "يَعْلَمُ", "يَتَعَلَّمُ"], "Families فَعَّلَ، فَاعَلَ and أَفْعَلَ start the present with يُـ."], ["c", "Present of أَرْسَلَ (he sent):", ["يُرْسِلُ", "يَرْسُلُ", "يَتَرَسَّلُ"], "Family أَفْعَلَ: يُفْعِلُ."], ["c", "Present of اِسْتَغْفَرَ:", ["يَسْتَغْفِرُ", "يُسْتَغْفِرُ", "يَغْفِرُ"], "Family اِسْتَفْعَلَ: يَسْتَفْعِلُ."]]}];
function dayNo(){var d=new Date();return Math.floor((d.getTime()-d.getTimezoneOffset()*6e4)/864e5);}
function pctBar(p,cls){return '<span class="meter'+(cls?' '+cls:'')+'"><i style="width:'+Math.max(0,Math.min(100,p))+'%"></i></span>';}
function tile(v,l,sub){return '<div class="tile"><b>'+v+'</b><span>'+l+'</span>'+(sub?'<small>'+sub+'</small>':'')+'</div>';}

/* ---------- grammar ---------- */
function gT(id){return GRAM.filter(function(t){return t.id===id;})[0];}
function gStat(id){D.gram=D.gram||{};var s=D.gram[id];return s?{b:s.b||0,n:s.n||0,r:s.r||0,t:s.t||0}:{b:0,n:0,r:0,t:0};}
function gLevel(id){var s=gStat(id);if(!s.n)return 0;return s.b>=90?3:s.b>=70?2:1;}
var GLV=[['New',''],['Needs work','warn'],['Good','good'],['Mastered','ok']];
function gAcc(id){var s=gStat(id);return s.t?Math.round(s.r/s.t*100):null;}
function gMastered(){return GRAM.filter(function(t){return gLevel(t.id)===3;}).length;}
function gPractised(){return GRAM.filter(function(t){return gStat(t.id).n>0;}).length;}
function gWeak(n){return GRAM.filter(function(t){return gStat(t.id).n&&gLevel(t.id)<3;}).sort(function(a,b){return (gStat(a.id).b)-(gStat(b.id).b);}).slice(0,n);}
function gNext(){return GRAM.filter(function(t){return gLevel(t.id)<2;})[0]||GRAM.filter(function(t){return gLevel(t.id)<3;})[0];}
function gTotalAcc(){var r=0,t=0;GRAM.forEach(function(x){var s=gStat(x.id);r+=s.r;t+=s.t;});return t?Math.round(r/t*100):null;}
function gItem(t,i){var d=t.d[i],it={tid:t.id,idx:i,type:d[0]};
  if(d[0]==='o'){it.words=d[1].split(' ');it.en=d[2];it.tiles=shuffle(it.words.map(function(w,k){return {w:w,k:k,used:false};}));
    if(it.words.length>1&&it.tiles.every(function(x,j){return x.k===j;}))it.tiles.reverse();it.built=[];}
  else{it.q=d[1];var right=d[2][0];it.o=shuffle(d[2]);it.a=it.o.indexOf(right);it.why=d[3];}
  return it;}
function gStart(title,pairs,ref){
  S.gd={title:title,items:pairs.map(function(p){return gItem(p[0],p[1]);}),i:0,score:0,pick:-1,checked:false,ref:ref,end:false,miss:0};
  trk('quiz_started',{kind:'grammar_drill',question_count:S.gd.items.length});render();scrollTo(0,0);}
function gTopicDrill(id){var t=gT(id);gStart(t.title,shuffle(t.d.map(function(_,i){return [t,i];})).slice(0,8),id);}
function gMixDrill(kind){var pairs=[];
  if(kind==='mistakes'){(D.gmiss||[]).forEach(function(key){var p=key.split(':'),t=gT(p[0]);if(t&&t.d[+p[1]])pairs.push([t,+p[1]]);});pairs=shuffle(pairs).slice(0,10);}
  else if(kind==='weak'){var w=gWeak(3);if(!w.length)w=GRAM.filter(function(t){return gLevel(t.id)<3;}).slice(0,3);
    w.forEach(function(t){shuffle(t.d.map(function(_,i){return i;})).slice(0,4).forEach(function(i){pairs.push([t,i]);});});pairs=shuffle(pairs).slice(0,10);}
  else{var pool=GRAM.filter(function(t){return gLevel(t.id)<3;});if(pool.length<5)pool=GRAM;
    shuffle(pool).slice(0,5).forEach(function(t){shuffle(t.d.map(function(_,i){return i;})).slice(0,2).forEach(function(i){pairs.push([t,i]);});});pairs=shuffle(pairs);}
  if(!pairs.length){toast('Nothing to practise here yet');return;}
  gStart(kind==='mistakes'?'Fix my mistakes':kind==='weak'?'My weak spots':'Daily grammar workout',pairs,'mix:'+kind);}
function gAnswer(ok){var G=S.gd,it=G.items[G.i],key=it.tid+':'+it.idx;D.gmiss=D.gmiss||[];
  var st=gStat(it.tid);st.t++;if(ok)st.r++;D.gram[it.tid]=st;
  var mi=D.gmiss.indexOf(key);
  if(ok){G.score++;sfx('ok');if(mi>=0)D.gmiss.splice(mi,1);}
  else{sfx('bad');G.miss++;if(mi<0){D.gmiss.push(key);if(D.gmiss.length>80)D.gmiss.shift();}}
  it.ok=ok;G.checked=true;trk('quiz_answered',{kind:'grammar_drill',question_number:G.i+1,correct:ok});save();}
function gFinish(){var G=S.gd,pct=Math.round(G.score/G.items.length*100),xp=G.score*5,msg='';G.end=true;
  if(G.ref.indexOf('mix:')!==0){var st=gStat(G.ref),was=gLevel(G.ref);st.n++;if(pct>st.b)st.b=pct;D.gram[G.ref]=st;if(gLevel(G.ref)===3&&was<3){xp+=25;msg='Topic mastered';}}
  trk('quiz_completed',{kind:'grammar_drill',score:G.score,question_count:G.items.length,percent:pct,passed:pct>=70});
  save();addXP(xp,msg);if(pct===100){confetti();sfx('win');}}
function gStatus(id){var l=gLevel(id),s=gStat(id);return '<span class="tag '+GLV[l][1]+'">'+GLV[l][0]+(s.n?' · Best '+s.b+'%':'')+'</span>';}
function viewGrammar(){
  if(S.gd)return viewGDrill();
  if(S.gtopic){var t=gT(S.gtopic),s=gStat(t.id),acc=gAcc(t.id);
    return '<button class="btn back" data-act="g_back">← All grammar topics</button><div class="lead"><h1>'+t.icon+' '+esc(t.title)+' <span class="ar" lang="ar" style="color:var(--primary)">'+esc(t.ar)+'</span></h1><p>'+gStatus(t.id)+(acc!=null?' <span class="note">'+acc+'% of your answers on this topic were right</span>':'')+'</p></div>'+
    '<div class="panel"><h2>The rule</h2><ul>'+t.rule.map(function(r){return '<li>'+mix(r)+'</li>';}).join('')+'</ul></div>'+
    '<div class="panel"><h2>Examples</h2><table>'+t.ex.map(function(e){return '<tr><td class="ar" lang="ar" style="font-size:24px">'+esc(e[0])+' '+sayBtn(e[0])+'</td><td>'+mix(e[1])+'</td></tr>';}).join('')+'</table></div>'+
    '<div class="panel"><h2>Practise</h2><p>8 questions: choose the right form, fix the mistake and build the sentence. Score 90% or more to master this topic.</p><div class="btnrow"><button class="btn primary" data-act="g_drill" data-id="'+t.id+'" style="font-size:18px;padding:12px 22px">Practise this topic</button></div>'+(s.n?'<p class="note">Practised '+s.n+' time'+(s.n>1?'s':'')+'.</p>':'')+'</div>';}
  var miss=(D.gmiss||[]).length,acc=gTotalAcc(),nx=gNext(),weak=gWeak(3);
  return '<div class="lead"><h1>Improve your grammar</h1><p>'+GRAM.length+' topics, each with the rule, examples and practice. Wrong answers come back until you get them right.</p></div>'+
  '<div class="tiles">'+tile(gMastered()+'/'+GRAM.length,'topics mastered')+tile(gPractised(),'topics practised')+tile(acc==null?'–':acc+'%','answers right')+tile(miss,'mistakes to fix')+'</div>'+
  '<div class="panel"><h2>Practise now</h2><div class="btnrow"><button class="btn primary" data-act="g_mix" data-id="workout">💪 Daily workout · 10 questions</button><button class="btn" data-act="g_mix" data-id="weak">🎯 My weak spots</button><button class="btn" data-act="g_mix" data-id="mistakes"'+(miss?'':' disabled')+'>🔁 Fix my mistakes'+(miss?' ('+miss+')':'')+'</button></div>'+
  (weak.length?'<p class="note">Weakest topics: '+weak.map(function(t){return '<button class="linkbtn" data-act="g_topic" data-id="'+t.id+'">'+esc(t.title)+' ('+gStat(t.id).b+'%)</button>';}).join(', ')+'</p>':'')+
  (nx?'<p class="note">Next topic to study: <button class="linkbtn" data-act="g_topic" data-id="'+nx.id+'">'+nx.icon+' '+esc(nx.title)+'</button></p>':'<p class="note">Maa shaa Allah, every topic is mastered. Keep them fresh with the daily workout.</p>')+'</div>'+
  '<h2 class="lvh">All topics</h2><div class="grid">'+GRAM.map(function(t,i){var s=gStat(t.id),l=gLevel(t.id);
    return '<button class="card'+(l===3?' done':'')+'" data-act="g_topic" data-id="'+t.id+'"><span class="n">TOPIC '+(i+1)+'</span><h3>'+t.icon+' '+esc(t.title)+'</h3><span class="ar" lang="ar">'+esc(t.ar)+'</span>'+pctBar(s.b,l===3?'ok':l===1?'warn':'')+gStatus(t.id)+'</button>';}).join('')+'</div>';}
function gNextBtn(G){return '<button class="btn primary" data-act="g_next">'+(G.i===G.items.length-1?'See result':'Next question')+' →</button>';}
function viewGDrill(){var G=S.gd;
  if(G.end){var pct=Math.round(G.score/G.items.length*100);
    return '<div class="q panel result" style="text-align:center"><h2>'+esc(G.title)+'</h2><div class="score">'+G.score+' / '+G.items.length+'</div><p style="font-weight:800;font-size:20px">'+(pct===100?'Maa shaa Allah, perfect!':pct>=70?'Well done!':'Keep going. Read the rule again and retry.')+'</p>'+
    (G.miss?'<p class="note">'+G.miss+' question'+(G.miss>1?'s were':' was')+' added to "Fix my mistakes".</p>':'')+
    '<div class="btnrow" style="justify-content:center"><button class="btn primary" data-act="g_again">Try again</button>'+(G.ref.indexOf('mix:')!==0?'<button class="btn" data-act="g_rule">Read the rule</button>':'')+'<button class="btn" data-act="g_exit">Continue</button></div></div>';}
  var it=G.items[G.i],t=gT(it.tid),body='',lbl=it.type==='c'?'Choose the right answer':it.type==='f'?'Fix the mistake':'Build the sentence';
  body+='<div class="tag">'+esc(G.title)+' · '+(G.i+1)+' of '+G.items.length+'</div> <span class="tag">'+t.icon+' '+esc(t.title)+'</span><p class="gtype">'+lbl+'</p>';
  if(it.type==='o'){
    body+='<h2>Put the words in order to say:</h2><p class="gen">“'+esc(it.en)+'”</p>'+
    '<div class="gbuild'+(G.checked?(it.ok?' right':' wrong'):'')+'" dir="rtl" lang="ar">'+(it.built.length?it.built.map(function(ti,j){return '<button class="gw" data-act="g_unt" data-k="'+j+'" data-ns'+(G.checked?' disabled':'')+'>'+esc(it.tiles[ti].w)+'</button>';}).join(''):'<span class="ph">Tap the words below</span>')+'</div>'+
    '<div class="gtiles" dir="rtl" lang="ar">'+it.tiles.map(function(x,k){return '<button class="gw" data-act="g_tile" data-k="'+k+'" data-ns'+(x.used||G.checked?' disabled':'')+'>'+esc(x.w)+'</button>';}).join('')+'</div>';
    if(!G.checked)body+='<div class="btnrow"><button class="btn primary" data-act="g_check"'+(it.built.length===it.words.length?'':' disabled')+'>Check <kbd>↵</kbd></button><button class="btn" data-act="g_clear">Clear</button></div>';
    else body+='<div class="qfoot'+(it.ok?' ok':' no')+'"><div class="why">'+(it.ok?'✅ Correct. ':'❌ Not quite. The right order is: ')+'<span class="ar" lang="ar" style="font-size:24px">'+esc(it.words.join(' '))+'</span> '+sayBtn(it.words.join(' '))+'</div>';if(G.checked)body+=gNextBtn(G)+'</div>';
  }else{
    body+=(it.type==='f'?'<h2>This sentence has a mistake. Which version is correct?</h2><div class="gwrong ar" lang="ar">'+esc(it.q)+'</div>':'<h2 style="margin-top:8px">'+mix(it.q)+'</h2>')+
    '<div class="opts">'+it.o.map(function(o,k){var a=AR.test(o),cls='opt'+(a?' ar':'')+(G.checked&&k===it.a?' right':'')+(G.checked&&k===G.pick&&k!==it.a?' wrong':'');
      return '<button class="'+cls+'" data-act="g_pick" data-k="'+k+'" data-ns'+(G.checked?' disabled':'')+(a?' lang="ar"':'')+'><kbd>'+(k+1)+'</kbd><span>'+esc(o)+'</span></button>';}).join('')+'</div>';
    if(G.checked)body+='<div class="qfoot'+(it.ok?' ok':' no')+'"><div class="why">'+(it.ok?'✅ Correct. ':'❌ Not quite. ')+mix(it.why)+'</div>'+gNextBtn(G)+'</div>';
    else body+='<p class="hint">Tip: press 1–'+it.o.length+' to answer</p>';
  }
  return '<button class="btn back" data-act="g_exit">← Stop</button><div class="q"><div class="prog"><i style="width:'+(G.i/G.items.length*100)+'%"></i></div><div class="panel">'+body+'</div></div>';}

/* ---------- vocabulary trainer (spaced repetition) ---------- */
var VIV=[0,1,3,7,16,35];
function vE(ar){return D.vb&&D.vb[ar];}
function vDue(){var t=dayNo();return allWords().filter(function(w){var e=vE(w[0]);return e&&e[0]>0&&e[1]<=t;});}
function vLearned(){return allWords().filter(function(w){var e=vE(w[0]);return e&&e[0]>0;}).length;}
function vMastered(){return allWords().filter(function(w){var e=vE(w[0]);return e&&e[0]>=4;}).length;}
function vHard(){return allWords().filter(function(w){var e=vE(w[0]);return e&&e[2]>0&&e[0]<4;}).sort(function(a,b){return vE(b[0])[2]-vE(a[0])[2];});}
function vSetOf(w){for(var i=0;i<SETS.length;i++)if(SETS[i].w.indexOf(w)>=0)return SETS[i];return null;}
function vNew(setId,n){var pool=setId&&setId!=='any'?((SETS.filter(function(s){return s.id===setId;})[0]||{w:[]}).w):allWords();
  var seen={};return pool.filter(function(w){if(seen[w[0]]||vE(w[0]))return false;seen[w[0]]=1;return true;}).slice(0,n);}
function vMark(w,ok){D.vb=D.vb||{};var e=(D.vb[w[0]]||[0,0,0,0]).slice(),t=dayNo();
  if(ok)e[0]=Math.min(5,(e[0]||0)+1);else{e[0]=1;e[2]=(e[2]||0)+1;}
  e[1]=t+(ok?VIV[e[0]]:0);e[3]=Date.now();D.vb[w[0]]=e;}
function vModes(){return canSay?['meaning','reverse','listen']:['meaning','reverse'];}
function vQ(w){var m=D.vmode||'mix';if(m==='mix'||vModes().indexOf(m)<0)m=vModes()[(Math.random()*vModes().length)|0];
  var st=vSetOf(w),pool=(st&&st.w.length>=8?st.w:allWords()).filter(function(x){return x[0]!==w[0]&&x[2]!==w[2];});var ds=sample(pool,3);
  if(m==='reverse'){var o=shuffle([w[0]].concat(ds.map(function(x){return x[0];})));return {w:w,m:m,q:'Which Arabic word means “'+w[2]+'”?',o:o,a:o.indexOf(w[0])};}
  var o2=shuffle([w[2]].concat(ds.map(function(x){return x[2];})));
  return {w:w,m:m,q:m==='listen'?'Listen. What does it mean?':'What does this mean?',o:o2,a:o2.indexOf(w[2])};}
function vStart(title,words,study,ref){if(!words.length){toast('No words here right now');return;}
  S.vt={title:title,words:words,phase:study?'study':'quiz',i:0,score:0,pick:-1,ref:ref,up:0,down:0};if(!study)S.vt.q=vQ(words[0]);
  trk('quiz_started',{kind:'vocab_trainer',question_count:words.length});render();scrollTo(0,0);if(!study&&S.vt.q.m==='listen')setTimeout(function(){say(S.vt.q.w[0]);},300);}
function vFinish(){var V=S.vt,pct=Math.round(V.score/V.words.length*100);V.phase='end';
  trk('quiz_completed',{kind:'vocab_trainer',score:V.score,question_count:V.words.length,percent:pct,passed:pct>=70});
  save();addXP(V.score*4,V.ref==='learn'?'New words learned':'');if(pct===100){confetti();sfx('win');}}
function viewVocab(){
  if(S.vt)return viewVDrill();
  var all=allWords(),tot=all.length,ln=vLearned(),ms=vMastered(),due=vDue(),hard=vHard(),mode=D.vmode||'mix';
  var wod=all[dayNo()%tot],sel=S.vset||'any';
  var mlab={mix:'Mixed',meaning:'Arabic → meaning',reverse:'Meaning → Arabic',listen:'Listening'};
  return '<div class="lead"><h1>Improve your vocabulary</h1><p>A smart review system: words you know come back less often, words you miss come back sooner. '+tot+' words to learn.</p></div>'+
  '<div class="tiles">'+tile(ln+'/'+tot,'words learned')+tile(ms,'words mastered','right 4 times in a row')+tile(due.length,'due for review today')+tile(hard.length,'hard words')+'</div>'+
  '<div class="vtwo"><div class="panel"><h2>Today</h2>'+(due.length?'<p>'+due.length+' word'+(due.length>1?'s are':' is')+' ready to review.</p><button class="btn primary" data-act="v_review" style="font-size:18px;padding:12px 22px">Start daily review</button>':'<p>✅ All caught up. Learn some new words below.</p>')+
  '<h2 style="margin-top:18px">Learn new words</h2><label class="vsel">Topic <select id="vset">'+'<option value="any">Any topic (in order)</option>'+SETS.map(function(s){var left=vNew(s.id,999).length;return '<option value="'+s.id+'"'+(s.id===sel?' selected':'')+(left?'':' disabled')+'>'+esc(s.title)+' · '+left+' new</option>';}).join('')+'</select></label>'+
  '<div class="btnrow"><button class="btn primary" data-act="v_learn" data-k="10">Learn 10 new words</button><button class="btn" data-act="v_learn" data-k="5">Just 5</button></div></div>'+
  '<div class="panel"><h2>Word of the day</h2><div class="wod"><span class="ar" lang="ar">'+esc(wod[0])+'</span> '+sayBtn(wod[0])+'<b>'+esc(wod[2])+'</b><span class="note">'+esc(wod[1])+'</span></div>'+
  '<h2 style="margin-top:18px">Practice style</h2><div class="chips">'+['mix'].concat(vModes()).map(function(m){return '<button class="chip" data-act="v_mode" data-id="'+m+'" aria-pressed="'+(m===mode)+'">'+mlab[m]+'</button>';}).join('')+'</div>'+
  '<div class="btnrow" style="margin-top:12px"><button class="btn" data-act="v_hard"'+(hard.length?'':' disabled')+'>🔥 Practise hard words'+(hard.length?' ('+Math.min(hard.length,15)+')':'')+'</button><button class="btn" data-act="v_rand"'+(ln>=4?'':' disabled')+'>🎲 Random 15 from words I know</button></div></div></div>'+
  (hard.length?'<div class="panel"><h2>Hard words</h2><div class="lvlist words">'+hard.slice(0,12).map(function(w){return '<div class="lvrow"><div class="lvar"><span class="ar" lang="ar">'+esc(w[0])+'</span>'+sayBtn(w[0])+'</div><div class="lvtl">'+esc(w[1])+'</div><div class="lven">'+esc(w[2])+' <span class="tag warn">missed '+vE(w[0])[2]+'×</span></div></div>';}).join('')+'</div></div>':'')+
  '<h2 class="lvh">Progress by topic</h2><div class="grid vgridt">'+SETS.map(function(s){var u={},n=0,l=0,m=0;s.w.forEach(function(w){if(u[w[0]])return;u[w[0]]=1;n++;var e=vE(w[0]);if(e&&e[0]>0)l++;if(e&&e[0]>=4)m++;});
    return '<button class="card vcard'+(l===n?' done':'')+'" data-act="v_set" data-id="'+s.id+'"><h3>'+esc(s.title)+'</h3><span class="ar" lang="ar">'+esc(s.ar)+'</span>'+pctBar(l/n*100,l===n?'ok':'')+'<span class="n">'+l+' / '+n+' LEARNED · '+m+' MASTERED</span></button>';}).join('')+'</div>';}
function viewVDrill(){var V=S.vt;
  if(V.phase==='study'){var w=V.words[V.i];
    return '<button class="btn back" data-act="v_exit">← Stop</button><div class="q"><div class="prog"><i style="width:'+(V.i/V.words.length*100)+'%"></i></div><div class="panel" style="text-align:center"><div class="tag">'+esc(V.title)+' · word '+(V.i+1)+' of '+V.words.length+'</div>'+
    '<div class="big-ar ar" lang="ar">'+esc(w[0])+' '+sayBtn(w[0])+'</div><p style="font-size:22px;font-weight:800;margin:0">'+esc(w[2])+'</p><p class="note">'+esc(w[1])+'</p>'+
    '<div class="btnrow" style="justify-content:center"><button class="btn primary" data-act="v_snext">'+(V.i===V.words.length-1?'Test me on these words':'Next word')+' <kbd>↵</kbd></button></div><p class="hint">Say the word out loud before you move on.</p></div></div>';}
  if(V.phase==='end'){var pct=Math.round(V.score/V.words.length*100);
    return '<div class="q panel result" style="text-align:center"><h2>'+esc(V.title)+'</h2><div class="score">'+V.score+' / '+V.words.length+'</div><p style="font-weight:800;font-size:20px">'+(pct===100?'Maa shaa Allah, perfect!':pct>=70?'Well done!':'Keep going. These words will come back soon.')+'</p>'+
    '<p class="note">'+V.up+' word'+(V.up===1?'':'s')+' moved up · '+V.down+' to review again today</p>'+
    '<div class="btnrow" style="justify-content:center"><button class="btn primary" data-act="v_again">Test these again</button><button class="btn" data-act="v_exit">Continue</button></div></div>';}
  var q=V.q,ans=V.pick>=0;
  return '<button class="btn back" data-act="v_exit">← Stop</button><div class="q"><div class="prog"><i style="width:'+(V.i/V.words.length*100)+'%"></i></div><div class="panel"><div class="tag">'+esc(V.title)+' · '+(V.i+1)+' of '+V.words.length+'</div><h2 style="margin-top:8px">'+esc(q.q)+'</h2>'+
  (q.m==='meaning'||(q.m==='listen'&&ans)?'<div class="big-ar ar" lang="ar">'+esc(q.w[0])+' '+sayBtn(q.w[0])+'</div>':q.m==='listen'?'<div style="text-align:center;margin:14px 0"><button class="btn primary bigsay" data-act="say" data-t="'+esc(q.w[0])+'">🔊 Play the word</button></div>':'')+
  '<div class="opts">'+q.o.map(function(o,k){var a=AR.test(o),cls='opt'+(a?' ar':'')+(ans&&k===q.a?' right':'')+(ans&&k===V.pick&&k!==q.a?' wrong':'');
    return '<button class="'+cls+'" data-act="v_pick" data-k="'+k+'" data-ns'+(ans?' disabled':'')+(a?' lang="ar"':'')+'><kbd>'+(k+1)+'</kbd><span>'+esc(o)+'</span></button>';}).join('')+'</div>'+
  (ans?'<div class="qfoot'+(V.pick===q.a?' ok':' no')+'"><div class="why">'+(V.pick===q.a?'✅ Correct. ':'❌ Not quite. ')+'<span class="ar" lang="ar">'+esc(q.w[0])+'</span> ('+esc(q.w[1])+') means “'+esc(q.w[2])+'”.</div><button class="btn primary" data-act="v_next">'+(V.i===V.words.length-1?'See result':'Next word')+' →</button></div>':'<p class="hint">Tip: press 1–'+q.o.length+' to answer</p>')+'</div></div>';}

/* ---------- my progress ---------- */
function histDays(n){var a=[];for(var i=n-1;i>=0;i--){var k=today(i),v=(D.hist&&D.hist[k])||0;a.push([k,v,D.days.indexOf(k)>=0]);}return a;}
function viewProgress(){
  var U=window.LisaanUser,l=level(),tot=allWords().length,h=histDays(14),mx=Math.max.apply(null,h.map(function(x){return x[1];}).concat([GOAL]));
  var qzPass=0;for(var k in D.qz)if(D.qz[k]>=70)qzPass++;
  var setPass=SETS.filter(function(s){return (D.sets[s.id]||0)>=80;}).length,lvPass=LV.filter(function(x){return ((D.lv||{})[x.id]||0)>=70;}).length;
  var row=function(lbl,n,of,act){return '<div class="prow"><span>'+lbl+'</span>'+pctBar(of?n/of*100:0,n>=of?'ok':'')+'<b>'+n+' / '+of+'</b>'+(act?'<button class="linkbtn" data-act="p_go" data-id="'+act+'">Open</button>':'<span></span>')+'</div>';};
  var weak=gWeak(3),due=vDue().length,hard=vHard().length;
  return '<div class="lead"><h1>My progress</h1><p>'+(U?'Everything you do is saved to your own account.':'You are learning as a guest on this device.')+'</p></div>'+
  '<div class="panel acctbox">'+(U?'<p>👤 Signed in as <b>'+esc(U.name||U.email||'you')+'</b>. Only you can see this progress, and it follows you to any phone or computer you sign in on.</p><button class="btn" data-act="p_acct">Account</button>':
    '<p>👤 Sign in or create a free account so your progress is saved to <b>your own</b> account. Each person who signs in sees only their own progress.</p><button class="btn primary" data-act="p_acct">Sign in or create account</button>')+'</div>'+
  voicePanel()+'<div class="tiles">'+tile(D.xp,'XP')+tile(LEVELS[l][1],'level')+tile('🔥 '+streak(),'day streak')+tile(D.days.length,'days learned')+'</div>'+
  '<div class="panel"><h2>Last 14 days</h2><div class="chart" role="img" aria-label="XP earned on each of the last 14 days">'+h.map(function(x,i){var p=x[1]?Math.max(6,x[1]/mx*100):(x[2]?6:0);var d=x[0].split('-');
    return '<div class="col'+(x[1]>=GOAL?' met':'')+'" title="'+x[0]+': '+x[1]+' XP"><i style="height:'+p+'%"></i><span>'+(i===13?'Today':d[2])+'</span></div>';}).join('')+'</div><p class="note">Daily goal: '+GOAL+' XP. Gold bars mean the goal was met.</p></div>'+
  '<div class="panel"><h2>Course progress</h2>'+
    row('📖 Lessons completed',doneCount(),LESSONS.length,'learn')+
    row('✍️ Grammar topics mastered',gMastered(),GRAM.length,'grammar')+
    row('🧠 Words learned',vLearned(),tot,'vocab')+
    row('⭐ Words mastered',vMastered(),tot,'vocab')+
    row('🗂️ Word sets passed (80%+)',setPass,SETS.length,'words')+
    row('🎯 Library quizzes passed',qzPass,QZ.length,'quiz')+
    row('📶 Level quizzes passed',lvPass,LV.length,'levels')+
    row('🧸 Kids levels finished',kgDone(),100,'kids')+
    row('🏆 Badges earned',BADGES.filter(function(b){return b[3]();}).length,BADGES.length,'rewards')+'</div>'+
  '<div class="vtwo"><div class="panel"><h2>Grammar to work on</h2>'+(weak.length?'<ul>'+weak.map(function(t){return '<li><button class="linkbtn" data-act="p_go" data-id="grammar:'+t.id+'">'+t.icon+' '+esc(t.title)+'</button> · best '+gStat(t.id).b+'%</li>';}).join('')+'</ul>':'<p>No weak topics yet. Start the daily workout to find them.</p>')+
    '<p>'+(D.gmiss||[]).length+' mistakes waiting to be fixed.</p><button class="btn" data-act="p_go" data-id="grammar">Go to grammar</button></div>'+
  '<div class="panel"><h2>Vocabulary</h2><p>'+due+' word'+(due===1?'':'s')+' due for review today · '+hard+' hard word'+(hard===1?'':'s')+'.</p><button class="btn'+(due?' primary':'')+'" data-act="p_go" data-id="vocab">'+(due?'Review now':'Go to vocabulary')+'</button></div></div>';}

/* ---------- actions ---------- */
function impAct(a,el,id,k){var G=S.gd,V=S.vt;
  if(a==='g_topic'){S.gtopic=id;S.gd=null;scrollTo(0,0);}
  else if(a==='g_back'){S.gtopic=null;}
  else if(a==='g_drill'){gTopicDrill(id);return;}
  else if(a==='g_mix'){gMixDrill(id);return;}
  else if(a==='g_pick'&&G&&!G.checked){G.pick=k;gAnswer(k===G.items[G.i].a);}
  else if(a==='g_tile'&&G&&!G.checked){var it=G.items[G.i];if(!it.tiles[k].used){it.tiles[k].used=true;it.built.push(k);}}
  else if(a==='g_unt'&&G&&!G.checked){var it2=G.items[G.i],ti=it2.built.splice(k,1)[0];it2.tiles[ti].used=false;}
  else if(a==='g_clear'&&G&&!G.checked){var it3=G.items[G.i];it3.built=[];it3.tiles.forEach(function(x){x.used=false;});}
  else if(a==='g_check'&&G&&!G.checked){var it4=G.items[G.i];if(it4.built.length<it4.words.length)return;gAnswer(it4.built.map(function(ti){return it4.tiles[ti].w;}).join(' ')===it4.words.join(' '));}
  else if(a==='g_next'&&G&&G.checked){if(G.i===G.items.length-1)gFinish();else{G.i++;G.pick=-1;G.checked=false;}scrollTo(0,0);}
  else if(a==='g_again'&&G){var ref=G.ref;S.gd=null;if(ref.indexOf('mix:')===0)gMixDrill(ref.slice(4));else gTopicDrill(ref);return;}
  else if(a==='g_rule'&&G){S.gtopic=G.ref;S.gd=null;scrollTo(0,0);}
  else if(a==='g_exit'){S.gd=null;}
  else if(a==='v_review'){vStart('Daily review',shuffle(vDue()).slice(0,20),false,'review');return;}
  else if(a==='v_learn'){var sv=document.getElementById('vset');S.vset=sv?sv.value:'any';var nw=vNew(S.vset,k||10);vStart('New words',nw,true,'learn');return;}
  else if(a==='v_set'){S.vset=id;var nw2=vNew(id,10);if(nw2.length)vStart('New words',nw2,true,'learn');else{var st=SETS.filter(function(s){return s.id===id;})[0];vStart(st.title+' review',shuffle(st.w).slice(0,15),false,'set');}return;}
  else if(a==='v_hard'){vStart('Hard words',vHard().slice(0,15),false,'hard');return;}
  else if(a==='v_rand'){vStart('Words I know',shuffle(allWords().filter(function(w){var e=vE(w[0]);return e&&e[0]>0;})).slice(0,15),false,'rand');return;}
  else if(a==='v_mode'){D.vmode=id;save();}
  else if(a==='v_snext'&&V){if(V.i===V.words.length-1){V.phase='quiz';V.i=0;V.words=shuffle(V.words);V.q=vQ(V.words[0]);render();if(V.q.m==='listen')say(V.q.w[0]);return;}V.i++;render();say(V.words[V.i][0]);return;}
  else if(a==='v_pick'&&V&&V.pick<0){V.pick=k;var ok=k===V.q.a,was=(vE(V.q.w[0])||[0])[0];vMark(V.q.w,ok);if(ok){V.score++;V.up++;sfx('ok');}else{V.down++;sfx('bad');}
    trk('quiz_answered',{kind:'vocab_trainer',question_number:V.i+1,correct:ok});save();if(ok&&was<4&&vE(V.q.w[0])[0]>=4)toast('Word mastered: '+V.q.w[2]);}
  else if(a==='v_next'&&V&&V.pick>=0){if(V.i===V.words.length-1)vFinish();else{V.i++;V.pick=-1;V.q=vQ(V.words[V.i]);render();scrollTo(0,0);if(V.q.m==='listen')say(V.q.w[0]);return;}}
  else if(a==='v_again'&&V){vStart(V.title,shuffle(V.words),false,V.ref);return;}
  else if(a==='v_exit'){S.vt=null;}
  else if(a==='p_acct'){var b=document.getElementById('acctBtn');if(b)b.click();return;}
  else if(a==='p_go'){var p=(id||'').split(':');try{location.hash=p[0];}catch(e){}S.view=p[0];S.lesson=null;S.set=null;S.quiz=null;S.game=null;S.kgame=null;S.lvl=null;S.gd=null;S.vt=null;S.gtopic=p[1]||null;scrollTo(0,0);}
  render();}
addEventListener('keydown',function(e){if(e.target.closest&&e.target.closest('input,textarea,select'))return;var G=S.gd,V=S.vt,n=+e.key,b;
  if(G&&!G.end){if(n>=1&&n<=4&&!G.checked)b=document.querySelector('[data-act=g_pick][data-k="'+(n-1)+'"]');else if(e.key==='Enter')b=document.querySelector('[data-act=g_next],[data-act=g_check]');}
  else if(V&&V.phase!=='end'){if(n>=1&&n<=4&&V.pick<0)b=document.querySelector('[data-act=v_pick][data-k="'+(n-1)+'"]');else if(e.key==='Enter')b=document.querySelector('[data-act=v_next],[data-act=v_snext]');}
  if(b&&!b.disabled){e.preventDefault();b.click();}});
addEventListener('lisaan:user',function(){if(S.view==='progress'&&!S.quiz)render();});

/* ---------- state and routing ---------- */
var VIEWS=['learn','grammar','vocab','levels','words','quiz','kids','library','rewards','progress'];
var S={view:'learn',lesson:null,set:null,quiz:null,game:null,kgame:null,gd:null,vt:null,gtopic:null};
function route(){var h=location.hash.replace('#','');S.view=VIEWS.indexOf(h)>=0?h:'learn';S.lesson=null;S.set=null;S.quiz=null;S.game=null;S.kgame=null;S.lvl=null;S.gd=null;S.vt=null;S.gtopic=null;render();}
addEventListener('hashchange',function(){route();scrollTo(0,0);});
document.querySelector('nav').addEventListener('click',function(e){var a=e.target.closest('a');if(!a)return;e.preventDefault();var v=a.getAttribute('data-v');
  try{location.hash=v;}catch(err){}S.view=v;S.lesson=null;S.set=null;S.quiz=null;S.game=null;S.kgame=null;S.lvl=null;S.gd=null;S.vt=null;S.gtopic=null;render();scrollTo(0,0);});

/* ---------- quiz engine ---------- */
function makeQ(q){var right=q.o[0],o=shuffle(q.o);return {q:q.q,big:q.big||'',o:o,a:o.indexOf(right),why:q.why||''};}
function vocabQ(pool,w){
  if(Math.random()<.5)return makeQ({q:'What does this word mean?',big:w[0],o:[w[2]].concat(sample(pool,3,w).map(function(x){return x[2];})),why:w[0]+' ('+w[1]+') means "'+w[2]+'".'});
  return makeQ({q:'Which word means "'+w[2]+'"?',o:[w[0]].concat(sample(pool,3,w).map(function(x){return x[0];})),why:w[0]+' ('+w[1]+') means "'+w[2]+'".'});
}
function trk(n,p){try{window.__lovableEvents&&window.__lovableEvents.track&&window.__lovableEvents.track('project.'+n,p);}catch(e){}}
function startQuiz(title,qs,kind,ref){trk('quiz_started',{kind:String(kind),question_count:qs.length});S.quiz={title:title,qs:qs,i:0,score:0,pick:-1,kind:kind,ref:ref,end:false};render();scrollTo(0,0);}
function viewQuiz(){
  var Q=S.quiz;
  if(Q.end){
    var pct=Math.round(Q.score/Q.qs.length*100);
    if(pct===100&&!Q.cf){Q.cf=1;setTimeout(confetti,50);sfx('win');}
    return '<div class="q panel result" style="text-align:center"><h2>'+esc(Q.title)+'</h2><div class="score">'+Q.score+' / '+Q.qs.length+'</div>'+
    '<p style="font-weight:800;font-size:20px">'+(pct===100?'Maa shaa Allah, perfect!':pct>=70?'Well done!':'Keep going. Review and try again.')+'</p>'+
    '<div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap"><button class="btn primary" data-act="quizAgain">Try again</button><button class="btn" data-act="quizExit">Continue</button></div></div>';
  }
  var q=Q.qs[Q.i],ans=Q.pick>=0;
  return '<div class="q"><div class="prog"><i style="width:'+(Q.i/Q.qs.length*100)+'%"></i></div>'+
  '<div class="panel"><div class="tag">'+esc(Q.title)+' · '+(Q.i+1)+' of '+Q.qs.length+'</div><h2 style="margin-top:8px">'+mix(q.q)+'</h2>'+
  (q.big?'<div class="big-ar ar" lang="ar">'+esc(q.big)+' '+sayBtn(q.big)+'</div>':'')+
  '<div class="opts">'+q.o.map(function(o,k){var kb='<kbd>'+(k+1)+'</kbd>';var cls='opt'+(AR.test(o)?' ar':'')+(ans&&k===q.a?' right':'')+(ans&&k===Q.pick&&k!==q.a?' wrong':'');
    return '<button class="'+cls+'" data-act="pick" data-k="'+k+'"'+(ans?' disabled':'')+(AR.test(o)?' lang="ar"':'')+'>'+kb+'<span>'+esc(o)+'</span></button>';}).join('')+'</div>'+
  (ans?'<div class="qfoot'+(Q.pick===q.a?' ok':' no')+'"><div class="why">'+(Q.pick===q.a?'✅ Correct. ':'❌ Not quite. ')+mix(q.why)+'</div><button class="btn primary" data-act="next">'+(Q.i===Q.qs.length-1?'See result':'Next question')+' →</button></div>':'<p class="hint">Tip: press 1–'+q.o.length+' to answer</p>')+'</div></div>';
}
function finishQuiz(){
  var Q=S.quiz,pct=Math.round(Q.score/Q.qs.length*100),xp=Q.score*10,msg='';trk('quiz_completed',{kind:String(Q.kind),score:Q.score,question_count:Q.qs.length,percent:pct,passed:pct>=70});
  if(Q.kind==='lesson'){if(pct>=66&&!D.done[Q.ref]){D.done[Q.ref]=1;xp+=20;msg='Lesson complete';}}
  else if(Q.kind==='level'){D.lv=D.lv||{};if(pct>(D.lv[Q.ref]||0))D.lv[Q.ref]=pct;}
  else if(Q.kind==='set'){if(pct>(D.sets[Q.ref]||0))D.sets[Q.ref]=pct;}
  else if(Q.kind==='lib'){if(pct>(D.qz[Q.ref]||0))D.qz[Q.ref]=pct;if(pct>=70)msg='Quiz passed';}
  else if(Q.kind==='mixed'&&pct===100){D.perfect=(D.perfect||0)+1;xp+=30;msg='Perfect score';}
  Q.end=true;save();addXP(xp,msg);
}

