  SETS.forEach(function(s){add(s.title+': read the Arabic','Word quizzes',function(r){return gVocab(s.w,r,8,0);});add(s.title+': find the Arabic','Word quizzes',function(r){return gVocab(s.w,r,8,1);});});
  var i;
